INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('cr-107476manualaccesibilidad', '10.7476/manual-accesibilidad', 'Manual de accesibilidad en libros digitales', NULL, '["Ramalho, Amanda de Souza","Castelhano, Giovanna Brito","Andrade, Antônio Ursine Magalhães de","Pinto, Gabriella Nair Figueiredo Noronha","Carvalho, Sofia Rodrigues Santos","Santos, Thales Rodrigues dos","Chaves, Amanda Rabelo","Lima, Caroliny Procopio"]', 'EdUEMG', 'México', 'Red SciELO', 'scielo-network', 2026, NULL, 'other', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, '', '[]', '10.7476/manual-accesibilidad', '9786076461747', 'https://doi.org/10.7476/manual-accesibilidad', NULL, NULL, NULL, NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('cr-107476manualacessibilidade', '10.7476/manual-acessibilidade', 'Manual de acessibilidade em livros digitais', NULL, '["Ramalho, Amanda de Souza","Castelhano, Giovanna Brito","Andrade, Antônio Ursine Magalhães de","Pinto, Gabriella Nair Figueiredo Noronha","Carvalho, Sofia Rodrigues Santos","Santos, Thales Rodrigues dos","Chaves, Amanda Rabelo","Lima, Caroliny Procopio"]', 'EdUEMG', 'Brasil', 'Red SciELO', 'scielo-network', 2026, NULL, 'other', 'book', 'social-sciences', 'Ciencias Sociales y Educación', NULL, 'O Manual de acessibilidade em livros digitais apresenta fundamentos, normas e orientações práticas para a produção de publicações digitais acessíveis. A obra aborda o contexto histórico e legal da acessibilidade, a importância dos livros digitais acessíveis para a democratização do conhecimento e as principais tecnologias assistivas e diretrizes que orientam a criação de conteúdos acessíveis. Voltado a autores, editores, revisores, designers, diagramadores e demais profissionais do livro, o manual oferece instruções para o planejamento e a elaboração de arquivos acessíveis nos formatos Word, PDF e EPUB, incluindo listas de verificação para apoiar as diferentes etapas da produção editorial. A publicação contribui para a disseminação de boas práticas de acessibilidade digital e para a promoção do acesso à leitura e à informação por todas as pessoas.', '[]', '10.7476/manual-acessibilidade', '9786586832693', 'https://doi.org/10.7476/manual-acessibilidade', NULL, NULL, NULL, NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('oa-W120959412', 'https://openalex.org/W120959412', 'Transformação e persistência: antropologia da alimentação e nutrição em uma sociedade indígena amazônica', NULL, '["Maurício Soares Leite"]', 'Editora FIOCRUZ', 'Brasil', 'Red SciELO', 'scielo-network', 2007, '2007-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'O livro traz a experiência do autor em sua convivência com os Wari’ (ou Pacaás Novos), povo indígena mais numeroso no estado de Rondônia, com cerca de 2.700 indivíduos. Apresenta, em linguagem precisa e agradável, uma abrangente descrição das condições de alimentação e nutrição locais, levando em consideração a especificidade cultural das comunidades amazônicas. A obra demonstra o quão importante é não prescindir de cuidadosa contextualização dos achados no conjunto das práticas nativas e das idéias que as orientam, seja qual for o campo sob investigação.', '["indigenous peoples","Amazonian communities","traditional food practices","Rondônia"]', '10.7476/9788575412930', '9788575412930', 'https://doi.org/10.7476/9788575412930', 'https://books.scielo.org/id/q/pdf/leite-9788575412930.pdf', NULL, NULL, NULL, 36, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('oa-W1580318844', 'https://openalex.org/W1580318844', 'História social da tuberculose e do tuberculoso: 1900-1950', NULL, '["Cláudio Bertolli Filho"]', 'Editora FIOCRUZ', 'Brasil', 'Red SciELO', 'scielo-network', 2001, '2001-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A intenção do autor é estudar o doente, investigando seus sentimentos e seu papel no contexto da tuberculose. Para tanto, ele desvenda a doença, os especialistas, as instituições e as relações sociais relacionadas à peste branca no Brasil nos primeiros cinqüenta anos do século passado. Interessante para os profissionais de saúde, historiadores e todos os interessados pelo enfoque humano na história da tuberculose, este livro discute a construção do ideário sobre a doença no Brasil, analisando comportamentos individuais e coletivos. A utilização de fontes documentais diversas, como obras literárias e os prontuários médicos, é importante, na medida em que constituem peças fundamentais na composição da história social da doença e do doente e de todos os envolvidos na tragédia regida pela tuberculose.', '["tuberculosis","social history of disease","tuberculosis patients","history of medicine","medical institutions","interpersonal relationships","medical records","Brazil"]', '10.7476/9788575412886', '9788575412886', 'https://doi.org/10.7476/9788575412886', 'https://books.scielo.org/id/4/pdf/bertolli-9788575412886.pdf', NULL, NULL, NULL, 53, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('oa-W2476376138', 'https://openalex.org/W2476376138', 'O léxico em foco: múltiplos olhares', NULL, '[]', 'Editora UNESP', 'Brasil', 'Red SciELO', 'scielo-network', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '[RETIRADO/WITHDRAWN] O léxico é objeto de interesse de muitos pesquisadores das áreas de Letras e Linguística. No Brasil, diversas Universidades desenvolvem pesquisas sobre essa matéria e a UNESP-Universidade Estadual Paulista se encontra entre elas, possuindo uma tradição consolidada na área e contando com vários grupos de pesquisa sobre o léxico da língua geral e das chamadas línguas de especialidade (domínios técnicos, científicos e especializados). É nesse âmbito e com esse sentido que nasce esta obra. A ideia é a de reunir trabalhos que divulguem as pesquisas desenvolvidas por pesquisadores da UNESP, fornecendo, assim, elementos para uma reflexão sobre os caminhos que os estudos lexicais trilham hoje em nossa Universidade. É também objetivo desta obra dar oportunidade a alunos de pós-graduação para exporem os principais resultados de suas investigações científicas, desenvolvidas sob o olhar crítico de seus orientadores.', '["lexical study","specialized lexicon","Brazilian Portuguese","lexicology"]', '10.7476/9788579831256', '9788579831256', 'https://doi.org/10.7476/9788579831256', NULL, NULL, NULL, NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
