xcluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('oa-W2489719736', 'https://openalex.org/W2489719736', 'SciELO – 15 Years of Open Access: an analytic study of Open Access and scholarly communication', NULL, '[]', 'UNESCO', 'Internacional', 'Red SciELO', 'scielo-network', 2014, '2014-01-01', 'en', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '', '["open access","scholarly communication","SciELO","open access journals","scholarly publishing","institutional repositories"]', '10.7476/9789230012373', '9789230012373', 'https://doi.org/10.7476/9789230012373', 'https://scielo.org/local/File/book.pdf', NULL, NULL, NULL, 36, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('oa-W2490437527', 'https://openalex.org/W2490437527', 'SciELO – 15 Anos de Acesso Aberto: um estudo analítico sobre Acesso Aberto e comunicação científica', NULL, '[]', 'UNESCO', 'Internacional', 'Red SciELO', 'scielo-network', 2014, '2014-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'This research objects to analyze how technological innovation and management are presented in works that discuss the subject of coffee production in the Brazilian savanna, known as "Cerrado Mineiro" located in Minas Gerais State.The analysis is based on a bibliometric data survey developed by the scientific journal Coffee Science and SciELO, from 2000 to 2015.We seek to verify the amount of scientific articles about coffee and coffee growing that, somehow present in their summaries the key words innovation, technology, management, Cerrado Mineiro and Cerrado Mineiro region, also to investigate the focus given to the technological innovation, based of the following characteristics: mechanical innovations, physico-chemical, biological and agronomic practices.As a result of this survey, nine abstracts of scientific articles were mapped: six of them in the scientific journal Coffee Science and three from SciELO website.From these summaries, five presented in their research the subsequent innovation aspects: physical-chemistry and agronomic (soil fertilization), physico-chemical and mechanical (maturation uniformity and harvest), physico-chemical and biological (fungi and grain humidity), mechanical (a summary about repetition of the harvest method and another about soil compaction); two abstracts referred to production management and two about production differentiation and costs (economic approach).From the examination of the abstracts it was observed a interdependence relationship between technological innovations and its effects to the increasing of productivity, production costs reduction, improvement in the quality of the grain and improvement of the environmental performance.In summary, this bibliometric research acted as a reference to the coffee growing thematic, since it is a way of fostering optimization with previously developed researches and, thus, opportunities or potential points in fields, themes or not investigated objects.In addition, it was observed with this survey data, that the technological development and innovation research are important to enhance the management of resources, so as the investments made by the producer in order to monitor more effectively the production management.', '["coffee production","Cerrado Mineiro","technological innovation","agricultural management","soil fertilization","harvesting methods","soil compaction","grain quality","production costs","open access","SciELO"]', '10.7476/9789237012376', NULL, 'https://doi.org/10.7476/9789237012376', 'https://old.scielo.org/local/File/livro.pdf', NULL, NULL, NULL, 43, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('oa-W3196006158', 'https://openalex.org/W3196006158', 'Prospectiva para ciência, tecnologia e inovação', NULL, '["Ian Douglas Miles","Ozcan Sarıtas","Alexander Sokolov"]', 'Editora FIOCRUZ', 'Brasil', 'Red SciELO', 'scielo-network', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Tradução de obra lançada em 2016, o livro preenche uma lacuna na literatura relacionada aos chamados estudos do futuro, em âmbitos nacional e internacional. Escrito por três professores da Escola Superior de Economia (HSE) de Moscou, na Rússia, o volume pretende ampliar o conjunto de atores engajados na política de ciência e inovação, contribuindo para planejadores, gestores, formadores de políticas e tomadores de decisão. Publicada originalmente sob o título Foresight for Science, Technology and Innovation, a obra foi traduzida por Valdir Ermida, chefe do Serviço de Planejamento do Instituto Nacional de Infectologia Evandro Chagas (INI/Fiocruz).', '["foresight","science policy","technology policy","innovation policy","science, technology and innovation","policy planning","decision-making"]', '10.7476/9786557081112', '9786557080375', 'https://doi.org/10.7476/9786557081112', NULL, NULL, NULL, NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('oa-W4230392535', 'https://openalex.org/W4230392535', 'Raízes históricas da medicina ocidental', NULL, '[]', 'Editora Fap-Unifesp', 'Brasil', 'Red SciELO', 'scielo-network', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '[RETIRADO/WITHDRAWN] Este livro tem por objetivo oferecer ao leitor um largo panorama da evolução do cuidado com a saúde, mostrando a multiplicidade e variedade de legados culturais que confluíram na formação do que hoje conhecemos por medicina. Fruto de grande pesquisa de um médico experiente e com vastas leituras de filosofia e história, o volume apresenta em sequência cronológica uma síntese dos preceitos e práticas de diversos povos em sua luta por conhecer e combater as doenças. Desde as remotas civilizações da Mesopotâmia e do Nilo até a Helênica, berço da doutrina hipocrática; desde fenícios, persas, hebreus e etruscos até a Europa Medieval e Islâmica, contemplam-se todas as etapas e facetas do processo que, na Renascença e no Século das Luzes, ensejou a transformação das artes médicas numa ciência moderna. Uma obra de consulta útil tanto para o leigo interessado em conhecer a genealogia da ciência médica como para o estudante, o docente e o profissional que queira ampliar seus horizontes para além dos limites de sua especialidade.', '["history of medicine","Western medicine","ancient medicine","Mesopotamian medicine","Egyptian medicine","ancient Greek medicine","Persian medicine","medieval medicine","Islamic medicine","Renaissance medicine","Enlightenment medicine","medical sciences"]', '10.7476/9788561673659', '9788561673659', 'https://doi.org/10.7476/9788561673659', NULL, NULL, NULL, NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('oa-W4230934386', 'https://openalex.org/W4230934386', 'O retrato', NULL, '["Osvaldo Peralva"]', 'Centro Edelstein', 'Brasil', 'Red SciELO', 'scielo-network', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O retrato é um dos mais importantes e contundentes relatos políticos brasileiros do século XX. Fervoroso militante e membro da cúpula do Partido Comunista Brasileiro, o jornalista e escritor Osvaldo Peralva foi enviado a Moscou em 1953 para estudar. Lá constatou que a utopia bolchevista havia se convertido em pesadelo totalitário. Três anos depois, quando voltou ao Brasil, percebeu que o PCB reproduzia em escala provinciana e farsesca tanto o terrorismo ideológico quanto o culto à personalidade que prevaleciam na URSS. O livro é a história da trajetória de Peralva no Partido Comunista, desde a apaixonada adesão na juventude até a traumática ruptura no final dos anos 1950. Com a argúcia de um repórter e a verve de um romancista, ele transforma suas memórias em arrebatadora narrativa sobre os bastidores sinistros do comunismo na União Soviética e os descaminhos do PCB, traçando retratos implacáveis de seus líderes, como Luís Carlos Prestes e Carlos Marighella.', '["Brazilian Communist Party","Brazilian communism","Soviet Union","ideological terrorism","cult of personality","Luís Carlos Prestes","Carlos Marighella","political memoirs","Communist Party leadership","1950s Brazil"]', '10.7476/9788579820151', '9788579820151', 'https://doi.org/10.7476/9788579820151', NULL, NULL, NULL, NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('oa-W7214227814', 'https://openalex.org/W7214227814', 'Foucault, a arqueologia e As palavras e as coisas 50 anos depois', NULL, '["Ivan Domingues"]', 'Editora UFMG', 'Brasil', 'Red SciELO', 'scielo-network', 2020, '2020-10-26', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] Tendo frequentado os cursos de Foucault no Collège de France entre os anos de 1981 e 1983, em quem vê o interlocutor oculto de sua tese de doutorado defendida mais tarde na Sorbonne, Ivan Domingues faz neste livro uma análise extensa e acurada da obra que o inspirou, As palavras e as coisas – uma arqueologia das ciências humanas. Ao mesmo tempo, realiza uma ansiada homenagem ao eminente filósofo, na ocasião dos 50 anos da obra, lançada em 1966 com grande repercussão na França e pelo mundo afora, inclusive no Brasil.', '["Michel Foucault","The Order of Things","Collège de France","reception of Foucault","history of knowledge"]', '10.7476/9786558580003', '9786558580003', 'https://doi.org/10.7476/9786558580003', NULL, NULL, NULL, NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-225y7', '225y7', 'Função do discurso em administração escolar no Brasil', NULL, '["Graziela Zambão Abdian"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Uma problemática organiza a estrutura deste livro: quais funções tem exercido o discurso de Administração Escolar na produção do conhecimento, especialmente o conceito de Administração Escolar? Graziela Zambão Abdian analisa a construção histórica desse discurso e constata que o pesquisador, ao reproduzir o conceito de Administração Escolar como mediação para o alcance de fins determinados, acaba por modelar a escola e seu cotidiano, por mais que variem o referencial ou os procedimentos de pesquisa Em seguida, a autora analisa a trajetória de sua própria pesquisa para compreender a formação da subjetividade e trazer os limites impostos pelas regras de formação postas em prática. Por fim, busca construir novas ferramentas metodológicas para serem discutidas por pesquisadores na área. Esse percurso permitiu a autora constatar que o discurso impede o pesquisador de fazer o conhecimento se diferenciar e que é necessário apreender a lógica da multiplicidade e da heterogeneidade do cotidiano a partir de suas próprias regras, que podem não ser as melhores, mas são diferentes daquelas pelas quais fomos governados até o momento.', '["school management","discourse analysis","knowledge production","researcher subjectivity","research methodology","school everyday life"]', '10.7476/9786557145586', '9786557145586', 'https://books.scielo.org/id/225y7', 'https://books.scielo.org/id/225y7/pdf/abdian-9786557145586.pdf', NULL, 'https://books.scielo.org/id/225y7/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-22qtc', '22qtc', 'Além das redes de colaboração: internet, diversidade cultural e tecnologias do poder', NULL, '["Nelson De Luca Pretto","Sérgio Amadeu da Silveira"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Discute o aprisionamento das subjetividades, os riscos e exageros do controle do conhecimento e da informática de dominação. Alerta para o fato de que a tentativa de ampliação do compartilhamento é combatida tanto pela expansão da propriedade sobre a cultura quanto pela ideologia da neutralidade tecnológica. Mostra a contradição entre as possibilidades de criação e disseminação cultural inerentes às redes informacionais e as tentativas de manter a interatividade sob o controle do capitalismo industrial.', '["internet","cultural diversity","technologies of power","knowledge control","cultural property","technological neutrality","information networks","subjectivity","industrial capitalism","cultural diffusion","interactivity"]', '10.7476/9788523208899', '9788523208899', 'https://books.scielo.org/id/22qtc', 'https://books.scielo.org/id/22qtc/pdf/pretto-9788523208899.pdf', NULL, 'https://books.scielo.org/id/22qtc/cover/cover_thumbnail.jpeg', NULL, 29, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-22r3s', '22r3s', 'Retórica na educação: a arte de convencer e de persuadir em contextos formativos', NULL, '["André Luiz Gaspari Madureira","Cristina Manuela Sá"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra apresenta uma série de reflexões sobre as condições sociais e históricas que colocam a retórica numa relação transversal com a educação. Durante esse percurso, é demarcado o papel fundante dos estudos retóricos no fazer pedagógico, o que justifica a pertinência de regaste e introdução no âmbito educacional. Obra necessária para professores, educandos, pedagogos e curiosos sobre o uso da retórica na educação.', '["rhetoric in education","persuasion","teaching practice","rhetoric and history"]', '10.7476/9786588211984', '9786588211984', 'https://books.scielo.org/id/22r3s', 'https://books.scielo.org/id/22r3s/pdf/madureira-9786588211984.pdf', NULL, 'https://books.scielo.org/id/22r3s/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-22zbb', '22zbb', 'Micropoderes, macroviolências', NULL, '["Suzana Varjão"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Estudo comparativo das coberturas policiais feitas pelos jornais A Tarde, Correio da Bahia e Tribuna da Bahia, analisando a produção e a reprodução social da violência no cotidiano baiano. Mostra a hierarquia dentro dos assuntos da mídia e coloca em discussão o papel das empresas jornalísticas e dos profissionais de jornalismo na sociedade. Revela também a atmosfera de uma cidade ainda dividida entre casas-grandes e senzalas que a autora chama de bolhas e vãos.', '["media violence","role of journalists","newspaper companies","social inequality"]', '10.7476/9788523209193', '9788523209193', 'https://books.scielo.org/id/22zbb', 'https://books.scielo.org/id/22zbb/pdf/varjao-9788523209193.pdf', NULL, 'https://books.scielo.org/id/22zbb/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-23pcw', '23pcw', 'Educação, saúde e esporte: novos desafios à Educação Física', NULL, '["Cristiano de Sant’anna Bahia","Juarez Vieira do Nascimento","Gelcemar Oliveira Farias"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '"A coletânea contempla capítulos que discutem a Educação Física a partir dos pressupostos da Educação, da Saúde e do Esporte, enquanto importante desafio do momento atual e diante dos avanços e das mudanças que se consolidaram na formação inicial em Educação Física. A obra convida a todos para a realização de futuras investigações, no sentido de concentrar esforços para o fortalecimento de núcleos de estudos e a sistematização de linhas de pesquisa."', '["physical education","initial teacher education","physical education teacher training","health education","sport","research lines"]', '10.7476/9788574554907', '9788574554907', 'https://books.scielo.org/id/23pcw', 'https://books.scielo.org/id/23pcw/pdf/farias-9788574554907.pdf', NULL, 'https://books.scielo.org/id/23pcw/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-23wpg', '23wpg', 'Atlas de dermatologia em povos indígenas', NULL, '["Douglas Rodrigues","Jane Tomimori","Marcos C. Floriano","Sofia Beatriz Machado de Mendonça"]', 'Editora Fap-Unifesp', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Essa publicação vem suprir a necessidade de materiais didáticos específicos sobre a atenção à saúde de povos indígenas que vivem na zona rural, isolados ou em áreas de difícil acesso. Nessas circunstâncias, a alta prevalência das doenças de pele, com características de baixa mortalidade, mas com impacto na qualidade de vida, tem feito parte da realidade dessas populações e, em geral, é um problema relegado a segundo plano.O objetivo deste livro é colaborar com o dia a dia dos profissionais de saúde que trabalham na atenção básica, especialmente em regiões em que a presença do dermatologista nem sempre é possível.', '["dermatology","indigenous peoples","skin diseases","rural health","isolated populations","hard-to-reach areas","primary care","quality of life","dermatological atlas"]', '10.7476/9788561673680', '9788561673680', 'https://books.scielo.org/id/23wpg', 'https://books.scielo.org/id/23wpg/pdf/rodrigues-9788561673680.pdf', NULL, 'https://books.scielo.org/id/23wpg/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2463f', '2463f', 'Rastro, hesitação e memória: o tempo na poesia de Yves Bonnefoy', NULL, '["Pablo Simpson"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'prEFácioYves Bonnefoy foi um dos poetas franceses mais importantes da segunda metade do século XX.Sua obra poética, que se inicia em 1946 com Traité du pianiste e Le Cœur-espace, pode ser situada, em um primeiro momento, a partir do diálogo com o surrealismo, de que se afastaria em 1947, mas cuja noção de sonho retomou em suas narrativas publicadas a partir dos anos 1970: L''Arrière-pays e Rue Traversière.Situa-se, além disso, face ao existencialismo de Jean Wahl.Leitor de Plotino, Kierkegaard e Léon Chestov, importante crítico de arte e da obra de Baudelaire, além de tradutor de Shakespeare, Yves Bonnefoy traz desde os ensaios de L''Improbable, de 1959, uma preocupação com o que chamaria de "presença" fundamental para a compreensão de seu projeto poético.Ela designaria, muitas vezes, uma oposição ao conceito filosófico e à linguagem.Traria o apelo a uma "realidade obscura", enigmática.Nesse sentido, a poesia pretenderia uma intuição do absoluto, uma esperança investida de uma vocação ontológica não sem relação com o questionamento heideggeriano.Este estudo pretende investigar as relações entre poesia e tempo.Há nos poemas de Anti-Platon e Du Mouvement et de l''immobilité de Douve, tanto quanto nos ensaios de L''Improbable, a condenação de um inteligível abstrato em virtude do esquecimento do tempo.A poesia repercutiria uma tensão entre interioridade conceitual e exterioridade.As palavras do poema evocariam um apagamento: rastro, presença ausente.A perda se tornaria a origem da linguagem poética.Através da leitura dos poemas de Du Mouvement et de l''immobilité de Douve, Hier régnant désert, Pierre écrite, Dans le leurre du seuil, Ce qui fut sans lumière e Les Planches courbes, e das narrativas L''Arrière-pays, Rue Traversière e Le Théâtre des enfants, este estudo buscará compreender a poesia de Yves Bonnefoy a partir das noções de rastro, hesitação e memória.Dividido em cinco capítulos principais, trata-se da tentativa de situar a sua poesia, a um só tempo, como expressão e reflexão de cada um desses lugares.', '["Yves Bonnefoy","time in poetry","presence","absence","memory","hesitation","obscurantism","anti-Platonism","Jean Wahl","existentialism"]', '10.7476/9788568334720', '9788568334720', 'https://books.scielo.org/id/2463f', 'https://books.scielo.org/id/2463f/pdf/simpson-9788568334720.pdf', NULL, 'https://books.scielo.org/id/2463f/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-24hnr', '24hnr', 'Geografia e anarquismo: a importância do pensamento de Piotr Kropotkin para a ciência', NULL, '["Amir El Hakim de Paula"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro procura discutir as principais contribuições para a ciência do pensador russo Piotr Kropotkin, um dos principais intelectuais do anarquismo no fim do século XIX e início do século XX. Embora respeitado no século XIX, ainda são escassos os debates sobre a obra de Kropotkin, principalmente sobre sua teoria do apoio mútuo e a influência que ela teria na organização dos seres vivos (incluindo os seres humanos). Relacionando suas pesquisas empíricas na Sibéria com a questão darwinista da “sobrevivência do mais capaz”, Kropotkin percebe que, ao contrário do que afirmavam alguns evolucionistas, naquela região predominava uma “estranha” sociabilidade, na qual se destacava a solidariedade entre indivíduos de uma mesma espécie, que desse modo conseguiam levar vantagem sobre seus “inimigos” naturais. Compreender a teoria do apoio mútuo e suas implicações no debate científico do século XIX permite-nos também perceber de que forma Kropotkin contribuiu para a constituição teórica de uma Geografa mais humanista, solidária e crítica.', '["mutual aid","anarchism","human geography","Darwinism","survival of the fittest","Siberia","sociability","solidarity","critique of Darwinism","19th-century science"]', '10.7476/9788595463356', '9788595463356', 'https://books.scielo.org/id/24hnr', 'https://books.scielo.org/id/24hnr/pdf/paula-9788595463356.pdf', NULL, 'https://books.scielo.org/id/24hnr/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-24sgf', '24sgf', 'Caminhos do pensamento: epistemologia e método', NULL, '["Maria Cecília de Souza Minayo","Suely Ferreira Deslandes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Nursing', 'Durante anos, os estudos sobre a saúde da criança e da mulher estiveram vinculados a uma ótica que não as percebia como protagonistas das situações - a mulher era vista apenas como mãe e a criança tinha sua subjetividade ignorada. Caminhos do pensamento: epistemologia e método é o primeiro livro da Coleção Criança, Mulher e Saúde que traz ao debate algumas temáticas consideradas base de toda ação de pesquisa e desenvolvimento. A coletânea reúne autores que discutem a relação entre teoria e método, construção de conceitos e a possibilidade de aplicação da ciência na melhora da qualidade de vida. Tudo isso faz deste livro um excelente objeto de pesquisa, ideal para alunos dos cursos de graduação, pós-graduação e leitores interessados na inserção da criança e da mulher nos estudos sobre clínica médica, ciências sociais e humanas, ciências básicas e saúde coletiva.', '["child health","women''s health","epistemology","research methodology","theory and method","concept formation","child subjectivity","women as mothers","quality of life","clinics","humanities and social sciences"]', '10.7476/9788575414118', '9788575410110', 'https://books.scielo.org/id/24sgf', NULL, NULL, 'https://books.scielo.org/id/24sgf/cover/cover_thumbnail.jpeg', 380, 63, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-24vqz', '24vqz', 'Enterrado vivo: identidade punk e território em Londrina', NULL, '["Nécio Turra Neto"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este trabalho a respeito de punks conta com elementos de antropologia, história, sociologia, psicologia, geografia, filosofia e com estudos de identidade cultural. Resultado do contato e do envolvimento do autor com o grupo pesquisado numa convivência por sete meses, explora conteúdos geográficos existentes na memória e no imaginário social de jovens brasileiros engajados em movimentos culturais. Uma contribuição da geografia para o estudo dos punks que também reforça o debate dos novos rumos da geografia brasileira, na perspectiva dos sujeitos sociais.', '["punk subculture","cultural identity","territory","youth subcultures","cultural movements","social memory","social imaginary","Brazilian youth","Londrina","Brazilian geography"]', '10.7476/9788539302765', '9788571395367', 'https://books.scielo.org/id/24vqz', NULL, NULL, 'https://books.scielo.org/id/24vqz/cover/cover_thumbnail.jpeg', 284, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-253vp', '253vp', 'Flores matinais colhidas ao entardecer - 朝花夕拾', NULL, '["Lu Xun"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro inaugura a Série Clássicos da Literatura Chinesa, fruto de uma parceria da Editora com o Instituto Confúcio da Unicamp. A obra reúne dez textos em prosa escritos em 1926. Conhecida como coletânea de textos reminiscentes, traz registros de memória que ilustram os caminhos trilhados e as experiências adquiridas pelo autor, da infância até a juventude. São, ao mesmo tempo, retratos vívidos do cotidiano do final da dinastia Qing até o início da República na China. Clássico da prosa moderna chinesa, o livro conta ainda com prefácio e posfácio do próprio autor, além de uma apresentação e um texto introdutório, que situam o autor e a obra.', '["Lu Xun","reminiscence","childhood memories","Qing dynasty","early Republican China","Chinese literature"]', '10.7476/9788526815445', '9786586253818', 'https://books.scielo.org/id/253vp', NULL, NULL, 'https://books.scielo.org/id/253vp/cover/cover_thumbnail.jpeg', 237, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-259tw', '259tw', 'Introdução à direção teatral', NULL, '["Walter Lima Torres Neto"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Administrar, coordenar, dirigir, encenar, ensaiar, provar, repetir… Esses são alguns verbos fundamentais na concepção de uma exibição cênica e de uma obra sobre direção teatral. Na primeira seção deste livro, o autor traça um breve histórico desse ofício no teatro ocidental. Na segunda, há uma reflexão sobre a dinâmica criativa dos elementos que compõem a encenação – texto, atuação, figurino, espaço, iluminação, música de cena, marcação, dentre outros elementos. Eles convergem para a cena graças ao esforço e ao trabalho intelectual do diretor em interação com o coletivo de agentes criativos. Na terceira seção, alguns tópicos são sugeridos para redação de um projeto de encenação. Na última parte, um “Caderno de imagens” no qual estão dispostos esquemas, plantas baixas e fotografias de espetáculos que tiveram concepção espacial de Doris Rollemberg.', '["theatrical direction","stage direction","Western theatre","staging","acting","costume design","stage space","stage lighting","theatre music","blocking","creative process","stage design"]', '10.7476/9788526815940', '9786586253658', 'https://books.scielo.org/id/259tw', NULL, NULL, 'https://books.scielo.org/id/259tw/cover/cover_thumbnail.jpeg', 239, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-25qkk', '25qkk', 'Métodos de pesquisa em comunicação política', NULL, '["Rousiley C. M. Maia"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra visa abordar técnicas e instrumentos de pesquisa de modo mais apropriado e coerente com as indignações e os problemas nessa área interdisciplinar de conhecimento. Os métodos são tratados de maneira didática e sistemática, a fim de permitir um entendimento aprofundado e contextualizado sobre várias estratégias analíticas, dimensões e ângulos para tratar complexos processos comunicativos que atravessam a política institucional formal, organizações do mercado, associações cívicas e as experiências das pessoas em diferentes domínios sociais.', '["political communication","research methodology","research tools","analytical strategies","institutional communication","market organization","civil associations","public opinion"]', '10.7476/9786556308883', '9786556304557', 'https://books.scielo.org/id/25qkk', 'https://books.scielo.org/id/25qkk/pdf/maia-9786556308883.pdf', NULL, 'https://books.scielo.org/id/25qkk/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-25y65', '25y65', 'Monitoramento, infraestruturas e tecnologias: novos desafios na comunicação científica', 'novos desafios na comunicação científica', '["Rogério Mugnaini","Fernando Modesto"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A comunicação científica passa por transformações impulsionadas por novas tecnologias, infraestruturas informacionais e desafios na avaliação da produção acadêmica. Esta coletânea reúne pesquisas sobre monitoramento da ciência, acesso aberto, métricas de avaliação, repositórios institucionais e plataformas digitais, explorando como esses elementos impactam a disseminação do conhecimento.', '["science communication","open access","research metrics","institutional repositories","digital platforms","knowledge dissemination","information infrastructure","scholarly publishing"]', '10.7476/9786556309156', '9786556307152', 'https://books.scielo.org/id/25y65', 'https://books.scielo.org/id/25y65/pdf/mugnaini-9786556309156.pdf', NULL, 'https://books.scielo.org/id/25y65/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-27bn3', '27bn3', 'Clio-Psyché: discursos e práticas na história da psicologia', NULL, '["Ana María Jacó-Vilela","Dayse de Marie Oliveira"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Apresenta reflexões sobre a história, a prática e os saberes da psicologia decorrentes do XI Encontro do Clio-Psyché, evento produzido pelo Programa de Estudos e Pesquisas da História da Psicologia da UERJ. Com autores provenientes de instituições do Brasil e de outros países da América Latina, assim como da Europa, a obra se caracteriza pela diversidade de temas. Entre eles, a relação do marxismo com a história da psicologia, o intercâmbio entre as psicanálises argentinas e brasileiras no contexto da ditadura, as especificidades da formação profissional, a reforma psiquiátrica, e a internacionalização da história da psicologia. Em destaque, analisa a contribuição de Emílio Mira y Lópes, psiquiatra, professor e sociólogo com atuação na Espanha, Argentina, URSS e Brasil.', '["history of psychology","Argentine psychoanalysis","Brazilian psychoanalysis","psychology education","psychiatric reform","Latin American psychology"]', '10.7476/9788575114988', '9788575114988', 'https://books.scielo.org/id/27bn3', 'https://books.scielo.org/id/27bn3/pdf/jaco-9788575114988.pdf', NULL, 'https://books.scielo.org/id/27bn3/cover/cover_thumbnail.jpeg', NULL, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-27djv', '27djv', 'Paisagem e Socionatureza: olhares geográfico-filosóficos', NULL, '["Reginaldo José de Souza"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'A obra resultou de uma pesquisa de pós-doutoramento realizada no Centro de Filosofia da Universidade de Lisboa. O enfoque é a compreensão das bases filosóficas de um conceito amplamente utilizado na pesquisa e no ensino de Geografia: a paisagem. A partir da abordagem filosófica, que a considera como dimensão da existência e de um possível retorno ao sentimento de natureza em uma sociedade econômica e ecologicamente em crise, o objetivo da obra é discorrer sobre a paisagem enquanto potencialidade para a leitura crítica da realidade e busca de um mundo socialmente justo. A essência da natureza é constituída pela dialética ordem-caos e, enquanto movimento incessante, subjuga tudo e todos à dissolução no tempo e no espaço. No cerne da democrática condenação natural à morte, a sociedade hierárquica pode encontrar meios para realizar sua própria humanidade: sem guerras, sem degradação, sem riquezas acumuladas através de empobrecimento e fome. A compreensão da paisagem pode ser a porta de entrada para a estética da beleza que deve haver no mundo, em nós, nas relações humanas e na maneira de transformar a natureza.', '["landscape","philosophy of geography","nature","order and chaos","dialectics","social justice","philosophy of beauty","human-nature relationship","environmental crisis"]', '10.7476/9788564905986', '9788564905986', 'https://books.scielo.org/id/27djv', 'https://books.scielo.org/id/27djv/pdf/souza-9788564905986.pdf', NULL, 'https://books.scielo.org/id/27djv/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-27nk7', '27nk7', 'A escravidão no Brasil ensaio histórico-jurídico-social - Vol 2', NULL, '["Agostinho Marques Perdigão Malheiros"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 1867, '1867-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Cap. VI. -Leis sobre liberdade dos índios.-Missões Jesuíticas.-Regimento das missões.-Novas leis de escravidão.-Descimento de índios.-Guerras dos mesmos.-Novas providências.Cap.VII -Bula de Benedito XIV a favor dos índios.-Novas providências sobre os mesmos.-Guerra das Missões no Rio da Prata.-Oposição no Amazonas.-Os Jesuítas.-Leis de liberdade absoluta dos índios.-Nova forma do seu governo temporal.-Diretório para o Maranhão e Pará.-Expulsão dos Jesuítas.-Decadência das aldeias; dispersão dos índios.-Abolição do Diretório.-Novas providências Cap.VIII.-Restauração do sistema do terror contra os índios.-Guerra aos mesmos.-Bandeiras.-Novas providências para a sua catequese e civilização.-Sistema misto Cap.IX. -Direito novo.-Abolição completa e definitiva do cativeiro e servidão dos índios.-Proteção e favores.-Sistema atual.-Futuro dos índios ante a civilização.-Conclusão.', '["slavery of indigenous peoples","indigenous rights","Jesuit missions","expulsion of the Jesuits","colonial Brazil","colonial legislation","bandeiras","abolition of slavery","Rio da Prata"]', '10.7476/9788579820731', '9788579820731', 'https://books.scielo.org/id/27nk7', 'https://books.scielo.org/id/27nk7/pdf/malheiros-9788579820731.pdf', NULL, 'https://books.scielo.org/id/27nk7/cover/cover_thumbnail.jpeg', NULL, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2844p', '2844p', 'O crime do padre Amaro – Eça de Queirós: texto da primeira versão e ensaios', NULL, '["Daiane Cristina Pereira","Danilo Silvério","José Roberto de Andrade"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Pensado no âmbito do 1ª Encontro do Grupo Eça, quando se comemorava 140 anos de sua primeira edição, este livro traz ao público a primeira versão de O crime do padre Amaro, de Eça de Queirós. Publicado na Revista Ocidental, no ano de 1875, pelas mãos de Antero de Quental e Jaime Batalha Reis, o livro foi revisto e praticamente reescrito por seu autor nos anos de 1876 e 1880, sendo que esta última é considerada a versão definitiva. Disso decorre que a versão de 1875 quase não tivesse tido novas edições e, dessa maneira, fosse pouco conhecida do público. O Livro traz grande interesse ao público em geral, mas também ao público mais especializado, como os estudantes e profissionais de literatura ou os próprios queirosianos, visto que apresenta a raridade e a preciosidade do objeto pouco encontrado e pouco conhecido. Esta edição conta com textos críticos acerca do livro, produzidos pelos representantes do Grupo Eça. Formado na Universidade de São Paulo, no ano de 2004, o grupo se espraiou para as mais importantes universidades do Brasil e, podemos dizer, do mundo e tenta manter uma produção consistente sobre a obra do escritor português. No caso da primeira versão de O crime do padre Amaro, os textos apresentados são fruto da reflexão de anos de trabalho e patindo das condições de publicação, atingindo a análise e interpretação mais pragmáticas do texto literário, os artigos produzidos desejam aclarar e tomar mais interessante ao público leitor o volume que tem em mãos.', '["Eça de Queirós","O Crime do Padre Amaro","first version","textual criticism","textual revision","Antero de Quental","Portuguese literature"]', '10.7476/9786586383058', '9788576287681', 'https://books.scielo.org/id/2844p', NULL, NULL, 'https://books.scielo.org/id/2844p/cover/cover_thumbnail.jpeg', 364, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-28m67', '28m67', 'Anopheles gambiae no Brasil – 1930 a 1940', NULL, '["Sergio Goes de Paula","Mário Moreira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Fred L. Soper e D. Bruce Wilson lideraram uma campanha sanitária no Nordeste brasileiro que culminou com a erradicação, em tempo recorde – apenas 35 meses –, do mais eficiente dentre os vetores da malária, o mosquito Anopheles gambiae. Considerado leitura obrigatória para os interessados em saúde pública no Brasil, o relatório final dessa campanha – que descreve detalhadamente os procedimentos e métodos de trabalho sob o ponto de vista de seus diretores – foi originalmente publicado em inglês, em 1943. Pouco depois, em 1945, o relatório ganhou uma edição em português, mas não uma tradução fiel. Ela se voltava para as atividades do Serviço de Malária do Nordeste e a questão dos doentes de malária, enquanto o original era centrado nas ações da Fundação Rockefeller e na campanha de erradicação do mosquito. Decidiu-se, então, retraduzir o original – encontrado hoje em dia somente na seção de obras raras de bibliotecas especializadas –, incorporando alguns elementos de destaque da primeira versão em português.', '["Anopheles gambiae","malaria vector control","mosquito eradication","malaria patients","Northeast Brazil","1930s","history of public health"]', '10.7476/9786557080702', '9788575412244', 'https://books.scielo.org/id/28m67', NULL, NULL, 'https://books.scielo.org/id/28m67/cover/cover_thumbnail.jpeg', 376, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-28w3s', '28w3s', 'Os Correios e as políticas governamentais: mudanças e permanências', NULL, '["Tadeu Gomes Teixeira"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro mostra, com base em um amplo estudo realizado nos Correios, as tendências do setor postal no Brasil e no contexto internacional. Obra única no mercado editorial, reflete, a partir do setor postal, tendências políticas e econômicas mais amplas. Aspectos como as disputas empresariais e governamentais para a regulação do mercado postal, as políticas de gestão e relações de trabalho nos Correios e os processos de modernização pelos quais passou a empresa desde o início da década de 1990 perpassam a obra. As polêmicas também não ficam de fora: por que há tantas greves no Correios? O que foi a "crise nos Correios"? Houve aparelhamento político na empresa? Ao término da leitura, o leitor terá respostas para essas questões e verá como estão imbricadas aos processos de trabalho e práticas de gestão no setor postal brasileiro, refletindo as estratégias adotadas pelos setores públicos que governaram o país nas últimas décadas, identificando as mudanças e permanências na empresa e nas políticas governamentais.', '["Correios","postal services","public policy","public enterprises","postal reform","state intervention in the economy"]', '10.7476/9788523220259', NULL, 'https://books.scielo.org/id/28w3s', 'https://books.scielo.org/id/28w3s/pdf/teixeira-9788523220259.pdf', NULL, 'https://books.scielo.org/id/28w3s/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-292wc', '292wc', 'Comensalidades em narrativa: estudos de mídia e subjetividade', NULL, '["Francisco Romão Ferreira","Denise da Costa Oliveira Siqueira","Luis Ernesto Blacha","Shirley Donizete Prado"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A coletânea destaca práticas alimentares por meio das quais emergem múltiplos imaginários e consumos que traduzem a diversidade de olhares, identidades e pertencimentos à vida urbanizada. O livro traz ainda análises de fenômenos comunicativos e suas representações a partir de miradas críticas em torno de temas diversos e suas múltiplas interfaces buscando trazer à luz convergências, mas também tensões, disputas e resistências sociais envolvendo diferentes saberes acerca da comida, da comensalidade e das subjetividades.', '["commensality","food practices","media representation of food","subjectivity","urban life","food and identity","social resistance","food knowledge"]', '10.7476/9786556305226', '9786556305226', 'https://books.scielo.org/id/292wc', 'https://books.scielo.org/id/292wc/pdf/ferreira-9786556305226.pdf', NULL, 'https://books.scielo.org/id/292wc/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2946x', '2946x', '¿Cómo se mide el acoso sexual? Aportes para determinar la prevalencia del acoso sexual em las instituciones de educación superior', NULL, '["María de Lourdes Larrea","Christian Paula","Milena Almeida","Paulina Palacios","Daniela Acosta","María José","Jeimy López"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2020, '2020-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este estudio busca contribuir a la formulación y aplicación de políticas públicas y académicas para combatir, prevenir y erradicar el acoso sexual en las instituciones de educación superior del Ecuador. El diseño y validación de un instrumento de medición del acoso sexual, así como los datos que se obtenga, permiten viabilizar la intervención de las autoridades frente a una problemática conocida pero ocultada. El resultado final es parte de un largo e intenso proceso colectivo, donde los debates académicos, ideológicos, técnicos y políticos fueron una constante. Esto explica que el texto refleja una variedad de contenidos que van desde los insumos teóricos hasta el manual de aplicación de una encuesta. El documento tiene distintas pretensiones. Por un lado, es una contribución al debate teórico sobre el tema del acoso sexual y la violencia de género; por otro lado, aporta con información valiosa para aquellas personas interesadas en el tema; adicionalmente, proporciona insumos metodológicos y un instrumento para replicar el proceso en cualquier universidad del país y de la región. Una de las constataciones más relevantes, al aplicar la encuesta, fue la hegemonía masculina en los puestos de decisión de las universidades nacionales. Aunque a nivel del estudiantado las mujeres son mayoría en casi todas las instituciones, los puestos de dirección están ocupados predominantemente por varones. Esta circunstancia fue determinante al momento de llevar a cabo la encuesta, debido a la oposición de docentes, decanos y personal directivo que percibían a la investigación como una amenaza al statu quo académico y administrativo', '["sexual harassment","higher education institutions","measurement instrument validation","prevalence survey","gender-based violence","women in academia","Ecuadorian universities"]', '10.7476/9789978106211', '9789978106211', 'https://books.scielo.org/id/2946x', 'https://books.scielo.org/id/2946x/pdf/larrea-9789978106211.pdf', NULL, 'https://books.scielo.org/id/2946x/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-296z5', '296z5', 'Paisagens sígnicas: uma reflexão sobre as artes visuais contemporâneas', NULL, '["Maria Celeste de Almeida Wanner"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Arte, inovação, educação, ciência, medicina, comunicação, literatura, são alguns dos ingredientes que irão compor esse evento, tornando-o uma grande oportunidade de intercâmbio entre as diversas áreas. Isso sem falar no local da ocasião, o Museu de Arte da Bahia, importante patrimônio cultural do nosso país.', '["contemporary visual art","art and science","art and education","art and communication","art and literature","art and medicine","innovation","interdisciplinarity","cultural heritage"]', '10.7476/9788523208837', '9788523208837', 'https://books.scielo.org/id/296z5', 'https://books.scielo.org/id/296z5/pdf/wanner-9788523208837.pdf', NULL, 'https://books.scielo.org/id/296z5/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-29dyw', '29dyw', 'Pesquisa-ação colaborativa na universidade: experiências e práticas inovadoras', NULL, '["Ramalho, Ana Carla","Lopes Ribeiro, Marinalva","Oliveira da Silva, Fabrício"]', 'Directory of Open access Books (OAPEN Foundation)', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A mudança de currículos e práticas pedagógicas são aspectos fundamentais dos textos reunidos nesta coletânea em que o foco das análises é o trabalho docente na universidade. Daí a pertinência metodológica do termo-chave utilizado: pesquisa-ação colaborativa. À luz desse enfoque, o que o conjunto dos trabalhos ressalta é a necessidade de se repensar a pedagogia do ensino superior, a qual, caracterizada pelo pensamento único da racionalidade técnica, é cega e surda, no cotidiano acadêmico, à emergência de diferentes sujeitos históricos e de suas linguagens, com o aporte das novas tecnologias de informação e comunicação.', '["collaborative action research","university teaching","curriculum change","teaching practice","information and communication technologies","technical rationality","innovative teaching practices"]', '10.7476/9788555921100', '9788555921100', 'https://books.scielo.org/id/29dyw', 'https://books.scielo.org/id/29dyw/pdf/ramalho-9788555921100.pdf', NULL, 'https://books.scielo.org/id/29dyw/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-29k48', '29k48', 'Educação permanente em saúde para os trabalhadores do SUS', NULL, '["Fernanda de Oliveira Sarreta"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Neste livro são analisadas as experiências de educação permanente como estratégia para a formação dos trabalhadores da saúde e consolidação do SUS na região de Franca/SP. A investigação foi construída a partir das teorias da aprendizagem significativa que valorizam as práticas dos sujeitos sociais. Para compreender as contradições e os conflitos emergentes nesse contexto, foram utilizadas a abordagem qualitativa e as entrevistas semi-estruturadas. As falas desses sujeitos evidenciam a necessidade de formação e a disposição dos trabalhadores para rever conceitos e experimentar novas tecnologias com vistas à melhoria do atendimento. O trabalho apresenta uma contribuição na busca de alternativas para disseminar a educação permanente e a saúde como direito humano universal e integral', '["continuing health education","healthcare workers","Unified Health System (SUS)","health professions education","meaningful learning","social subjectivity"]', '10.7476/9788579830099', '9788579830099', 'https://books.scielo.org/id/29k48', 'https://books.scielo.org/id/29k48/pdf/sarreta-9788579830099.pdf', NULL, 'https://books.scielo.org/id/29k48/cover/cover_thumbnail.jpeg', NULL, 20, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-29qxf', '29qxf', 'Uma história das leishmanioses no novo mundo: anos 1960 ao século XXI – Amazônia', NULL, '["Jaime Larry Benchimol","Cláudio de Oliveira Peixoto"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Do ponto de vista historiográfico e metodológico, a maior contribuição do livro é a capacidade dos autores de concatenar diferentes sujeitos e territórios na longa duração, estabelecendo fluxos geracionais, identificando influências intelectuais, mapeando genealogias e trajetórias, conectando diferentes tempos e espaços em torno de uma doença – a leishmaniose –, fazendo confluir múltiplos e independentes canais de energia criativa, digamos assim, para uma espécie de ponto de fuga. Ao mesmo tempo em que caracterizam uma comunidade epistêmica, tecem narrativas paralelas, tal como um argumento que se desenvolve em camadas. Por exemplo, esmiuçam as controvérsias científicas inerentes à parasitologia, como a da relação parasita hospedeiro, enquanto exploram as agruras políticas e ambientais decorrentes da descoberta de Carajás ou da construção da Transamazônica. O que une ou costura a narrativa de Benchimol e Peixoto é a leishmaniose, presente no horizonte de interesses de pesquisadores de diversas nacionalidades, nas agendas de instituições de pesquisa e de agências governamentais, no dia a dia de serviços médicos e de saúde e na vida das populações afetadas por desastres perpetrados pelo Estado brasileiro.', '["leishmaniasis","history of parasitology","Amazon","Carajás","Transamazon Highway","host-parasite interactions","epistemic communities","scientific controversy","health services","Brazilian states","longue durée"]', '10.7476/9786557081785', '9786557081365', 'https://books.scielo.org/id/29qxf', NULL, NULL, 'https://books.scielo.org/id/29qxf/cover/cover_thumbnail.jpeg', 964, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-29wr5', '29wr5', 'Comunidades de aprendizagem: outra escola é possível', NULL, '["Roseli Rodrigues de Mello","Fabiana Marini Braga","Vanessa Gabassa"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] Comunidades de Aprendizagem é proposta de transformação das escolas para garantir máxima aprendizagem, convivência plena na diversidade e participação da comunidade nos processos e decisões. O livro apresenta Comunidades de Aprendizagem em cinco capítulos: o primeiro está dedicado ao contexto atual, em âmbito internacional, e às implicações e especificidades do Brasil, que colocam às escolas o desafio de se transformar; o segundo traz o conceito de Aprendizagem Dialógica, base teórico-metodológica de Comunidades de Aprendizagem; o terceiro trata das fases de transformação em Comunidade de Aprendizagem; o quarto traz o funcionamento dos processos de uma Comunidade de Aprendizagem, com base em experiências pesquisadas pelas autoras em Comunidades de Aprendizagem do Brasil e da Espanha; o livro é encerrado com elementos favorecedores e os que são obstáculo, no contexto brasileiro, para a transformação das escolas em sentido mais democrático, dialógico e de garantia de aprendizagem para todos os estudantes.', '["learning communities","school transformation","dialogic learning","school democracy","school community participation","coexistence in diversity","inclusive education"]', '10.7476/9788576003731', '9788576003731', 'https://books.scielo.org/id/29wr5', NULL, NULL, 'https://books.scielo.org/id/29wr5/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2b8tj', '2b8tj', 'Estado e punitividade: problemas de governança penal democrática', NULL, '["David Santos Fonseca","Carlos Cañedo"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'No interior de sociedades democráticas, os limites de atuação do sistema penal sempre provocam intenso debate. O aumento do uso das prisões ao redor do mundo é um dos temas mais espinhosos da atualidade, de forma a demandar respostas que permitam compreender as razões por detrás dessa expansão. Nesse processo, a inter-relação entre democracia e governança penal revela complexos matizes na adoção de modelos de punição e na forma de exercício do controle social formal em diferentes países. Com a presente obra, a análise de diversas regiões permite um amplo esforço comparativo, enquanto também oferece novos métodos e abordagens no estudo desse fenômeno. Ao reunir esses trabalhos, este livro viabiliza caminhos para se discutir a relação entre penalidade e democracia de modo amplo, com a introdução de discussões que ultrapassam a simples atribuição do atual encarceramento em massa ao efeito do punitivismo e do populismo penal. Os artigos aqui reunidos permitem que aspectos estruturais e institucionais de vários contextos democráticos sejam analisados de forma detida e aprofundada, de modo a complementar, quando não subverter, as explicações tradicionais sobre a crise contemporânea do sistema penal. O intuito é, assim, permitir que as discussões sobre esse tema no cenário brasileiro possam incorporar outras perspectivas, refinar os diagnósticos e permitir a elaboração de proposições para melhoria desse campo de atuação estatal.', '["democracy","punitiveness","mass incarceration","penal populism","social control","comparative criminal justice","Brazil"]', '10.7476/9786558461579', '9786558460015', 'https://books.scielo.org/id/2b8tj', NULL, NULL, 'https://books.scielo.org/id/2b8tj/cover/cover_thumbnail.jpeg', 480, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2bg5k', '2bg5k', 'Língua e sociedade nas páginas da imprensa negra paulista: um olhar sobre as formas de tratamento', NULL, '["Sabrina Rodrigues Garcia Balsalobre"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta pesquisa tem, como objetivo principal, a análise da inter-relação entre fatores de ordem linguística e social a partir de um corpus jornalístico: a Imprensa Negra paulista – movimento realizado por negros e destinado a essa população no período posterior à abolição da escravatura no Brasil. A formação dessa imprensa se deu pela necessidade de veicular as reivindicações por melhores condições de vida e as propostas de inserção na sociedade brasileira. Para cumprir o objetivo desse trabalho, de se estabelecer relações interdependentes entre usos linguísticos e fatores sociais, foram analisados três periódicos da Imprensa Negra: O Kosmos, O Alfinete e O Clarim d’Alvorada. Essa escolha se justifica por uma combinação de fatores, entre eles a disponibilidade desse material, o período e local de produção (primeiras décadas do século XX / cidade de São Paulo) e o propósito de cada um desses periódicos. Para atingir esse propósito, optou-se por analisar o sistema de formas de tratamento empregado nos jornais, por se acreditar que esse fenômeno linguístico representa um exemplo privilegiado da relação entre a escolha linguística e seu motivador social. A fim de se estabelecer os usos da população negra e os usos tipicamente empregados pelo jornalismo da época, fez-se necessário comparar os dados da Imprensa Negra, com um jornal de circulação mais ampla na cidade de São Paulo: O Combate. Uma vez que o jornal é um gênero textual constituído por textos de naturezas diversas, privilegiou-se a proposta teórico-metodológica de Bonini (2003, 2004, 2006), que prevê a análise do jornal como um hipergênero, com o intuito de se avaliar as características peculiares de cada um dos gêneros do jornal para, posteriormente, relacioná-las com o emprego das formas de tratamento. O fenômeno lingüístico, em análise no presente estudo...', '["address terms","language and society","Black press","São Paulo","journalistic genres","hypergenre","post-abolition period","Black communities"]', '10.7476/9788579831041', '9788579831041', 'https://books.scielo.org/id/2bg5k', 'https://books.scielo.org/id/2bg5k/pdf/balsalobre-9788579831041.pdf', NULL, 'https://books.scielo.org/id/2bg5k/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2bgqq', '2bgqq', 'Presença intelectual africana: Cheikh Anta Diop', NULL, '["Flávio Gonçalves dos Santos","Jacques Depelchin"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Na perspectiva de se dar mais visibilidade, no Brasil, às obras de autores africanos, o livro apresenta textos de diferentes pesquisadores a respeito da vasta contribuição intelectual do historiador e antropólogo senegalês Cheikh Anta Diop. Aqui, Diop é estudado e homenageado por sua intensa dedicação à pesquisa da cultura africana pré-colonial, origens da raça humana, dentre outros temas.', '["Cheikh Anta Diop","African intellectual history","African historiography","African anthropology"]', '10.7476/9786586213775', '9788574555478', 'https://books.scielo.org/id/2bgqq', NULL, NULL, 'https://books.scielo.org/id/2bgqq/cover/cover_thumbnail.jpeg', 133, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2brvb', '2brvb', 'Fronteiras linguísticas em contextos migratórios', NULL, '["Sabine Gorovitz","Dioney Moreira Gomes"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'As fronteiras nunca impediram a circulação de homens e mulheres no mundo. Invasores, colonos, migrantes, refugiados, pessoas deslocadas, viajantes estão constantemente cruzando essas fronteiras em todas as direções, misturando línguas e costumes em contato com as populações locais. Os autores deste livro exploram, cada um à sua maneira, os contextos em que as relações entre línguas e fronteiras foram forjadas nos níveis político e ideológico, com forte ênfase na observação das práticas linguísticas e na análise de diálogos e interações entre falantes de diferentes idiomas. A articulação das diferentes abordagens possibilita aqui, pelo menos em parte, explicar a complexidade dos fenômenos observados. Tal qual um manifesto em favor do reconhecimento do multilinguismo, o livro homenageia as práticas bilíngues e os recursos criativos que cada falante implementa, onde ele está, de onde ele está falando, para criar um vínculo com os outros.', '["language boundaries","migration","multilingualism","bilingualism","language contact","language practices","refugees","displaced persons","language ideology","interlanguage interaction"]', '10.7476/9788523013448', '9788523010171', 'https://books.scielo.org/id/2brvb', NULL, NULL, 'https://books.scielo.org/id/2brvb/cover/cover_thumbnail.jpeg', 296, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2bvx9', '2bvx9', 'Solidariedade ou Competição? Políticas e sistema de atenção à saúde na Alemanha', NULL, '["Lígia Giovanella"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2001, '2001-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Analisa o sistema de proteção social à saúde – na Alemanha, Seguro Social de Doença. O seguro social implica a segmentação da clientela, assim, a solidariedade é resultado de mecanismos políticos de negociação corporativa, quando são capazes de gerar pactos sociais que reduzam a estratificação. O Estado exerce papel fundamental para a garantia do processo de negociação corporativa, para a regulação do mercado e garantia dos direitos dos usuários e no desenvolvimento de políticas para os grupos desprotegidos ou para demandas específicas. Apesar de enfocar a realidade alemã, este livro oferece grande contribuição na reflexão sobre questões de políticas de saúde, consideradas, talvez precocemente, obsoletas pelos reformadores brasileiros.', '["health care system","social health insurance","solidarity","competition","social protection","health policy","health stratification","state role in health care","Brazil"]', '10.7476/9786557080979', '9786557080979', 'https://books.scielo.org/id/2bvx9', 'https://books.scielo.org/id/2bvx9/pdf/giovanella-9786557080979.pdf', NULL, 'https://books.scielo.org/id/2bvx9/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2c9z8', '2c9z8', 'Língua(gem) e sexualidade: perspectivas do século XXI', NULL, '["Pedro Eduardo de Lima"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra tem a finalidade de reunir pesquisas de diferentes áreas do conhecimento, com o objetivo de apresentar, divulgar e traçar perspectivas acerca das pesquisas multidisciplinares sobre gênero, sexualidade e linguagem, a partir de argumentações diversas na literatura das áreas envolvidas. Entre as áreas estão: sociolinguística, estudos discursivos, estudos de gênero, estudos feministas, línguas de sinais, entre outras, no que diz respeito às práticas linguísticas de diferentes corpos, que vão além dos dicotômicos feminino e masculino, a fim de desenvolver uma série de ferramentas teóricas e metodológicas para a análise crítica dos fenômenos de língua(gem) e sexualidade.', '["gender and language","sexuality","gender","language","feminist studies","sign language","sociolinguistics","language practices"]', '10.7476/9786556305004', '9786556303505', 'https://books.scielo.org/id/2c9z8', NULL, NULL, 'https://books.scielo.org/id/2c9z8/cover/cover_thumbnail.jpeg', 248, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2cc7t', '2cc7t', 'Saúde em jogo: atores e disputas de poder na Agência Nacional de Saúde Suplementar (ANS)', NULL, '["Marcello Fragano Baird"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra expõe com riqueza de detalhes a estrutura de poder político e econômico que governa o setor da saúde suplementar no Brasil. Indo muito além da simples descrição da configuração do mercado de planos de saúde e da atuação da Agência Nacional de Saúde Suplementar (ANS), Marcello Baird mergulha em dados sobre doações de campanhas, indicações políticas, laços pessoais, vínculos empregatícios e na análise de normas para desvendar a trama das íntimas relações entre as grandes empresas do setor, políticos poderosos e diretores da agência reguladora.', '["supplementary health insurance","health insurance market","regulatory agencies","power struggles","political economy of health","campaign contributions","political patronage","personal networks","health policy","Brazil"]', '10.7476/9786557080849', '9786557080108', 'https://books.scielo.org/id/2cc7t', NULL, NULL, 'https://books.scielo.org/id/2cc7t/cover/cover_thumbnail.jpeg', 215, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2chyk', '2chyk', 'Brasil Saúde Amanhã: população, economia e gestão', NULL, '["Paulo Elson Fernandes Gadelha","José Carvalho de Noronha","Sulamis Dain","Thelma Ruth Pereira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra pretende refletir sobre o Brasil que queremos em um horizonte de vinte anos. Comprometido com a efetivação do SUS e a melhoria da saúde pública brasileira, o livro discute temas como projeções do perfil epidemiológico do país, organização e gestão dos serviços de saúde. Para identificar tendências, construir indicadores e intervir na realidade, os autores utilizam as ferramentas da prospecção estratégica. “Prospectar o futuro é ter um programa de ação. É criar elementos para a articulação e indução de políticas econômicas e sociais, no interesse do desenvolvimento com equidade, fomentando o acesso e a inclusão de camadas excluídas, expandindo e assegurando direitos sociais às significativas parcelas da população que permanecem marginalizadas”, explicam os organizadores. “Tomando a realidade atual como ponto de partida e a materialização das aspirações como ponto de chegada, torna-se possível projetar futuros favoráveis ao desenvolvimento econômico e social, dos quais faz parte um patamar mais elevado de gasto público em saúde, compatível com a universalização do acesso, há tanto anunciada”. O livro integra um conjunto de publicações resultantes da iniciativa Brasil Saúde Amanhã, rede multidisciplinar de pesquisa, coordenada pela Fiocruz, com apoio do Ministério da Saúde.', '["strategic foresight","health services administration","health care organization","epidemic projection","Unified Health System (SUS)","public health policy","health care costs","universal access to health","health equity","social inclusion","health indicators"]', '10.7476/9786557080931', '9786557080931', 'https://books.scielo.org/id/2chyk', 'https://books.scielo.org/id/2chyk/pdf/gadelha-9786557080931.pdf', NULL, 'https://books.scielo.org/id/2chyk/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2ckpr', '2ckpr', 'Ni con pequeño trabajo, ni con pequeño favor de Dios: fray Pedro Aguado y fray Antonio de Medrano frente a la conquista del Nuevo Reino de Granada 1550-1582', NULL, '["María Eugenia Hernández Carvajal"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2013, '2013-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Descubrimiento, pacificación y población de la provincia de Santa Marta y Nuevo Reino es una obra clave para entender los procesos culturales y sociales que se dieron en el Nuevo Reino de Granada durante el periodo colonial. Fray Antonio de Medrano, de la orden franciscana, inició esta obra alrededor de 1550, aprovechando su experiencia en las expediciones de conquista. Más tarde fray Pedro Aguado encontró estas notas y continuó el trabajo hasta terminarlo, con el objetivo de publicarlo (aunque nunca se llegó a hacer). La creencia en el Demonio y la necesidad de combatirlo (temas propios del pensamiento de san Agustín), la construcción del mito del hombre excepcional, el héroe fundador y su contraste con el tirano traidor son algunos de los ejes principales en torno a los cuales gira la obra. Este libro contiene un análisis del pensamiento de Aguado y Medrano, que trata de situar al lector en el horizonte actual del debate sobre las crónicas de la Conquista. La reflexión se ha contextualizado en el marco de las discusiones jurídicas y teológicas sobre la justificación de la conquista de América heredadas de la Edad Media, pero alimentadas por las nuevas condiciones y realidades que resultaron del encuentro del mundo europeo y el mundo americano. Acercarnos a estos temas y tratar de ubicarlos en el presente son tareas que resultan cada vez más necesarias.', '["Franciscan missionaries","colonial chronicles","demonology","Augustine of Hippo","founder myth","tyrants","Spanish colonial thought","16th century"]', '10.7476/9789585005419', '9789585005419', 'https://books.scielo.org/id/2ckpr', 'https://books.scielo.org/id/2ckpr/pdf/hernandez-9789585005419.pdf', NULL, 'https://books.scielo.org/id/2ckpr/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2dymk', '2dymk', 'Música popular e adjacências...', NULL, '["Paulo Costa Lima"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Música e composição vão além daquilo que soa, e vibram na direção do que se pensa, do que se imagina e do que se fala. As crônicas e ensaios apresentados nesse livro surgiram dessa consciência, e especialmente da teimosia na combinação de traços e temas aparentemente opostos. Celebra uma abertura de diálogo com um novo público, encontrando agora uma moldura em livro, buscando identificar caminhos e processos de construção composicional, mostrando que o terreno é fértil, e menos visitado do que deveria ser, especialmente agora que a complexidade das hierarquias não mais precisa das fronteiras de ontem, e nem mesmo de fixar receitas de complexidade.', '["popular music"]', '10.7476/9788523212025', '9788523212025', 'https://books.scielo.org/id/2dymk', 'https://books.scielo.org/id/2dymk/pdf/lima-9788523212025.pdf', NULL, 'https://books.scielo.org/id/2dymk/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2f3jk', '2f3jk', 'A política externa brasileira e a integração regional: uma análise a partir do Mercosul', NULL, '["Marcelo Passini Mariano"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'BRASILEIRA Princípios, valores e tradiçõesAnalisando o desenvolvimento histórico da política externa do Brasil, a partir da literatura especializada, identificamos a existência de elementos norteadores das decisões tomadas nesse campo.Amado Cervo (1992), por exemplo, os descreve como tradições que acompanham a história da política externa brasileira, capazes de sobreviver às mudanças de governo e às próprias alterações organizacionais do Estado, sendo representadas pela orientação pacifista, a juridicista e a pragmática (Cervo, 1994). 1 1 O pacifismo refere-se à posição defendida pela diplomacia brasileira de buscar solucionar os conflitos por meio de negociações.Isto é, a política externa brasileira tradicionalmente resiste à ideia de usar a força para resolver as controvérsias no plano internacional.Já o juridicismo relaciona-se com a postura de respeito aos tratados, acordos e convenções internacionais, aceitando-os enquanto instrumentos ordenadores da interação entre os atores estatais e do próprio sistema de Estados.Finalmente, temos o pragmatismo, também entendido como realismo na política externa brasileira.Essa tradição baseia-se na análise sobre o sistema internacional, a posição do Brasil neste sistema, as relações com as potências e a capacidade de defesa dos interesses nacionais para, a partir destes condicionantes, orientar a ação externa.Essas tradições fundamentam', '["Brazilian foreign policy","regional integration","Mercosur","pacifism","legalism","pragmatism"]', '10.7476/9788568334638', '9788568334638', 'https://books.scielo.org/id/2f3jk', 'https://books.scielo.org/id/2f3jk/pdf/mariano-9788568334638.pdf', NULL, 'https://books.scielo.org/id/2f3jk/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2fg55', '2fg55', 'Ensaios sobre o capitalismo no século XX', NULL, '["Frederico Mazzucchelli","Luiz Gonzaga de Mello Belluzzo"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Coletânea de parte dos artigos publicados na imprensa por Luiz Gonzaga de Mello Belluzzo, economista que, ao longo de sua carreira, se caracterizou pela coragem de debater suas opiniões dentro e fora da universidade. De leitura agradável e acessível, o livro é divido em quatro partes que tratam de: inflexões históricas do capitalismo do século XX; reflexões sobre transformações recentes desse sistema; observações sobre seus principais críticos e quatro artigos sobre futebol. (co-edição: Instituto de Economia da Unicamp)', '["capitalism","20th century","history of capitalism","economic transformation","football"]', '10.7476/9788539302994', '9788571395442', 'https://books.scielo.org/id/2fg55', NULL, NULL, 'https://books.scielo.org/id/2fg55/cover/cover_thumbnail.jpeg', 239, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2fpsy', '2fpsy', 'Ética profissional na tradução assistida por sistemas de memórias', NULL, '["Érika Nogueira de Andrade Stupiello"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Érika Nogueira de Andrade Stupiello faz aqui um convite à reflexão sobre o envolvimento do tradutor com seu trabalho, o papel desse profissional na atualidade e, principalmente, as consequências do emprego de tecnologias na tradução de textos. Ela enfatiza três sistemas de armazenamento de memória de tradução – Trados, Transit e Wordfast –, analisando os principais atributos de cada sistema e concentrando-se nas implicações de seu uso.Os sistemas apresentam vantagens e desvantagens bastante comentadas pela literatura sobre tradução. Embora possibilitem maior controle e padronização de terminologia e fraseologia, aumento da velocidade de trabalho, constituição do próprio banco de dados, eles reduzem o espaço para escolhas do tradutor, incentivam o uso instrumental das línguas para aumentar o reaproveitamento, impedem remuneração de material recuperado pelo sistema.Ao lembrar que os sistemas de memória não têm como objetivo eliminar a intervenção humana durante o processo de tradução nem destinar ao tradutor o papel de mero pós-editor de textos, a autora pontua questões práticas e teóricas, especialmente as relacionadas à ética profissional, que emergem com sua utilização. Uma destas questões refere-se eventual esquecimento do caráter humano envolvido na tradução, em meio à vertiginosa circulação eletrônica de textos.A obra também aborda tópicos delicados, como o compartilhamento de memórias, neste caso sob três perspectivas: a do cliente, a das agências de tradução e a do próprio tradutor. Traz à tona ainda as discussões sobre a pulverização da responsabilidade do tradutor em grandes projetos e as questões éticas envolvidas no intercâmbio de memórias, além da questão financeira e da polêmica sobre a propriedade intelectual, contexto que sugere, para o futuro, a possibilidade reestruturação na remuneração do tradutor e da prática de reutilização de memórias.', '["translation memory systems","Trados","transit","translator responsibility","memory sharing","translation agencies","intellectual property","translator remuneration","post-editing"]', '10.7476/9788568334461', '9788568334461', 'https://books.scielo.org/id/2fpsy', 'https://books.scielo.org/id/2fpsy/pdf/stupiello-9788568334461.pdf', NULL, 'https://books.scielo.org/id/2fpsy/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2fq67', '2fq67', 'Rasuras narrativas: das mutações entre “Frankenstein” e “Poor things”', NULL, '["Rita de Cássia Silva Sacramento"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro é o resultado de uma pesquisa sobre a escrita do autor escocês Alasdair Gray na composição de seu livro Poor things (1992). O trabalho de Gray é uma desleitura do romance Frankenstein (1818), da escritora Mary Shelley. Na obra o monstro aparece como feminino. Numa perspectiva comparativa e inovadora, renovando as temáticas.', '["Alasdair Gray","Poor Things","Mary Shelley","Frankenstein","literary rewriting","female monsters","comparative literature","Scottish fiction"]', '10.7476/9786588211946', '9786588211694', 'https://books.scielo.org/id/2fq67', 'https://books.scielo.org/id/2fq67/pdf/sacramento-9786588211946.pdf', 'https://books.scielo.org/id/2fq67/epub/sacramento-9786588211946.epub', 'https://books.scielo.org/id/2fq67/cover/cover_thumbnail.jpeg', 162, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2ftjs', '2ftjs', 'A formação continuada sob análise do professor escolar', NULL, '["Fernanda Rossi","Dagmar Aparecida Cynthia França Hunger"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os debates nacionais e internacionais sobre o trabalho docente cada vez mais destacam a formação continuada dos professores como um dos fatores fundamentais para a atividade. Além de preparar e qualificar os profissionais do ensino, a formação continuada produz a profissão e a profissionalidade. Mas o que tal formação representa para os próprios professores e o que significa de fato para seu desenvolvimento profissional e a prática pedagógica? Estas são as principais questões avaliadas neste estudo, desenvolvido com base em depoimentos de professores da educação básica da rede pública de ensino de Bauru, no interior paulista. As autoras verificaram que, apesar de sua importância, a formação continuada não tem trazido os benefícios esperados para o desempenho em sala de aula ou para o desenvolvimento profissional do docente. Um dos motivos, afirmam elas, é o fato do professor não ser considerado no processo “como um sujeito ativo de seu próprio desenvolvimento, suas experiências adquiridas no exercício da profissão docente e seus conhecimentos construídos nas suas histórias de vida”. O livro reúne material para reflexões em torno de questões diversas, como a visão dos professores a respeito do papel da escola na formação continuada dos professores, sua participação nas etapas de construção e implementação dessas ações e as necessidades e expectativas relacionadas à prática.', '["continuing teacher education","teacher professional development","teacher perceptions","teacher professionalism","teaching practice","life histories of teachers","Bauru"]', '10.7476/9786557144787', '9786557144787', 'https://books.scielo.org/id/2ftjs', 'https://books.scielo.org/id/2ftjs/pdf/rossi-9786557144787.pdf', NULL, 'https://books.scielo.org/id/2ftjs/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2gm55', '2gm55', 'Dimensionamento de elementos e ligações em estruturas de aço', NULL, '["Alex Sander Clemente De Souza"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', '[RETIRADO/WITHDRAWN] Este texto pretende ser uma ferramenta de auxílio ao entendimento do comportamento das estruturas metálicas em aço, ao processo de projeto e à disseminação da norma brasileira de projeto de estruturas metálicas NBR 8800:2008. São apresentados e discutidos os conceitos teóricos fundamentais para a análise e o dimensionamento de elementos estruturais e ligações em estruturas de aço segundo a NBR 8800:2008. No final de cada capítulo são apresentados exemplos de aplicação com enfoque na análise estrutural e no dimensionamento de elementos submetidos aos diversos tipos de esforços solicitantes.', '["steel structures","structural design","steel members","steel connections","structural analysis","design codes"]', '10.7476/9786580216130', '9786580216130', 'https://books.scielo.org/id/2gm55', NULL, NULL, 'https://books.scielo.org/id/2gm55/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2gqk8', '2gqk8', 'A tentação fascista no Brasil: imaginário de dirigentes e militantes integralistas', NULL, '["Hélgio Trindade"]', 'Editora da UFRGS', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Embora o conteúdo deste livro esteja focado na análise das entrevistas com ex-dirigentes e militantes do integralismo, no seu “Epílogo: ainda a tentação fascista no Brasil?” discute-se a nova conjuntura mundial e brasileira. Não se pode subestimar a importância dos novos populismos de direita que, desde a década de 1980, emergiram na Europa, especialmente os partidos, movimentos e governos que tiveram uma ascensão considerável nos principais países. Hoje o Integralismo faz parte da literatura internacional sobre o fascismo. Para Stanley Payne (University of Wisconsin), “o único que alcançou real importância e que, de fato, se converteu no único grande partido latino-americano que se aproximou em quase todos os aspectos do fascismo europeu, foi a AIB de Plínio Salgado, fundada em 1932”. Para além de um trabalho acadêmico o livro traduz de forma extraordinária o que o fascismo significou para os brasileiros que se uniram ao movimento, o surgimento de Plínio Salgado, seu líder, no contexto político do início da década de 30, a organização e, o que é mais importante, o espírito e estilo do movimento. Trata-se de uma obra que nos permite salientar adequadamente temas comuns que definem um movimento como nitidamente fascista, possibilitando descobrir as variedades de fascismo dentro de sua unidade básica e aprofundar a análise das diversas famílias ideológicas no interior do fascismo.', '["Brazilian Integralism","Plínio Salgado","fascism","right-wing populism","fascist movements","Brazilian political history","1930s Brazil","fascist ideology"]', '10.7476/9788538603887', '9788538602927', 'https://books.scielo.org/id/2gqk8', NULL, NULL, 'https://books.scielo.org/id/2gqk8/cover/cover_thumbnail.jpeg', 838, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2h3ks', '2h3ks', 'Comunicação, cultura e linguagem', NULL, '["Anita Simis","Anna Flora Brunelli","Arlindo Rebechi","Carlo José Napolitano","Lucilene dos Santos Gonzales","María Cristina Gobbi","Suely Maciel"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'em escolas públicas brasileiras 405 Francisco Rolfsen Belda e Muna Muhammad Odeh Breve apresentaçãoA obra Comunicação, cultura e linguagem surgiu de um debate promovido pela Pró-Reitoria de Pesquisa (PROPe/Unesp), no ano de 2013, cujo principal objetivo foi reunir seus diversos pesquisadores das Humanidades para que pudessem trocar experiências em seus respectivos saberes.Foi nessa ocasião que, agrupados por afinidades, os pesquisadores de Comunicação, em suas diversas faces e linhas de pesquisa, puderam iniciar um intenso trabalho de organização desses artigos.O propósito era desenvolver uma iniciativa que, a um só tempo, pudesse demonstrar o estado da questão no campo da Comunicação e também demonstrasse a experiência singular e atuante dos pesquisadores dessa área no âmbito da Unesp.Alinhada ao espírito da coleção Desafios Contemporâneos, esta obra procura reunir reflexões sobre os problemas contemporâneos que dialogam com o campo acadêmico e científico da área da Comunicação.Depois de um longo percurso de reflexão, foram criados três eixos norteadores dentro da obra, a saber:(1) As múltiplas formas de linguagem e produção de sentido:eixo preocupado em investigar o campo da produção, da 10 ANITA S.• ANNA B.• ARLINDO JR.• CARLO N.• LUCILENE G.• MARIA G.• SUELY M. (ORGS.', '["communication","culture","language","meaning production"]', '10.7476/9788579835605', '9788579835605', 'https://books.scielo.org/id/2h3ks', 'https://books.scielo.org/id/2h3ks/pdf/simis-9788579835605.pdf', NULL, 'https://books.scielo.org/id/2h3ks/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2h3sk', '2h3sk', 'A enunciação imagética em tecnologias de inteligência artificial: algoritmos e produção de sentido', 'algoritmos e produção de sentido', '["Henrique da Silva Pereira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A enunciação imagética a partir de tecnologias de inteligência artificial é o tema da presente pesquisa que reflete sobre a compreensão da produção de sentido na comunicação midiática no cenário contemporâneo. Fundamentada nas contribuições do aporte teórico-metodológico da semiótica discursiva de linha francesa, notadamente as questões relativas à enunciação e ao nível discursivo do percurso gerativo da significação, o trabalho parte das matrizes conceituais elaboradas por Benveniste (1989), Greimas (1974) e Greimas e Courtés (2016). Compreendida como instância que permite fazer-ser o sentido e como procedimento de manifestação por meio da seleção paradigmática e combinação sintagmática, a enunciação entendida como termo complexo que implica na projeção de enunciador e enunciatário, é, nesta pesquisa, a instância onde são identificados os papeis dos atores da enunciação.', '["enunciation","imagery","artificial intelligence","algorithms","meaning production","media communication","Benveniste","Greimas"]', '10.7476/9786559544493', '9786559544493', 'https://books.scielo.org/id/2h3sk', 'https://books.scielo.org/id/2h3sk/pdf/pereira-9786559544493.pdf', NULL, 'https://books.scielo.org/id/2h3sk/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2hdrc', '2hdrc', 'Violência sexual e o direito ao aborto legal no Brasil: fatos e reflexões', NULL, '["Camila Giugliani","Ângela Ester Ruschel","Gregório Corrêa Patuzzi","Maura Carolina Belomé da Silva"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-08-09', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra realiza uma discussão sobre o direito à interrupção de gestações decorrentes de violência sexual no Brasil. Parte-se da contextualização histórica e social dos direitos sexuais e reprodutivos, passando pela análise da literatura científica nacional sobre o tema, contemplando o panorama jurídico, dados epidemiológicos e cenário assistencial, para então discutir as barreiras e estratégias de superação dos desafios impostos.', '["sexual violence","abortion rights","legal abortion","sexual and reproductive rights","abortion law","abortion access barriers"]', '10.7476/9786557081099', '9786557080405', 'https://books.scielo.org/id/2hdrc', NULL, NULL, 'https://books.scielo.org/id/2hdrc/cover/cover_thumbnail.jpeg', 136, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2jmrz', '2jmrz', 'As formas do silêncio: no movimento dos sentidos', NULL, '["Eni Puccinelli Orlandi"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'As formas do silêncio tem como fio condutor a apresentação dos sentidos do silêncio, e é isto que o estudioso da linguagem encontrará aqui, desenvolvido com a cautela de quem cuida de explorar os entremeios tanto das disciplinas como das diferentes teorias da linguagem, procurando, no entanto, uma especificidade. Silêncio que atravessa as palavras, que existe entre elas, ou que indica que o sentido pode sempre ser outro, ou ainda aquilo que é o mais importante nunca se diz; todos esses modos de existir dos sentidos e do silêncio nos indicam que este é fundante. Sendo assim, nessa reflexão, a autora procura indicar as várias pistas pelas quais se chega ao princípio da significação.', '["silence","meaning","theory of meaning","linguistic theory","unsaid","philosophy of language"]', '10.7476/9788526814707', '9788526807556', 'https://books.scielo.org/id/2jmrz', NULL, NULL, 'https://books.scielo.org/id/2jmrz/cover/cover_thumbnail.jpeg', 181, 264, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2jykn', '2jykn', 'A salvação pelo ensino primário', 'Bahia (1924-1928)', '["José Augusto Ramos da Luz"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro elucida alguns percursos históricos da educação voltada para a infância na Bahia. A educação foi fortemente influenciada por decisões políticas e econômicas; por isso, compreender o cenário de articulações, de influências e embates desse período, é fundamental para entender esses tempos de mudanças que antecedem a década de 1920 e na qual se consolidaram. Cumpre também assinalar que, em meio ao atraso e conservadorismo, foram tomadas iniciativas políticas e econômicas e acima de tudo pedagógicas que tentaram modernizar a educação baiana. Eram tempos em que o velho e o novo passaram a ser bem demarcados, numa sociedade que vivenciava um processo de modernização sem modernidade, mas que, mesmo assim, produziu intelectuais e políticos que idealizaram e defenderam um modelo de escola voltado para o interior e para o sertão e uma educação que valorizasse a cultura do aluno e o meio geográfico em que ele vivia.', '["primary education","history of education","childhood education","Bahia","educational modernization","pedagogical reform","rural education","sertão","education policy","19th century"]', '10.7476/9788555921704', '9788599799765', 'https://books.scielo.org/id/2jykn', NULL, NULL, 'https://books.scielo.org/id/2jykn/cover/cover_thumbnail.jpeg', 270, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2k2mb', '2k2mb', 'História oral: desafios para o século XXI', NULL, '["Marieta de Moraes Ferreira","Tania Maria Fernandes","Verena Alberti"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2000, '2000-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'desafios para o século XXI Maneta de Moraes Ferreira Tania Maria Fernandes Verena Alberti (orgs.)Que desafios se apresentam para a história oral no século XXI? Será que ela pode modificar os modos de viver e de pensar no terceiro milênio?Quais os pontos comuns da história oral praticada em diferentes regiões do mundo?Que diferenças aparecem nas abordagens teóricometodológicas? Essas e outras questões estão tratadas nesse conjunto de textos apresentados por conferencistas de diferentes países no X Congresso Internacional de História Oral, realizado no Rio de Janeiro, em junho de 1998.', '["oral history","21st century","theoretical and methodological approaches"]', '10.7476/9788575412879', '9788575412879', 'https://books.scielo.org/id/2k2mb', 'https://books.scielo.org/id/2k2mb/pdf/ferreira-9788575412879.pdf', NULL, 'https://books.scielo.org/id/2k2mb/cover/cover_thumbnail.jpeg', NULL, 18, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2kv6c', '2kv6c', 'Caleidoscópio Primo Levi: ensaios sobre um poliédrico quimiscritor', NULL, '["Aislan Camargo Maciera","Luciana Massi"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Primo Levi (1919-1987), italiano de origem judaica, químico, sobrevivente dos campos de concentração e extermínio nazistas, é considerado um dos principais nomes da literatura que surge da experiência nos campos de concentração. Através de sua literatura, promove uma reflexão não somente sobre a Shoah, mas também sobre a própria condição humana. Mas, muito além do testemunho, a obra de Levi se constitui em uma complexidade de temas e gêneros, o que o torna um autor poliédrico. Nessa perspectiva, o objetivo desta coletânea é apresentar as várias faces desse poliedro, partindo de seu testemunho, passando pela ficção, pela fantasia, pelo romance, pelos ensaios críticos e escritos de divulgação científica, para formar, em sua totalidade, a imagem de um dos mais significativos pensadores do século XX, que ainda tem muito a dizer ao leitor do século XXI.', '["Primo Levi","Holocaust literature","Holocaust testimony","Auschwitz survivors","Holocaust","human condition","critical essays","fiction","fantasy","Italian literature","20th-century literature"]', '10.7476/9788526815391', '9786586253887', 'https://books.scielo.org/id/2kv6c', NULL, NULL, 'https://books.scielo.org/id/2kv6c/cover/cover_thumbnail.jpeg', 230, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2m678', '2m678', 'História de São Paulo colonial', NULL, '["Maria Beatriz Nizza da Silva","Carlos de Almeida Prado Bacellar","Eliana Rea Goldschmidt","Lúcia Maria Bastos Pereira das Neves"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta obra aborda aspectos da história da Capitania de São Paulo, abrangendo seus primórdios, quando se chamava Capitania de São Vicente e pertencia a donatários; o período mais complexo em que, depois de se denominar Capitania de São Paulo e das Minas de Ouro, perdeu grande parte de seu território e passou a estar subordinada ao governo do Rio de Janeiro; e finalmente o período da restauração de sua autonomia até ser agitada pelo movimento constitucional.', '["territorial loss","constitutional movement","colonial Brazil"]', '10.7476/9788539304400', '9788571398672', 'https://books.scielo.org/id/2m678', NULL, NULL, 'https://books.scielo.org/id/2m678/cover/cover_thumbnail.jpeg', 346, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2mvbb', '2mvbb', 'Ação afirmativa: conceito, história e debates', NULL, '["João Feres Júnior","Luiz Augusto Campos","Verônica Toste Daflon","Anna Carolina Venturini"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Produto de quase duas décadas de pesquisa, a obra investiga o papel da ação afirmativa na democratização da universidade pública. Apresenta ao leitor um olhar sobre a complexidade dessa política pública, analisando seus aspectos conceituais, jurídicos e morais, assim como as perspectivas históricas, políticas e administrativas. A leitura possibilita não apenas compreender melhor o contexto das posições favoráveis e contrárias às políticas afirmativas, mas também compartilhar de saberes sobre os atores sociais envolvidos, com destaque para a imprensa, e sobre os desdobramentos da adoção dessa estratégia de inclusão em outros países', '["affirmative action","higher education access","public policy","social inclusion","history of affirmative action","social actors"]', '10.7476/9786599036477', '9786599036477', 'https://books.scielo.org/id/2mvbb', 'https://books.scielo.org/id/2mvbb/pdf/feres-9786599036477.pdf', NULL, 'https://books.scielo.org/id/2mvbb/cover/cover_thumbnail.jpeg', NULL, 91, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2nc9y', '2nc9y', 'Quimiometria: conceitos, métodos e aplicações', NULL, '["Márcia M. C. Ferreira"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Chemistry', 'A quimiometria surgiu da necessidade de extrair informações químicas da profusão de dados resultantes da moderna instrumentação. Neste livro são abordados os principais métodos de tratamento de dados de natureza multivariada, iniciando com a apresentação das técnicas utilizadas na sua preparação. A seguir, são abordados os métodos de análise exploratória: análise de componentes principais (PCA) e análise de agrupamentos por métodos hierárquicos (HCA). Modelos quantitativos são construídos utilizando os métodos de regressão linear múltipla (MLR), componentes principais (PCR) e quadrados mínimos parciais (PLS). Métodos supervisionados de reconhe­cimentos de padrões do k-ésimo vizinho mais próximo (k-NN), SIMCA, e a análise discriminante PLS-DA são discutidos na construção dos modelos de classificação. Todos os capítulos incluem rotinas computacionais e vários exemplos.', '["chemometrics","multivariate analysis","principal component analysis","hierarchical clustering","multiple linear regression","principal component regression","partial least squares","k-nearest neighbors","SIMCA","PLS-DA","classification models","data preprocessing"]', '10.7476/9788526814714', '9788526810631', 'https://books.scielo.org/id/2nc9y', NULL, NULL, 'https://books.scielo.org/id/2nc9y/cover/cover_thumbnail.jpeg', 493, 187, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2ndtk', '2ndtk', 'Atenção Psicossocial além da Reforma Psiquiátrica: contribuições a uma Clínica Crítica dos processos de subjetivação na Saúde Coletiva', NULL, '["Abílio da Costa-Rosa"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'A obra reúne uma série de ensaios produzidos a partir da preocupação do autor em colaborar com o desenvolvimento de diferentes aspectos da Atenção psicossocial. Para ele, a Atenção psicossocial é o “conjunto de ações realizadas no campo da saúde mental, geralmente denominadas tratamento, cuidado, promoção e mesmo atenção” A definição do paradigma de Atenção psicossocial é o objeto dos ensaios e lhes dá unidade, embora cada texto possa ser lido independentemente. Para o autor, o termo “psicossocial”, que tradicionalmente se referia apenas a aspectos psíquicos e sociais secundários à prática psiquiátrica, passou a aspirar o status de conceito, determinando um novo campo da práxis, a partir do momento em que a crítica mais radical à atividade psiquiátrica contribui para sua transformação. Nas últimas décadas, desde que o Ministério da Saúde estabeleceu a Atenção psicossocial como política pública nacional, delimitou-se um campo de saberes baseados em um ideário ético-político que veio a substituir a psiquiatria centrada nas práticas hospitalares e médicas. E, embora hoje o antigo modo de exercício da psiquiatria se encontre subordinado ideologicamente, continua sendo percebido nas práticas cotidianas. De acordo com o autor, “este conjunto de ensaios, com as preocupações teóricas, técnicas e éticas que os atravessam, pretende ser uma contribuição para melhorar nossas caixas de ressonância para a receptividade das demandas dos indivíduos que nos procuram nas instituições substitutivas do manicômio e do hospital psiquiátrico”.', '["psychosocial care","psychiatric reform","critical psychiatry","subjectivation","public health","mental health policy","psychiatric hospitals","care ethics"]', '10.7476/9786557144817', NULL, 'https://books.scielo.org/id/2ndtk', 'https://books.scielo.org/id/2ndtk/pdf/costa-9786557144817.pdf', NULL, 'https://books.scielo.org/id/2ndtk/cover/cover_thumbnail.jpeg', NULL, 27, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2p5cs', '2p5cs', 'A profetisa e o historiador: sobre A Feiticeira de Jules Michelet', NULL, '["Maria Juliana Gambogi Teixeira"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '"O Michelet que a estudiosa nos restitui é, em mais de um aspecto, estimulante, apaixonante e é de se desejar que este livro seja lido como participante de um bom número de debates intelectuais, hoje importantes na Europa, mas também (até onde sei), na America Latina. De qualquer forma, o estudo de Juliana Gambogi se inscreve numa verdadeira interdisciplinaridade, o que é, certamente, uma de suas maiores qualidades. Deveria, por consequência, interessar a um público diversificado, e não apenas aos historiadores de profissão. (...) Juliana Gambogi soube manter reunidos os diferentes aspectos do raciocínio de Michelet, e apontar de que modo eles se articulam; mas também soube analisá-los com grande rigor, demonstrando como poderemos reencontrá-los, sob distintas formas, no conjunto do corpus micheletiano. (...) E este será , ainda, um do êxitos desde estudo: fornecer ferramentas para a leitura de uma grande parte da obra de Michelet ao se fixar, preferencialmente, sobre apenas um de seus livros. A autora soube, com perfeição, revelar a exemplaridade de A Feiticeira , tirando proveito máximo disso e tornando seu livro uma excelente introdução da obra de Jules Michelet."', '["Jules Michelet","La Sorcière","witchcraft","witch trials","prophetic literature","historiography","history and literature"]', '10.7476/9788542302882', '9788542301595', 'https://books.scielo.org/id/2p5cs', NULL, NULL, 'https://books.scielo.org/id/2p5cs/cover/cover_thumbnail.jpeg', 312, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2p9rw', '2p9rw', 'Celso Furtado: a esperança militante (Depoimentos): vol. 2', NULL, '["Cidoval Morais de Sousa","Ivo Marcos Theis","José Luciano Albino Barbosa"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Celso Furtado (1920-2004) era um republicano exemplar. É assim que o define o sociólogo Francisco de Oliveira neste Volume 2 da Trilogia Celso Furtado: a esperança militante. Trata-se de uma coletânea de quase duas dezenas de depoimentos de pessoas que trabalharam, estudaram e/ou acompanharam, de perto, a carreira intelectual e política do paraibano de Pombal, que se dizia, antes de mais nada, um otimista. Apostava no homem e na sua capacidade criativa, e pensava o Brasil com independência, método e paixão. Vivia intensamente o que pregava: o valor de um cientista resulta da combinação dos ingredientes imaginação e coragem. Em muitos casos, dizia ele, cabe-lhe também atuar de forma consistente no plano político e, portanto, assumir a responsabilidade de interferir no processo histórico. Nas próximas páginas, o testemunho de quem experimentou de perto essa rica história de esperança.', '["Celso Furtado","republican thought","Brazilian political thought","political activism","optimism","intellectual history"]', '10.7476/9786586221671', '9786586221671', 'https://books.scielo.org/id/2p9rw', 'https://books.scielo.org/id/2p9rw/pdf/sousa-9786586221671.pdf', NULL, 'https://books.scielo.org/id/2p9rw/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2pwn4', '2pwn4', 'A página violada: da ternura à injúria na construção do livro de artista', NULL, '["Paulo Antonio de Menezes Pereira da Silveira"]', 'Editora da UFRGS', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro de artista é um produto da arte contemporânea, construído deliberadamente a partir de um suporte preexistente, o livro, que é o seu protótipo, e ao qual louva ou faz contraposição crítica. A página e a estrutura podem ser enaltecidas ou sofrer todas as possibilidades de injúria e objeção, até alcançarem o estatuto da escultura e abandonarem a condição objetiva de livro. A página violada, de Paulo Silveira, propõe que as gradações percebidas não só podem como devem ser instrumentos da conceitualização e caracterização da obra e da categoria na qual ela se insere, desde certos exemplares do livro ilustrado até todo e qualquer livro-objeto. São apresentadas cerca de duzentas obras através de mais de seiscentas imagens, que também incluem eventos e documentos, a maioria delas coloridas e originais para este trabalho.', '["artist''s book","book pages","book materiality","contemporary art","book illustration","book structure"]', '10.7476/9788538603900', '9788538603900', 'https://books.scielo.org/id/2pwn4', 'https://books.scielo.org/id/2pwn4/pdf/silveira-9788538603900.pdf', NULL, 'https://books.scielo.org/id/2pwn4/cover/cover_thumbnail.jpeg', NULL, 30, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2py6x', '2py6x', 'Dois séculos de dívida pública: a história do endividamento público brasileiro e seus efeitos sobre o crescimento econômico (1822-2004)', NULL, '["Guilherme Antonio Ziliotto"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Na história do Estado brasileiro, o papel da dívida pública, a inten­sidade de seu uso e seus efeitos sobre a economia variaram muito. Em vários momentos, o endividamento público foi utilizado ampla­mente como forma de financiamento de projetos estatais; outras vezes, a dívida pública assumiu um caráter tão vultoso que passou a ser acusada de ser mais maléfica do que benéfica à economia; e em outros períodos, foi praticamente relegada ao esquecimento. Tentando contribuir para a compreensão desses aspectos da história das finanças públicas do país, este livro procura analisar, na história do Estado brasileiro, a hipótese de causalidade entre o endividamento público e o crescimento econômico e sintetizar a história da dívida pública no Brasil, de 1822 a 2004, com base na historiografia dominante sobre o tema e nos dados e documentos históricos mais relevantes e difundidos. Essa síntese foi feita também no sentido de dar um elemento adicional à análise sobre a relação entre dívida pública e crescimento econômico, por uma perspectiva de análise histórica, complementando a análise econométrica.', '["public debt","economic growth","fiscal history","Brazilian states"]', '10.7476/9786557145241', '9786557145241', 'https://books.scielo.org/id/2py6x', 'https://books.scielo.org/id/2py6x/pdf/ziliotto-9786557145241.pdf', NULL, 'https://books.scielo.org/id/2py6x/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2pykd', '2pykd', 'Guia básico de morfologia interna de carrapatos ixodídeos', NULL, '["Mathias, Maria Izabel Camargo"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Immunology and Microbiology', 'Conjunto de artigos produzidos por um grupo de especialistas, esta obra dirige-se a pesquisadores em busca de estudos consistentes sobre a morfologia interna de carrapatos. Apresenta pesquisas que tratam especificamente da morfologia interna e dos diferentes órgãos de ixodídeos (sistema digestório, glândulas salivares, corpo gorduroso, sistema reprodutor feminino e sistema traqueal). Parasitas hematófagos de vertebrados, os carrapatos têm sido objeto de preocupação da população mundial porque transmitem patógenos a seus hospedeiros e trazem danos à produção de leite, carne e couro, quando infestam animais de produção. Estima-se que os gastos com programas de controle desse artrópode no Brasil sejam da ordem de 2 bilhões de dólares por ano. Nas áreas urbanas, onde hospedam-se preferencialmente em cães e gatos, os carrapatos adquiriram resistência a métodos artificiais de controle, com consequente sucesso adaptativo, tornando-se um problema no ambiente doméstico.', '["ticks","Ixodidae","internal morphology","tick anatomy","digestive system","salivary glands","fat body","female reproductive system","tracheal system","hematophagous arthropods","tick-borne pathogens","livestock ticks"]', '10.7476/9786557144763', '9786557144763', 'https://books.scielo.org/id/2pykd', 'https://books.scielo.org/id/2pykd/pdf/mathias-9786557144763.pdf', NULL, 'https://books.scielo.org/id/2pykd/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2qn3d', '2qn3d', 'Formas de matar, de morrer e de resistir', 'limites da resolução negociada de conflitos ambientais', '["Zhouri, Andréa","Valencio, Norma"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro trata de processos de resolução negociada de conflitos ambientais em curso no Brasil e de seus limites. As técnicas de governo forjadas no âmbito de instituições financeiras globais são consideradas inapropriadas para tratar de processos históricos e políticos que envolvem a diversidade de sujeitos sociais do país e as condições de desigualdade às quais estão submetidos. Quando a economia subsume a política e a justiça, o resultado é a perpetuação da subalternidade pela continuidade das formas de colonialidade do saber e o poder.', '["environmental dispute resolution","international financial institutions","neoliberal governance","subalternity","coloniality of knowledge","social inequality","economics and politics","Brazil"]', '10.7476/9786558582120', '9788542300772', 'https://books.scielo.org/id/2qn3d', NULL, NULL, 'https://books.scielo.org/id/2qn3d/cover/cover_thumbnail.jpeg', 395, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2qpn8', '2qpn8', 'Darwinismo e racismo científico no Brasil', NULL, '["Cláudia Sepúlveda","Yaci Farias","Ricardo Machado","Juanma Sánchez Arteaga"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Entre 1870 e 1930, médicos, bacharéis de direito, antropólogos e literatos, que compunham a elite intelectual brasileira, adotaram diversas interpretações das teorias evolutivas de Darwin para propor uma solução científica para o suposto problema de civilizar uma nação miscigenada. Qual a relação entre a adesão ao darwinismo por esses intelectuais e o modo como a elite econômica e o Estado lidaram com as massas de ex-escravizados no período pós-abolição? Qual a relação entre esses discursos e práticas e as tensas relações étnico-raciais e desigualdades sociais que até hoje enfrentamos no Brasil? Essas são questões que os autores pretendem discutir de modo a motivar e apoiar professoras e professores de diferentes áreas de conhecimento a desenvolverem uma educação antirracista, segundo os princípios dispostos nas leis 10.639/03 e 11.645/08, tendo como base a história do racismo científico no Brasil. Para tanto, fazem uso de linguagem acessível; apresentam curtas biografias de importantes personagens, com ilustrações dos mesmos e de instituições de saber em seu tempo histórico de atuação; apontam orientações de como determinados episódios históricos podem ser abordados em sala de aula, e apresentam obras e gêneros da literatura brasileira que divulgaram ou problematizaram os modelos raciais de análise da sociedade, pautados no evolucionismo darwinista, entre os séculos XIX e XX.', '["scientific racism","Darwinism","racial theory","racial inequality","interethnic relations","anti-racist education","Law 10.639/2003","Law 11.645/2008","Brazilian intellectuals","Brazilian literature"]', '10.7476/9788555921162', '9786589524489', 'https://books.scielo.org/id/2qpn8', NULL, NULL, 'https://books.scielo.org/id/2qpn8/cover/cover_thumbnail.jpeg', 98, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2qyk6', '2qyk6', 'O Diretório dos Índios na América Portuguesa: aplicação e adaptações (1757-1808)', 'aplicação e adaptações (1757-1808)', '["F. L. B. Santos","Karl Heinz Arenz","Vanice Siqueira de Melo","Wania Alexandrino Viana"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro O Diretório dos Índios na América Portuguesa: aplicações e adaptações (1757-1808) reflete a expansão das pesquisas realizadas nos últimos anos sobre o Diretório dos Índios nos domínios portugueses na América. A ampliação desses estudos permitiu compreender de que maneira uma lei, inicialmente redigida para ser implementada na atual Região Amazônica, foi praticada, com adaptações, no restante do Brasil. Dessa forma, a obra aponta a diversidade das realidades vivenciadas durante a aplicação do Diretório dos Índios nos domínios portugueses na América. Os capítulos deste livro contemplam discussões que abrangem uma variedade de abordagens, algumas das quais pouco exploradas, como a política linguística indígena e a relação dos povos indígenas com o espaço e o mundo natural.', '["indigenous peoples","colonial Brazil","indigenous law","law implementation","indigenous language policy","indigenous space","18th century"]', '10.7476/9786556309057', '9786556307633', 'https://books.scielo.org/id/2qyk6', 'https://books.scielo.org/id/2qyk6/pdf/santos-9786556309057.pdf', NULL, 'https://books.scielo.org/id/2qyk6/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2r9cy', '2r9cy', 'Intercooperação e redes de cooperativas no Rio Grande do Sul', NULL, '["Angélica Leoní Albrecht Gazzoni"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', '(Menção Honrosa 8º Prêmio ABEU 2022) Este livro circunda as diversas temáticas que envolvem o cooperativismo e a formação de redes, trazendo uma importante revisão dos aspectos que englobam a comercialização de alimentos pelas redes de cooperativas organizadas por agricultores e suas entidades representativas. Portanto, apresenta conteúdo de interesse do meio acadêmico das Ciências Agrárias e Sociais e serve de apoio atualizado sobre o tema e de embasamento teórico-prático aos técnicos, engenheiros e extensionistas da extensão rural ou da assistência técnica especializada, assim como aos cooperativistas, os quais, a partir do conteúdo apresentado, podem aperfeiçoar e/ou incorporar novos métodos de organização e administração cooperativa. Igualmente, interessa ao público geral que busca conhecer novos mecanismos de ação coletiva. Além disso, a obra traduz em suas entrelinhas a experiência de seis anos (2012 a 2018) da autora na execução do Programa de Extensão Cooperativa (PEC/RS), criado em 2011 no RS e executado pela Emater/RS através das sete Unidades de Cooperativismo (UCPs) formada por profissionais multidisciplinares com o objetivo de assessorar as cooperativas agropecuárias.', '["agricultural cooperatives","cooperative networks","inter-cooperative cooperation","food marketing","farmer groups","agricultural extension","cooperative extension programs","collective action","cooperative management","Rio Grande do Sul"]', '10.7476/9786586545685', '9786586545685', 'https://books.scielo.org/id/2r9cy', 'https://books.scielo.org/id/2r9cy/pdf/gazzoni-9786586545685.pdf', NULL, 'https://books.scielo.org/id/2r9cy/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2rxjb', '2rxjb', 'Uso público em áreas protegidas: contribuições para gestão de unidades de conservação', NULL, '["Davis Gruber Sansolo"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Este livro deriva de uma pesquisa sobre uso público em unidades de conservação (UC), realizada pelo Laboratório de Planejamento Ambiental e Gerenciamento Costeiro (Laplan), sediado no Instituto de Biociências da Universidade Estadual Paulista (Unesp), câmpus Litoral Paulista. O estudo estimulou, em 2017, a realização do I Encontro sobre Uso Público em Unidades de Conservação. Diversos trabalhos e palestras foram apresentados; alguns deles participam desta obra. Qual a finalidade do programa de uso público em uma unidade de conservação? Os parques têm como um dos principais motivos de sua existência a promoção da educação ambiental e da visitação pública em uma UC. Tal finalidade lhes confere a função relacional entre o bem comum, como valor da natureza e sua dinâmica conservada, e os diversos sujeitos que se relacionam com esses territórios protegidos. A conservação da natureza é um direito de todos, mas, para que todos tenham esse direito, é necessário compreender os significados que a sociedade confere a esses territórios. E esse é, portanto, o principal papel do programa de uso público de uma unidade de conservação.', '["public use of protected areas","protected area management","nature conservation","environmental education","common good","access to nature"]', '10.7476/9786557140123', '9786557140123', 'https://books.scielo.org/id/2rxjb', 'https://books.scielo.org/id/2rxjb/pdf/sansolo-9786557140123.pdf', NULL, 'https://books.scielo.org/id/2rxjb/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2s7y9', '2s7y9', 'Os nervos e os ossos do ofício: uma análise etnológica da aula de Anatomia', NULL, '["Ana Carolina Biscalquini Talamoni"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Os personagens 67 5 Lições de Anatomia... 93 Considerações finais 153 Referências 159A figura do anatomista, por sua vez, também é uma construção sócio-histórica que garante a tradição que caracteriza a comunidade anatômica.Esse encontro de elementos sociais, históricos e culturais que confluem para a aula de Anatomia transcende os aspectos didático-pedagógicos da mesma, que acaba por se realizar enquanto um fato social no qual cada sujeito tem um papel culturalmente determinado a desempenhar.O percurso dessa área da ciência, como se verá adiante, comportou uma série de dificuldades e, por que não, de imposturas éticas e filosóficas que desafiaram o conhecimento tradicional/religioso acerca do corpo e culminaram em outra história: a da dissecação.Os entraves enfrentados para a legalização da prática anatômica se deram a nível prático, moral, legal, mas, sobretudo, a nível simbólico, tendo sido necessária uma reorientação das sensibilidades.O processo de dessacralização do corpo permitiu que se assumisse explicitamente a ambiguidade do cadáver, fonte de curiosidade e ao mesmo tempo de horror e repugnância.O estabelecimento da Anatomia ocorreu em consonância com o desejo humano de compreender o próprio corpo e de superar seus temores mais profundos.', '["anatomy education","history of anatomy","anatomists","dissection","corpses","body and religion","ethics of dissection","medical education"]', '10.7476/9788568334430', '9788568334430', 'https://books.scielo.org/id/2s7y9', 'https://books.scielo.org/id/2s7y9/pdf/talamoni-9788568334430.pdf', NULL, 'https://books.scielo.org/id/2s7y9/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2sbzx', '2sbzx', 'Erotismo e religiosidade: romances de Antônio da Fonseca Soares sobre mulheres', NULL, '["Carlos Eduardo Mendes de Moraes"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Conjunto de estudos produzido por pesquisadores da área de Letras, este livro trata da obra de um curioso personagem, Antônio da Fonseca Soares, autor português do século XVIII. A singularidade do poeta e orador está no fato dele ter produzido uma obra vasta, parte composta por poemas eróticos, satíricos e lírico-amorosos, assinada por Antônio da Fonseca Soares, e parte relativa a uma oratória fervorosamente religiosa, assinada por Frei Antônio das Chagas, nome sob o qual se tornou mais conhecido. O segundo personagem emerge após a conversão do poeta à vida monástica. Essa escolha motivou o poeta, que havia se exilado voluntariamente no Brasil, a escrever uma carta a Dom Francisco de Sousa pedindo para voltar a Portugal na condição de religioso, tornando-se esse documento essencial para se compreender sua conversão. Ao mesmo tempo, a própria escolha do poeta como objeto de estudo deu-se por um “acidente de percurso” durante a elaboração de um guia biográfico e bibliográfico de cerca de duas centenas e meia de autores que assinaram trabalhos nas academias brasílicas da Bahia nos anos de 1724 e 1759. Constatou-se, então, que o nome de Antônio da Fonseca Soares não constava em nenhuma daquelas associações. Mesmo assim, optou-se pela inclusão de 104 de suas produções, em mais de três centenas, que se encontram arquivadas na Biblioteca Geral de Universidade de Coimbra, em Portugal. Os estudos abordam diversas questões sobre o poeta e religioso português e seus escritos, como a relação entre suas identidades e a forma como representou a mulher em sua obra.', '["eroticism","religiosity","representation of women","religious conversion","monasticism","satire","love poetry","women in literature"]', '10.7476/9786557145135', '9786557145135', 'https://books.scielo.org/id/2sbzx', 'https://books.scielo.org/id/2sbzx/pdf/9786557145135.pdf', NULL, 'https://books.scielo.org/id/2sbzx/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2sszd', '2sszd', 'Do erro em composição', NULL, '["Flo Menezes"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Todo construído tendo por base a estrutura expositiva da Ética de Spinoza – talvez o primeiro grande tratado de psicanálise da história –, o presente livro discorre sobre o erro na composição musical. Para tanto, parte de um argumento inicial, pelo qual se afirma que a melhor forma de entender, pensar e ensinar a composição musical é a análise. E analisamos sempre o que mais amamos. Nesse processo, nosso orolho – aquele órgão imaginário e simbiótico entre o olho e a orelha, entre o ouvir e o olhar – detecta os acertos dessas obras que nos guiam e inspiram. Mas e quanto a seus erros? Pois não há obra perfeita, e a imperfeição é mesmo sinal de que a obra é algo vivo e que decorre de fendas que se dão em seu interior, na ausência de verdades absolutas. A fenda é, entretanto, apenas um tipo de erro. Discorrer sobre os erros, diagnosticando seus tipos e avaliando, dentre tais categorias, aqueles que procuramos evitar, aqueles que combatemos, aqueles com os quais forçosamente convivemos, e aqueles que almejamos, é ao que se propõe este livro.', '["music composition","musical analysis","Spinoza''s Ethics","psychoanalysis","music education"]', '10.7476/9786557140529', '9786557140529', 'https://books.scielo.org/id/2sszd', 'https://books.scielo.org/id/2sszd/pdf/menezes-9786557140529.pdf', NULL, 'https://books.scielo.org/id/2sszd/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2svrj', '2svrj', 'Na vida, a trabalho: mobilidade social, escrita de si e marcadores de diferenças na trajetória de Antônio Arantes (Salvador/BA — 1930-2009)', 'mobilidade social, escrita de si e marcadores de diferenças na trajetória de Antônio Arantes (Salvador/BA — 1930-2009)', '["Lucas Porto"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro reconstrói a trajetória de Antônio Honorato de Arantes Filho (1930–2009), trabalhador pardo que, a partir de origens populares e com baixo letramento formal, construiu um percurso singular de ascensão social em Salvador ao longo do século XX. A obra analisa sua experiência como operário têxtil, profissional da construção civil e administrador rural, articulando trabalho, classe e relações raciais em um contexto anterior à consolidação de uma classe média negra na cidade. Com base em manuscritos autobiográficos inéditos, documentos pessoais, processos judiciais, entrevistas e vasto acervo iconográfico, o livro oferece uma leitura sensível das estratégias, limites e estigmas enfrentados por um sujeito “excepcional-normal”. Trata-se de uma contribuição relevante para os estudos sobre mobilidade social, história do trabalho e dinâmicas de cor no Brasil.', '["social mobility","life writing","race relations","Black middle class","textile workers","construction workers","rural administration","race and class","stigmatization","literacy","Salvador, Bahia","history of work"]', '10.7476/9786556309507', '9786556308203', 'https://books.scielo.org/id/2svrj', 'https://books.scielo.org/id/2svrj/pdf/porto-9786556309507.pdf', NULL, 'https://books.scielo.org/id/2svrj/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2sxzv', '2sxzv', '“Trabalhando feito cupim”: experiências educativas decoloniais', 'experiências educativas decoloniais', '["Eduardo Oliveira Miranda","Marta Alencar dos Santos"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra é pautada por questões relacionadas ao universo da mobilidade acadêmica, no cenário da internacionalização do ensino superior, analisando as transições desenvolmentais, as estratégias de afiliação empreendidas, as experiências e influências na vida dos estudantes de graduação. O foco da obra volta-se para as práticas de internacionalização desenvolvidas em uma universidade pública baiana, para compreender como a mobilidade estudantil internacional colabora para a formação universitária e o desenvolvimento humano.', '["decolonial pedagogy","student mobility","internationalization of higher education","academic mobility","undergraduate students","human development","public universities","Bahia"]', '10.7476/9788555921643', '9786589524649', 'https://books.scielo.org/id/2sxzv', NULL, NULL, 'https://books.scielo.org/id/2sxzv/cover/cover_thumbnail.jpeg', 347, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2tjs8', '2tjs8', 'As razões da máquina antropofágica: poesia e sincronia em Haroldo de Campos', NULL, '["Diana Junkes Bueno Martha-Toneto"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A análise de A máquina do mundo repensada, considerado o poema síntese da obra de Haroldo de Campos, é o tema deste livro, cujo título revela a concepção da autora em relação à obra do poeta, tradutor e crítico paulistano. De acordo com a autora a antropofagia é traço presente nas convergências estabelecidas pelo poeta em toda a sua obra. E em relação ao poema analisado, afirma: “o eu-poético, simulacro do próprio Haroldo de Campos, dialoga com a tradição literária, a religião, os mitos de criação e a moderna física quântica em busca de respostas para a origem do universo”. O estudo mostra de que forma o poema é construído e como essa construção reflete o pensamento poético, o estilo, as obsessões e a mitologia do poeta, enfim, sua utopia. Como afirma no prefácio a professora Maria de Lourdes Ortiz Gandini Baldan, “de leitura obrigatória para os estudiosos da poética de Haroldo de Campos, o livro que agora se publica nasce como referência fundamental aos estudos de poesia brasileira”.', '["Haroldo de Campos","cannibalism","synchronicity","Brazilian poetry","poetic voice","literary tradition","religious themes in poetry","creation myths","quantum physics","origin of the universe","poetics","utopia"]', '10.7476/9786557144800', '9786557144800', 'https://books.scielo.org/id/2tjs8', 'https://books.scielo.org/id/2tjs8/pdf/martha-9786557144800.pdf', NULL, 'https://books.scielo.org/id/2tjs8/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2tmzj', '2tmzj', 'Judaísmo para todos', NULL, '["Bernardo Sorj"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este texto es un esfuerzo de actualizar el judaísmo secular y humanista, que en los tiempos modernos orientó a los mayores pensadores, científicos, artistas y activistas judíos, de Spinoza a Hanna Arendt, de Freud a Einstein, de Gershwin a Chagall, de Kafka a Roth, de Theodor Hertzl a Emma Goldman, de Isaac Deutscher a Amos Oz, así como a la gran mayoría de sus premios Nobel. Judíos, que no invocaban libros sagrados o mandamientos divinos para afirmar una identidad judaica, que se nutrieron de la historia y de la cultura judía, de sus dramas psíquicos y existenciales, de lazos particulares de solidaridad cuando los judíos son perseguidos, como de revuelta cuando los judíos actúan sin sensibilidad frente al sufrimiento de los otros.', '["secular Judaism","Jewish identity","Jewish history","Jewish culture","Jewish intellectuals","Jewish artists","Jewish scientists","Jewish activists","persecution of Jews"]', '10.7476/9788579820564', '9788579820564', 'https://books.scielo.org/id/2tmzj', 'https://books.scielo.org/id/2tmzj/pdf/sorj-9788579820564.pdf', NULL, 'https://books.scielo.org/id/2tmzj/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2trwj', '2trwj', 'Certa herança marxista', NULL, '["José Arthur Giannotti"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Nem sempre Marx escreve de pontos de vista convergentes, embora tenha sempre no horizonte a perspectiva da revolução que, assim me parece, lhe permite captar, de forma inovadora, as relações sociais do sistema capitalista e as contradições que as atravessam. Mas isso só lhe é possível porque, em contrapartida, recorre a uma lógica que, pretendendo inverter a lógica hegeliana, sem, entretanto tratar das principais questões levantadas por essa inversão, faz com que possa ir além dos limites postos por uma ciência positiva, a despeito de estar a todo momento reiterando profissão de fé nessa ciência. [trecho retirado do primeiro capítulo do livro]', '["Karl Marx","Hegelian logic","critique of Hegel","capitalist relations","contradictions of capitalism","revolution","Marxist theory","positivism"]', '10.7476/9788579820458', '9788579820458', 'https://books.scielo.org/id/2trwj', 'https://books.scielo.org/id/2trwj/pdf/giannotti-9788579820458.pdf', NULL, 'https://books.scielo.org/id/2trwj/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2ty3q', '2ty3q', 'Literacia em Saúde', NULL, '["Frederico Peres","Karla Meneses Rodrigues","Thais Lacerda e Silva"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-06-09', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Como compreendemos e avaliamos as diversas informações sobre saúde que recebemos? Como podemos usar essas informações para o nosso cuidado e para o cuidado do outro? Em tempos de pandemia, essas são questões ainda mais urgentes diante do excesso de notícias, diagnósticos e assuntos relacionados à saúde que alcançam as pessoas das mais diferentes formas. O livro da coleção Temas em Saúde aborda o conceito de literacia em saúde, que está diretamente associado ao conjunto de habilidades e competências que cada indivíduo possui para buscar compreender, avaliar e dar sentido às informações sobre saúde. Ao longo de quatro capítulos, os autores apresentam a trajetória do conceito e mostram como a literacia em saúde foi se constituindo como elemento estratégico para o pensamento e as práticas relacionados ao campo da saúde em diferentes partes do mundo. O título se estrutura a partir de uma série de debates que podem apoiar os mais diversos profissionais, pesquisadores e interessados no tema.', '["health literacy","health information","health information seeking","health information evaluation","health competence","COVID-19 pandemic","healthcare workers"]', '10.7476/9786557081068', '9786557080337', 'https://books.scielo.org/id/2ty3q', NULL, NULL, 'https://books.scielo.org/id/2ty3q/cover/cover_thumbnail.jpeg', 154, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2w35w', '2w35w', 'Juliano Moreira: da Bahia para o mundo a formação baiana do intelectual de múltiplos talentos (1872-1902)', NULL, '["Ronaldo Ribeiro Jacobina"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O estudo dá prioridade à vida e à obra do baiano Juliano Moreira, no período em que viveu em sua terra natal, desde o seu nascimento em 1872 até 1902, quando transferiu-se para viver no Rio de Janeiro. O livro apresenta os dados biográficos desse importante intelectual baiano afrodescendente, desde o seu nascimento ainda no período escravista, sua formação escolar, com destaque para o período na Faculdade de Medicina, até o desenvolvimento dos seus estudos na dermatologia, e depois na psiquiatra e neurologia. A obra também revela algumas facetas desconhecidas de Moreira, como o trabalho como redator na Gazeta Médica da Bahia e a produção literária e poética.', '["Juliano Moreira","Afro-Brazilian intellectuals","dermatology","psychiatry","neurology","medical education","Faculdade de Medicina da Bahia","Bahia","Rio de Janeiro","slavery","Bahian literature","poetry"]', '10.7476/9786556302652', '9788523218188', 'https://books.scielo.org/id/2w35w', NULL, NULL, 'https://books.scielo.org/id/2w35w/cover/cover_thumbnail.jpeg', 323, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2w3jg', '2w3jg', '(Re)pensando o suicídio: subjetividades, interseccionalidade e saberes pluriepistêmicos', NULL, '["Lima, Luana","Navasconi, Paulo Vitor Palma"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'A obra tem o suicídio como temática central e estrutura-se sob o seguinte tripé: “Leituras críticas à colonialidade e epistemologias contra-hegemônicas”; “Interseccionalidade e populações vulnerabilizadas”; e “Formação, espaços e práticas profissionais”. Privilegiando abordagens insurgentes, o livro se ancora sob pesquisas e questões de gênero, raça, classe, orientação sexual, saberes afro-brasileiros e espaços como hospital, internet e regiões produtivas do agronegócio, sob as lentes da epidemiologia crítica, filosofia, bioética, religião e política.', '["suicide","subjectivity","intersectionality","vulnerable populations","coloniality","Afro-Brazilian knowledge","gender","race","social class","sexual orientation","critical epidemiology","bioethics"]', '10.7476/9786556304991', '9786556304106', 'https://books.scielo.org/id/2w3jg', NULL, NULL, 'https://books.scielo.org/id/2w3jg/cover/cover_thumbnail.jpeg', 241, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2y5zd', '2y5zd', 'Foucault, a arqueologia e As palavras e as coisas – 50 anos depois', NULL, '["Ivan Domingues"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Tendo frequentado os cursos de Foucault no Collège de France entre os anos de 1981 e 1983, em quem vê o interlocutor oculto de sua tese de doutorado defendida mais tarde na Sorbonne, Ivan Domingues faz neste livro uma análise extensa e acurada da obra que o inspirou, As palavras e as coisas – uma arqueologia das ciências humanas. Ao mesmo tempo, realiza uma ansiada homenagem ao eminente filósofo, na ocasião dos 50 anos da obra, lançada em 1966 com grande repercussão na França e pelo mundo afora, inclusive no Brasil.', '["Michel Foucault","The Order of Things","Collège de France","reception of Foucault","history of knowledge","human sciences"]', '10.7476/9786558581239', NULL, 'https://books.scielo.org/id/2y5zd', NULL, NULL, 'https://books.scielo.org/id/2y5zd/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2yqzj', '2yqzj', 'Nova leitura crítica de Jorge Amado', NULL, '["Sudha Swarnakar","Ediliane Lopes Leite de Figueiredo","Patrícia Gomes Germano"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta coletânea de ensaios críticos apresenta nova fortuna crítica deste grande escritor que discute temas ainda inexplorados. Estes artigos são escritos tanto pelos estudiosos amadianos de renome quanto pelos jovens que estreiam suas carreiras de críticos, críticos emergentes que sentiram a necessidade de oferecer uma nova leitura deste escritor controverso nesta ocasião de centenário. Cobrindo um vasto campo: literatura, linguística, história, memória e direito. Esses escritores estão apresentando suas críticas das obras amadianas para chamar atenção, para desmitificar o mito em torno de Amado e também para provocar o leitor a reler obras de Amado no novo século com uma nova perspectiva.', '["Jorge Amado","literary criticism","deconstruction of myth","Brazilian literature"]', '10.7476/9788578793289', '9788578793289', 'https://books.scielo.org/id/2yqzj', 'https://books.scielo.org/id/2yqzj/pdf/swarnakar-9788578793289.pdf', NULL, 'https://books.scielo.org/id/2yqzj/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2yxj2', '2yxj2', 'Redes transnacionales y emergencia de la diplomacia indígena: un estudio a partir del caso colombiano', 'un estudio a partir del caso colombiano', '["Ángela Santamaría"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2008, '2008-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este libro busca analizar, de una manera novedosa, las luchas jurídicas de los Pueblos Indígenas desde las trayectorias sociales de sus protagonistas, utilizando el método etnográfico aplicado a la disciplina de las Relaciones Internacionales, dando cuenta, sin embargo, de procesos estructurales. De esta manera, aporta elementos teóricos y metodológicos para el estudio de la dimensión “transnacional” de las problemáticas globales, desde un tema aparentemente encasillado en perspectivas nacionales o locales. Su público principal son los organismos internacionales, las organizaciones sociales y la comunidad académica nacional e internacional de internacionalistas, antropólogos sociales, politólogos, sociólogos y juristas, y en general estudiosos del tema de los derechos humanos, los Pueblos Indígenas y la globalización jurídica.', '["Indigenous diplomacy","transnational networks","indigenous peoples","legal dispute","indigenous rights","globalization of law","transnationalism","Colombia","international organizations","social movements"]', '10.7476/9789585005341', '9789588378282', 'https://books.scielo.org/id/2yxj2', 'https://books.scielo.org/id/2yxj2/pdf/santamaria-9789585005341.pdf', NULL, 'https://books.scielo.org/id/2yxj2/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2yzwb', '2yzwb', 'Democracia e inovação na gestão local da saúde', NULL, '["Sônia Fleury"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Homens, brancos, médicos ou filhos de médicos, fazendeiros ou famílias de políticos tradicionais no local: se este era o perfil costumeiro dos secretários municipais de saúde, pode-se dizer que os efeitos da democratização se fazem notar. Já é significativa a participação de mulheres, negros e não médicos à frente das pastas da saúde, especialmente em municípios de menor porte. Este é um dos resultados apresentados no livro, fruto de um projeto que, ao longo de uma década, analisou as mudanças no perfil dos gestores, na gestão e nos padrões de difusão de inovação das secretarias municipais de saúde. No quesito inovação, o estudo evidenciou expressivos avanços na dimensão assistencial, mas identificou dificuldades na dimensão gerencial. Fez-se uma comparação entre os municípios mais e menos inovadores e, dessa forma, foi possível identificar algumas variáveis que favorecem e outras que obstruem a inovação. Entre as que favorecem, destacam-se o treinamento específico do secretário como gestor, a prática do associativismo e a participação nas conferências de saúde e em eventos do Conasems. Quanto aos obstáculos, verificou-se que os municípios muito pequenos e os muito grandes são onde os gestores encontram mais dificuldades para a inovação. O livro reúne tanto os resultados quanto os marcos teóricos e metodológicos da pesquisa, cujo diferencial foi seu caráter dinâmico, com a comparação de dados coletados em dois momentos distintos, em 1996 e 2006. “O produto mais importante que podemos oferecer a todos é uma base metodológica para o estudo do processo de descentralização, com vistas a compreender sua dinâmica e suas relações com a democratização do poder local e com a inovação na gestão local”, avalia a autora. “Em 2016, uma nova década se cumpre e seria uma fabulosa oportunidade para conhecer o que mudou em relação às décadas anteriores!”, instiga.', '["local health management","municipal health secretaries","democratization","healthcare innovation","decentralization","health associations","health conferences"]', '10.7476/9788575415535', '9788588422179', 'https://books.scielo.org/id/2yzwb', NULL, NULL, 'https://books.scielo.org/id/2yzwb/cover/cover_thumbnail.jpeg', 480, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2z7h5', '2z7h5', 'Em “carne viva”: territórios, sociabilidades e a construção social da(s) política(s)', 'territórios, sociabilidades e a construção social da(s) política(s)', '["Anete Brito Leal Ivo","Gabriel Kraychete"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro apresenta algumas tensões civilizatórias da modernidade em países periféricos, como o Brasil. Os autores interpelam as experiências contemporâneas de sociabilidade na vida econômica e na vida institucional, vivenciadas nas lutas cotidianas dos trabalhadores e suas famílias, por pessoas em situação de rua, por quilombolas em busca do reconhecimento de seus territórios e da sua cultura, segundo diferentes políticas implementadas. Em “carne viva” mostra as contradições contemporâneas de valorização de ativos, por meio da "espoliação" de territórios e da precarização das relações de trabalho, no campo e na cidade, e convida os leitores a desenvolver um "outro olhar" sobre esses sujeitos em defesa da vida, moradia e trabalho dignos, vida pública, cidadania e vida democrática.', '["sociability","territorial struggles","quilombola territories","street dwellers","workers'' struggle","precarization of work","modernity","citizenship","democracy","housing","public life","peripheral countries"]', '10.7476/9786556309002', '9786556306704', 'https://books.scielo.org/id/2z7h5', 'https://books.scielo.org/id/2z7h5/pdf/ivo-9786556309002.pdf', NULL, 'https://books.scielo.org/id/2z7h5/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2zqsv', '2zqsv', 'Economías globalizadas: producción y consumo responsable, experiencias en América Latina', NULL, '["Raúl Cera Ochoa"]', 'Editorial Fundación Universitaria San Mateo', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Con esta publicación, se pretende formular planteamientos que fortalezca la comunidad académica y desarrollar en los profesionales en formación; las competencias requeridas en el siglo XXI y no competencias con paradigmas del pasado, para que los futuros profesionales puedan asumir con éxito los grandes retos de nuestra sociedad de forma creativa, analítica, innovadora y con un pensamiento crítico.', '["responsible production","responsible consumption","globalization","Latin America","21st century skills","critical thinking","professional training"]', '10.7476/9786289558296', '9786289558296', 'https://books.scielo.org/id/2zqsv', 'https://books.scielo.org/id/2zqsv/pdf/cera-9786289558296.pdf', NULL, 'https://books.scielo.org/id/2zqsv/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALE