INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2zt6f', '2zt6f', 'Ser mulher no século XXI: desafios, direitos, conquistas e vivências', NULL, '["Ana Paula Andrade","Rayane Silva Guedes"]', 'Editora UEMG', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Reconhecendo as tensões, demandas e novas configurações que se apresentam para pensar o “ser mulher”, pesquisadoras de diferentes horizontes epistêmicos se reuniram nesta coletânea para alcançar, a partir de suas trajetórias individuais e estudos desenvolvidos, uma obra plural e convergente com a temática.', '["female identity","women''s rights","gender relations","women''s experiences","21st century","women''s history","gender inequality"]', '10.7476/9786586832433', '9786586832433', 'https://books.scielo.org/id/2zt6f', 'https://books.scielo.org/id/2zt6f/pdf/passos-9786586832433.pdf', NULL, 'https://books.scielo.org/id/2zt6f/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2ztnf', '2ztnf', 'Relações Brasil-África e geopolítica do Atlântico Sul', NULL, '["Eli Alves Penha"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Livro faz uma retomada das relações entre o Brasil, a África e o Atlântico Sul, abordando a “Pax Lusitana” e o período colonial; as transformações do poder marítimo contemporâneo; as estratégias marítimas das grandes potências no Atlântico-Sul; as formulações geopolíticas brasileiras sobre o Atlântico Sul, dentre outros assuntos relevantes. Para finalizar, Relações Brasil-África apresenta o cenário atual da cooperação Sul-Atlântica, o “despertar” da África, a diplomacia do “pragmatismo responsável”, os conflitos, interações e relações comerciais no Atlântico Sul, inclusive a parceria Brasil-Nigéria, o estabelecimento da Zona de Paz e a Organização do Tratado do Atlântico.', '["Brazil-Africa relations","South Atlantic geopolitics","colonial period","maritime power","Brazilian geopolitics","commercial relations"]', '10.7476/9788523212292', '9788523207748', 'https://books.scielo.org/id/2ztnf', NULL, NULL, 'https://books.scielo.org/id/2ztnf/cover/cover_thumbnail.jpeg', 245, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-2zxfn', '2zxfn', 'A figueira', NULL, '["Sarita [UNESP] Leonel","Aloísio Costa SAMPAIO","Adilson Pacheco de Souza","Aldir Carlos Silva","Andréa Carvalho da Silva","Danila Monte Conceição","Edvan Alves Chagas","Edvar de Sousa da Silva","Emerson Dias Gonçalves","Emi Rainildes Lorenzetti","Erval Rafael Damatto","Everton Pires Soliman","Fabíola Villa","Gláucia Cristina Moreira","Gutemberg Armando Diniz Guerra","Jaime Duarte Filho","João Vieira Neto","Jose Augusto Maiorano","Lin Chau Ming","Magali Leonel","Manoel Euzébio de [UNESP] Souza","Marco Antonio da Silva Vasconcellos","Maria de Nazaré Ângelo Menezes","Rafael Pio","Ronaldo Simões Grossi"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'A figueira, originária da região da Ásia Menor e da Síria, foi cultivada e selecionada pela primeira vez pelos árabes e judeus, em uma região situada ao sudoeste da Ásia. É uma das mais anti­gas plantas cultivadas no mundo, sendo considerada pelos povos antigos como símbolo de honra e fertilidade. A cultura da figueira é interessante para o Brasil, que vem se destacando como um grande fornecedor de figos para o mundo, com 20% a 30% do volume total produzido no país destinado para a exportação. Neste livro, organizado por Sarita Leonel e Aloísio Costa Sampaio, diversas abordagens sobre esse fruto, tanto em seu aspecto econômico como biológico e até mesmo cultural, são feitas por especialistas, que procuram fazer uma revisão biblio­gráfica sobre a figueira, demonstrando sua importância ao longo da história da humanidade, com referências registradas em escri­tos religiosos, políticos, artísticos, medicinais e gastronômicos.', '["fig trees","Ficus carica","fig cultivation","fig fruit"]', '10.7476/9786557145142', '9786557145142', 'https://books.scielo.org/id/2zxfn', 'https://books.scielo.org/id/2zxfn/pdf/leonel-9786557145142.pdf', NULL, 'https://books.scielo.org/id/2zxfn/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-329', '329', 'Capacitação docente e responsabilidade social: aportes pluridisciplinares', NULL, '["Robinson Moreira Tenório","Reginaldo de Souza Silva"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Publicado pela Editora da Universidade Federal da Bahia (EDUFBA), este livro, escrito a muitas mãos, desvela para o leitor os resultados da parceria bem-sucedida entre a UESB e o Programa de Pós-Graduação em Educação da Faced – UFBA na capacitação docente, voltados para a melhoria da qualidade do ensino, a produção do conhecimento socialmente relevante e a ação social responsável. Os resultados de “Capacitação Docente e Responsabilidade Social: aportes pluridisciplinares”, mesmo que ainda muito recentes, permitem visualizar que é possível superar as assimetrias de desenvolvimento entre regiões e instituições de ensino superior, no que diz respeito à formação de docentes, na criação e consolidação de grupos de pesquisa, na expansão e fortalecimento da graduação e pós-graduação, necessárias para o desenvolvimento do ensino superior, da ciência e da tecnologia.', '["teacher professional development","social responsibility","higher education","teaching quality","university partnerships","regional disparities","research groups"]', '10.7476/9788523208912', '9788523208912', 'https://books.scielo.org/id/329', 'https://books.scielo.org/id/329/pdf/tenorio-9788523208912.pdf', NULL, 'https://books.scielo.org/id/329/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-32g7m', '32g7m', 'Acordos comerciais internacionais: o Brasil nas negociações do setor de serviços financeiros', NULL, '["Neusa Maria Pereira Bojikian"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Mesmo implantando uma ampla liberalização financeira, o Brasil resiste às pressões internacionais para assumir compromissos que tornariam as medidas já adotadas quase definitivas. Este aparente paradoxo é explorado por Neusa Maria Pereira Bojikian, que demonstra – apoiada em vasta documentação e instrumentos de análise – como a "liberalização administrada" se impôs como as opção mais racional para as autoridades nacionais. Acordos comerciais internacionais responde à questão de por que um país que se dispõe a fazer reformas profundas em sua estrutura econômica adota uma postura tida como conservadora no momento de apresentar ofertas concretas nas negociações comerciais internacionais. Percebe-se neste caminho que o Brasil usa as mesmas estratégias e táticas dos principais países desenvolvidos.', '["international trade agreements","financial services liberalization","Brazil","trade negotiations","financial liberalization","economic reform"]', '10.7476/9788595461970', '9788571399884', 'https://books.scielo.org/id/32g7m', NULL, NULL, 'https://books.scielo.org/id/32g7m/cover/cover_thumbnail.jpeg', 273, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-32vmq', '32vmq', 'Incursões na escrita acadêmico-universitária: letramento, discurso, enunciação', NULL, '["Cármen Agustini","Ernesto Sérgio Bertoldo"]', 'EDUFU', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A obra está inserida nesta dupla linha de investigação: a competência tradutória e sua aquisição; e a didática da tradução. O livro é uma contribuição importante para a investigação sobre a competência tradutória, uma vez que aborda o estudo das diversas subcompetências essenciais para o tradutor (bilíngue, extralinguística, instrumental e estratégica) e também para o tradutólogo (competência teórica e metateórica). Além disso, são propostas diretrizes pedagógicas para o desenvolvimento dessas subcompetências, através das quais também se demarcam as pesquisas sobre a didática da tradução. Os aspectos tratados no livro são de natureza diversa – tradução de acrósticos, de piadas, da estrutura verbal em textos literários –, bem como contemplam o uso de recursos de documentação para tradutores.', '["translation competence","translation pedagogy","humor translation","academic writing","college writing","literacy","discourse","enunciation"]', '10.7476/9786586084269', '9786586084269', 'https://books.scielo.org/id/32vmq', 'https://books.scielo.org/id/32vmq/pdf/agustini-9786586084269.pdf', NULL, 'https://books.scielo.org/id/32vmq/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-32yjm', '32yjm', 'Realismo e violência na literatura contemporânea: os contos de Famílias terrivelmente felizes, de Marçal Aquino', NULL, '["Fábio Marques Mendes"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro, fruto da dissertação de mestrado do autor, busca compreender a ficção brasileira contemporânea considerando a história político-social da nação, no período que vai do fim da ditadura militar à sua redemocratização. Assim, Fábio Mendes propõe uma análise crítica dos contos de Famílias terrivelmente felizes, escritos por Marçal Aquino, identificando uma linguagem da violência que perpassa a articulação de temas e motivos, a constituição dos narradores, a caracterização das personagens e a materialidade dos textos. Quanto ao conteúdo, essa violência estaria ajustada às imagens da morte, seja de modo predominante ou incidental, física, psicológica, social e simbólica, traços de uma sociedade brasileira autoritária e matéria-prima da linha de produção do novo realismo. Nestes termos, a ironia aparece como o principal elemento constitutivo das narrativas de Aquino, articulando a violência de modo que o leitor seja atraído para o mundo do texto literário e incorpore sua mensagem, consciente ou inconscientemente, em seu modo de vida.', '["short stories","violence in literature","new realism","contemporary Brazilian fiction","irony","death imagery","authoritarian societies","military dictatorship","post-dictatorship Brazil","narrator","characterization","textual materiality"]', '10.7476/9788579837005', '9788579837005', 'https://books.scielo.org/id/32yjm', 'https://books.scielo.org/id/32yjm/pdf/mendes-9788579837005.pdf', NULL, 'https://books.scielo.org/id/32yjm/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-33937', '33937', 'Bioética para profissionais de saúde', NULL, '["Sérgio Rêgo","Marisa Palácios","Rodrigo Siqueira‐Batista"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'ApreSentAçãoEste livro destina-se aos estudantes e profissionais da área da saúde que, apesar de não especialistas em bioética, sentem-se profundamente incomodados com os problemas de sua prática cotidiana que apresentam interface com questões de natureza ética.O mundo mudou, a medicina mudou, a assistência médicosanitária -hoje chamada assistência à saúde, ou, de forma ainda mais apropriada, cuidado da saúde -também mudou, assim como o olhar da sociedade e a avaliação que esta elabora em resposta aos problemas morais relacionados ao processo saúde-doença.O meio social se transforma, e a forma como o homem se relaciona com ele também.Assim, para melhor compreensão da atuação laboral em saúde é premente o desenvolvimento de um novo olhar sobre os novos problemas morais, os quais têm marcante interface com as ações de prevenção, promoção e organização da saúde.Esse novo olhar, esse novo saber e as ferramentas que são usadas para analisar essa nova realidade não devem ser considerados como algo estranho à clínica nem à saúde pública.Antes, é um saber disciplinar -por que não transdisciplinar?-, claramente aplicável tanto ao universo da prática clínica quanto ao da saúde pública.Assim, apresentaremos análises que considerem o certo e o justo sempre de forma contextualizada, compreendendo o [ à prevenção da tuberculose, em cem crianças, sem a obtenção do consentimento de seus responsáveis para a participação na pesquisa; 75 dessas crianças morreram no decorrer do projeto.O fato ficou conhecido como "o desastre de Lübeck".O episódio levou o ministro do Interior da Alemanha a estabelecer, em 1931, as Diretrizes para Novas Terapêuticas e Pesquisa em Seres Humanos, as quais não foram suficientes para impedir as pesquisas abusivas com judeus, ciganos e prisioneiros em geral, durante a Segunda Guerra Mundial.Em 1932, nos Estados Unidos da América (EUA), iniciou-se na cidade de Tuskegee a famosa pesquisa sobre a história natural da sífilis com 399 negros com sífilis, que não apenas não foram tratados quando a penicilina passou a estar disponível para a terapêutica desta enfermidade como também tiveram impedido o acesso a tal intervenção.Apenas em 1972, após denúncia do episódio pela imprensa leiga, o estudo foi suspenso.Note-se a respeito desse estudo que ele foi permanentemente acompanhado e avaliado pelas autoridades sanitárias nos National Institutes of Medicine e que, além disso, diversos artigos foram publicados ao longo dos quarenta anos de pesquisa.Apenas em maio de 1997 o presidente Clinton pediu desculpas, em nome do governo, aos sobreviventes.Durante esses quarenta anos a comunidade científica estadunidense e do mundo (afinal, os artigos foram publicados em periódicos de referência mundial) acompanhou a pesquisa e seus resultados em 13 artigos que foram revistos por pares e publicados!O que isso significa?Que esses pesquisadores eram pessoas de má índole?Pessoas cruéis e insensíveis?Provavelmente, não.Elas expressavam, sim, a compreensão da comunidade científica de que determinadas ações e estudos se', '["bioethics","healthcare workers","medical ethics","research ethics","informed consent","Tuskegee syphilis study","health promotion","health prevention","transdisciplinarity","clinical practice","public health","health care organization"]', '10.7476/9788575413906', '9788575413906', 'https://books.scielo.org/id/33937', 'https://books.scielo.org/id/33937/pdf/rego-9788575413906.pdf', NULL, 'https://books.scielo.org/id/33937/cover/cover_thumbnail.jpeg', NULL, 43, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-33h8q', '33h8q', 'Plantas medicinais no semiárido: conhecimentos populares e acadêmicos', NULL, '["Ingrid Estefania Mancia de Gutiérrez","Antidio dos Reis e Silva Filho","Mara Zélia de Almeida","Nina Cláudia Barboza da Silva"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Na região do Semiárido, ocorre um dos grandes biomas brasileiro, a Caatinga, que ocupa uma área contínua, com clima quente e seco, circundada por áreas de clima mais úmido. Com o conhecimento popular como fonte de dados importantes para novas descobertas científicas sobre as propriedades terapêuticas das plantas, esse livro analisa o estado da arte de espécies nativas do semiárido brasileiro visando o desenvolvimento e a caracterização da tolerância a estresses abióticos, em espécies vegetais nativas dessa região.', '["medicinal plants","Caatinga","semi-arid region","traditional knowledge","native plants","abiotic stress tolerance","ethnobotany"]', '10.7476/9788523212179', '9788523207120', 'https://books.scielo.org/id/33h8q', NULL, NULL, 'https://books.scielo.org/id/33h8q/cover/cover_thumbnail.jpeg', 130, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COA