INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-33k73', '33k73', 'Adultos mayores privados de la libertad en Colombia', NULL, '["Carol Iván Abaunza Forero","Mónica Alexandra Mendoza Molina","Paola Bustos Benítez","Giovanny Paredes Álvarez","Karla Vanessa Enriquez Wilches","Andrea Padilla-Muñoz"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'mayores privados de la libertad en Colombia Panorama de las poblaciones excepcionales etarias frente a la responsabilidad penal ..............', '["older prisoners","criminal liability","criminal justice system"]', '10.7476/9789587385328', '9789587385328', 'https://books.scielo.org/id/33k73', 'https://books.scielo.org/id/33k73/pdf/abaunza-9789587385328.pdf', NULL, 'https://books.scielo.org/id/33k73/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-33wpq', '33wpq', 'Diálogos interdisciplinares sobre mulheres, gênero e feminismo', NULL, '["Márcia Santana Tavares","Ângela Maria Freire de Lima e Souza"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta coletânea reflete a riqueza dos diálogos interdisciplinares que se dão no cotidiano de um programa de pós-graduação feminista formado por pesquisadoras, pesquisadores e estudantes de formações acadêmicas variadas. Ao longo de nove capítulos, o livro oferece um panorama de diferentes temáticas e perspectivas teórico-metodológicas que revela o quanto o passado se encontra enredado ao presente. Além disso, permite vislumbrar devires, seja nas formas de agenciamento das mulheres sobre suas escolhas e vidas, seja nas diferentes estratégias elaboradas tanto nos centros urbanos como na zona rural, no Brasil, na América Latina, na Europa central ou mesmo no Egito.', '["women","gender","feminism","interdisciplinary dialogue","women''s agency","Latin America","Europe"]', '10.7476/9786556305172', '9786556305172', 'https://books.scielo.org/id/33wpq', 'https://books.scielo.org/id/33wpq/pdf/marcia-9786556305172.pdf', NULL, 'https://books.scielo.org/id/33wpq/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-33zzh', '33zzh', 'Barragens, injustiça e sofrimento social no Brasil', NULL, '["Carmem Regina Giongo"]', 'Editora da UFRGS', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro busca compreender como se constrói socialmente a banalização do sofrimento vivenciado pelas populações atingidas pela construção de hidrelétricas. Nesse sentido, a autora procede à desconstrução das categorias "energia limpa", "renovável" e "de baixo custo", utilizadas para caracterizar a fonte de energia hídrica, e ainda examina as profundas mudanças que as hidrelétricas acarretam nos modos de vida e de trabalho dessas populações. A narrativa desenvolve-se com base em importantes marcadores teóricos e do caso da Hidrelétrica de Itá, obra localizada entre os estados de Santa Catarina e Rio Grande do Sul que entrou em operação no ano 2000 e atingiu cerca de 3.500 famílias. As memórias das comunidades rurais que permaneceram no entorno do reservatório após a construção do empreendimento são reveladas na voz de pequenos agricultores, que vivem em condições muito precárias e estão presenciando o desaparecimento de suas comunidades rurais.', '["hydroelectric dams","social suffering","social injustice","smallholder farmers","hydropower development","social memory","Santa Catarina","Rio Grande do Sul"]', '10.7476/9786557252253', '9786557250990', 'https://books.scielo.org/id/33zzh', NULL, NULL, 'https://books.scielo.org/id/33zzh/cover/cover_thumbnail.jpeg', 202, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-34rvh', '34rvh', 'Experiencias docentes en tiempo de pandemia', NULL, '["Floralba Aguilar Gordón","María Sol Villagómez"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2022, '2022-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'El texto Experiencias docentes en tiempo de pandemia está estructurado en dos partes: 1. Discusiones necesarias sobre la educación superior en tiempo de pandemia. 2. Prácticas docentes en época de pandemia expresadas a través del relato. En la primera parte, se presenta un conjunto de nueve artículos que buscan fundamentar teóricamente la situación actual de la educación conforme a las circunstancias que estamos viviendo, de manera que: Robert Fernando Bolaños Vivas, en su artículo La filosofía de la Educación ante la crisis sanitaria COVID-19, una oportunidad de humanización, considera que la crisis sanitaria de la COVID-19 ha puesto de manifesto la profunda crisis humana que pone a prueba la calidad de los seres humanos, razón por la cual el autor intenta demostrar la deficiente respuesta antropológica a las complejas exigencias y complejidades de la crisis sanitaria provocada por la COVID- 19, en este sentido, en el artículo reflexiona sobre la dimensión de la alteridad, la historicidad y la temporalidad humana.', '["COVID-19 pandemic","higher education","teaching practice","philosophy of education","humanization","human crisis","otherness","historicity","temporality"]', '10.7476/9789978108222', '9789978108222', 'https://books.scielo.org/id/34rvh', 'https://books.scielo.org/id/34rvh/pdf/aguilar-9789978108222.pdf', NULL, 'https://books.scielo.org/id/34rvh/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-35m', '35m', 'Comida: prazeres, gozos e transgressões', NULL, '["Angelina Bulcão Nascimento"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste livro a autora enfoca vários aspectos que se entrelaçam, para que o objetivo de ampliar a questão da alimentação para além da nutrição, seja alcançado. Este é um livro que, pela originalidade de seu enforque, pelo cuidado na pesquisa dentro de uma área que, afinal, atinge a todos, não pode deixar de despertar grande interesse. E de ensinar a ver aspectos da realidade em que as pessoas estão imersas e, por isso, cegas para eles. É uma leitura proveitosa, enriquecedora, erudita e, em grande parte - o que parece cada vez mais raro - despretensiosamente divertida.', '["food","eating","food culture","gastronomy","food and pleasure","food and identity","food and society"]', '10.7476/9788523209070', '9788523209070', 'https://books.scielo.org/id/35m', 'https://books.scielo.org/id/35m/pdf/nascimento-9788523209070.pdf', NULL, 'https://books.scielo.org/id/35m/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-35yrp', '35yrp', 'Cultura letrada: literatura e leitura', NULL, '["Márcia Abreu"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A autora apresenta uma análise sobre a literatura e seu ensino, procurando responde a questões como: há livros bons em si? todos devem apreciar o mesmo tipo de texto? há uma qualidade estética objetiva nas obras? há uma maneira correta de ler literatura? como definir literatura? Com linguagem fluente e acessível, sem prescindir porém do rigor acadêmico, o livro é direcionado para o público dos últimos anos de ensino médio, primeiros anos de universidade e professores em geral.', '["literary culture","reading and literature","literature teaching","definition of literature","literary appreciation","literary reading","literary canon"]', '10.7476/9788539302932', '9788571396999', 'https://books.scielo.org/id/35yrp', NULL, NULL, 'https://books.scielo.org/id/35yrp/cover/cover_thumbnail.jpeg', 128, 141, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-365ff', '365ff', 'Ciências ambientais e interdisciplinaridade', NULL, '["Lobão, Jocimara Souza Britto","Joselisa Maria Chaves","Nolasco, Marjorie Csekö","Castro, Paulo de Tarso Amorim","Rocha, Washington de Jesus Sant’anna da Franca"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O Programa de Modelagem em Ciências da Terra e do Ambiente – PPGM se constituiu, e após uma longa jornada de publicações e busca incessante o caráter interdisciplinar, no intento de compreender a complexidade ambiental. Este livro é uma forma de publicizar os trabalhos de discentes e docentes do PPGM, não é o primeiro, mas pretende tornar-se a primeira série, anual, que registre e consolide nossa história, através de capítulos advindos de parcerias e de orientações, complementados por histórias e caminhos. Este livro também apresenta, em seus capítulos, uma retrospectiva histórica que celebra termos alcançado um objetivo há muito traçado, o doutorado. O PPGM desde seus primórdios, em 2005, foi pensado como Mestrado e Doutorado, um Programa de Pós Graduação, que agora está completo. No intuito de registrar um pouco dessa história, esta introdução apresentará, através das coordenações, o percurso das primeiras ideias ao doutorado, atual. A área de Geociências, da UEFS, iniciou o sonho preparandose para este objetivo anos antes, com formação de doutores entre seus professores, intenso trabalho de formação entre discentes e diálogos com outras áreas de conhecimento dos departamentos de Biologia, Exatas, Engenharias, Saúde e Ciências Humanas e Aplicadas. Foram 15 anos de trabalho intenso e um mundo de construções, secundadas por nossos primeiros alunos, strar-ups — que se chamavam empresas juniores, na época — busca ativa por integração nacional e internacional, desde o primeiro pensar, nunca desprezando conhecimentos não-acadêmicos, advindos das mais diferentes fontes; ou mesmo profissionais que, sem títulos formais, traziam a experiência de vida significativa.', '["environmental science","interdisciplinarity","graduate program history","doctoral education","graduate education","earth sciences","environmental complexity"]', '10.7476/9786589524939', '9786589524939', 'https://books.scielo.org/id/365ff', 'https://books.scielo.org/id/365ff/pdf/lobao-9786589524939.pdf', NULL, 'https://books.scielo.org/id/365ff/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-36d', '36d', 'Como anda Salvador e sua região metropolitana', NULL, '["Inaiá Maria Moreira de Carvalho","Gilberto Corso Pereira"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro reúne textos de diversos autores cujas observações apuradas permitem ao leitor compreender a situação social, econômica e geográfica de Salvador e Região Metropolitana. Os textos são ilustrados com gráficos e mapas atualizados tornando a leitura mais dinâmica. A partir de análises sobre temas, como violência, infra-estrutura, demografia e economia, os autores traçam um perfil dessa região que concentra conflitos e esperanças, contradições e liberdade, tornando o livro um indispensável meio para entendê-la um pouco mais.', '["Salvador, Bahia","Salvador Metropolitan Region","social conditions","economic conditions","violence","infrastructure","demography","regional economy","urban profile"]', '10.7476/9788523209094', '9788523209094', 'https://books.scielo.org/id/36d', 'https://books.scielo.org/id/36d/pdf/carvalho-9788523209094.pdf', NULL, 'https://books.scielo.org/id/36d/cover/cover_thumbnail.jpeg', NULL, 22, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-36jp8', '36jp8', 'Direitos e ajuda humanitária: perspectivas sobre família, gênero e saúde', NULL, '["Jaqueline Teresinha Ferreira","Patrice Schuch"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Dirigida a todos que se interessam pela interface entre ciências sociais e direitos humanos, porque nela pesquisam ou atuam, a coletânea apresenta uma série de estudos, a maioria de cunho etnográfico, sobre práticas sociais que articulam os discursos de direitos e os valores da ajuda humanitária. Aborda problemas sociais, como pobreza e discriminação, e novas formas de intervenção sobre eles, provenientes da ação estatal, jurídica, de ajuda humanitária ou de organizações da sociedade civil.', '["humanitarian aid","human rights","family","gender","health","poverty","discrimination","social practices","state intervention","civil society organizations","legal intervention"]', '10.7476/9788575413142', '9788575412015', 'https://books.scielo.org/id/36jp8', NULL, NULL, 'https://books.scielo.org/id/36jp8/cover/cover_thumbnail.jpeg', 275, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-36rwg', '36rwg', 'Inovações tecnológicas e a complexidade do sistema econômico', NULL, '["Carolina Marchiori Bezerra"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'O objetivo deste trabalho é analisar como o processo de inovações tecnológicas é tratado pela Teoria dos Sistemas Complexos. A abordagem neoclássica tradicional, ao partir de pressupostos bastante restritivos sobre os agentes e os mercados, não é capaz de fornecer explicações plausíveis aos vários problemas econômicos da vida real. Ao desconsiderar a dinâmica dos fenômenos econômicos, essa abordagem foi incapaz de incorporar os aspectos do processo de inovação e mudança tecnológica. A abordagem evolucionária, nesse sentido, ao considerar a racionalidade limitada, incerteza e heterogeneidade presente em ambientes que exibem inovação, foi capaz de fornecer um tratamento mais próximo da realidade. A inovação é, então, entendida como uma mudança descontínua que altera as condições estruturais gerando desenvolvimento, progresso e evolução no sistema. Já abordagem dos sistemas complexos, ao apresentar um arcabouço não reducionista e que se fundamenta sobre uma perspectiva evolucionária e sistêmica, concebe a economia como um sistema composto por agentes heterogêneos que interagem entre si. Apesar do ambiente de incerteza nas decisões tomadas, os agentes procuram se adaptar às informações recebidas do meio e se auto-organizarem gerando com isso novos padrões de auto-ordenamento e estruturas emergentes. A modelagem, nesse sentido, tem por principal objetivo descobrir as propriedades emergentes resultantes da interação entre os agentes no sistema. Por fim chega-se a conclusão de que as inovações tecnológicas apresentaram resultados mais satisfatórios e mais condizentes quando analisadas dentro dessa perspectiva agent-based.', '["technological innovation","complexity theory","evolutionary economics","agent-based modeling","heterogeneous agents","self-organization","emergent properties","bounded rationality","uncertainty","critique of neoclassical economics","economic complexity"]', '10.7476/9788579830891', '9788579830891', 'https://books.scielo.org/id/36rwg', 'https://books.scielo.org/id/36rwg/pdf/bezerra-9788579830891.pdf', NULL, 'https://books.scielo.org/id/36rwg/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-36vqv', '36vqv', 'Adolescências em tempos de guerra', 'modos de pensar, modos de operar', '["Andréa Máris Campos Guerra"]', 'Editora da UFRGS', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'O livro trança com o leitor realocações do discurso sobre a psicanálise no campo político e sobre o adolescente em conflito com a lei. Propõe revisões conceituais e apresenta fundamentos metodológicos para a prática nas instituições. Testemunha o valor vivo do saber adolescente e não se intimida em tomar posição sobre a responsabilidade de um psicanalista com seu tempo. Toma subjetividade e política como dois lados de uma faixa que, torcida, cria uma continuidade não linear entre ambos, cujo corte os afeta. Verifica a pluralização de referências simbólicas que deixa o adolescente infrator diante de múltiplos modos de viver e diante de um curto-circuito entre a infância e a adultez. O genocídio desse jovem, no Brasil, revela um sistema no qual o estado de exceção é a regra e eles se tornam matáveis, atualizando sua condição de "homo sacer". Assim como os neuróticos de guerra atualizam no corpo, sob a forma de angústia, o real da cena da guerra, parece-nos que os jovens, em situação de guerrilha urbana, consentem em oferecer seus corpos para sustentar uma verdade histórica capitalista: a de que são supérfluos. Fora do circuito simbólico que engendra a transmissão de um lugar no mundo, invertem o valor social dos dispositivos simbólicos de regulação da vida. Marcam sua presença na cena da cidade pelo tripé revolta-vingança-morte, numa relação de descrença com a lei jurídica. Com isso, as intervenções com eles operam sob um fundo de suspeita, instalando a função do Sujeito Suposto Suspeito, de onde pode advir a suposição de saber. Daí a necessidade de ampliar a clínica, introduzindo três tempos: o do reconhecimento do sintoma, o do deslocamento de sua resposta e o do reenlace com o Outro. Buscamos articular o nome do gozo vivo de cada adolescente com os nomes do “em comum” entre os homens.', '["juvenile offenders","juvenile delinquency","war","state of exception","homo sacer","urban guerrilla","psychoanalysis and politics","the Real","psychoanalytic intervention","childhood and adulthood"]', '10.7476/9786557252291', '9786557251058', 'https://books.scielo.org/id/36vqv', NULL, NULL, 'https://books.scielo.org/id/36vqv/cover/cover_thumbnail.jpeg', 360, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-377sy', '377sy', 'Cuando los instagrammers son los adultos', NULL, '["Torres-Toukoumidis, Ángel","Andrea De Santis-Piras"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2020, '2020-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'En el marco de los temas relacionados al marketing, se encuentran varias estrategias que afectan la conducta de compra de los consumidores con la finalidad de informar o persuadir sobre los beneficios que brinda determinado producto o servicio. Las empresas ecuatorianas utilizan dichas estrategias para captar la atención de clientes actuales y potenciales, con la finalidad de generar: posicionamiento de mercado, top of mind, captación e incremento del market share, satisfacción de los clientes y por supuesto, mayores ventas de los bienes que ofrecen. Esta recopilación de artículos académicos, aborda diversas estrategias manejadas por las pymes ecuatorianas, con sus correspondientes respuestas de mercado en los consumidores, manejando temas tales como: neuromarketing, marketing digital, cultura de consumo y comportamiento de compra.', '["Instagram influencers","social media influencers","consumer purchase behavior","neuromarketing","digital marketing","consumerism","small and medium-sized enterprises","Ecuadorian companies","market positioning","customer satisfaction"]', '10.7476/9789978105719', '9789978105719', 'https://books.scielo.org/id/377sy', 'https://books.scielo.org/id/377sy/pdf/torres-9789978105719.pdf', NULL, 'https://books.scielo.org/id/377sy/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-379v2', '379v2', 'Da cena do contato ao inacabamento da história: Os últimos isolados (1967-1999), Corumbiara (1986-2009) e Os Arara (1980-)', NULL, '["Clarisse Maria Castro de Alvarenga"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro se destina a todos(as) que se interessam por conhecer um tipo raro de cinema feito no Brasil: os filmes de contato. Seus realizadores se dedicam a filmar durante um extenso período de tempo uma das experiências mais devastadoras ainda nos dias de hoje em andamento no território brasileiro: o contato entre a sociedade nacional e os povos que aqui vivem originariamente. Adrian Cowell, Vincent Carelli e Andrea Tonacci captam os inúmeros sentidos desse encontro, indagando a história – suas catástrofes e suas aberturas –, no mesmo momento em que abrem novos caminhos para o cinema.', '["Contact (film)","indigenous peoples","indigenous cinema","Brazilian cinema","ethnographic film"]', '10.7476/9788523218690', '9788523218690', 'https://books.scielo.org/id/379v2', 'https://books.scielo.org/id/379v2/pdf/alvarenga-9788523218690.pdf', NULL, 'https://books.scielo.org/id/379v2/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-37f2w', '37f2w', 'Anamorfoses na música eletroacústica mista', NULL, '["Tiago Gati"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'One of the most recurring and essential issues of mixed electroacoustic music lies in the distortions – anamorphosis – that result from the interaction of a performer with electroacoustic means, ambiguous situations in which not only the nature of a sound source is veiled, but also the process through which this sound might have gone through. In the performance of mixed pieces, sounds and visual images trigger intricate connections with the public, and anamorphosis acts in between a more direct audiovisual relationship – what is seen in gestural terms is coherent with what is heard – and an “illusory” one – what is seen does not relate immediately to what is heard. Cases considered representative in the repertoire of mixed pieces, the analysis of two works (Parcours de l’Entité, by Flo Menezes, and Altra voce, by Luciano Berio), and the practical investigation in two composed pieces contribute to investigate anamorphosis in the realm of instrumental gesture as well as in the dynamics of the performance, given the fact that extra-musical elements are often used by composers to emphasize such distortions.', '["anamorphosis","instrumental gestures","performance dynamics","Luciano Berio"]', '10.7476/9788579837074', '9788579837074', 'https://books.scielo.org/id/37f2w', 'https://static.scielo.org/scielobooks/37f2w/pdf/gati-9788579837074.pdf', NULL, 'https://books.scielo.org/id/37f2w/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-37my2', '37my2', 'Mozambique’s foreign policy towards South Africa: managing asymmetrical economic diplomacy', NULL, '["Paulo Mateus Wache"]', 'Editora da UFRGS', 'Brasil', 'SciELO Books', 'books', 2022, '2022-07-20', 'en', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra discute a política externa de Moçambique para a África do Sul, procurando compreender as causas da dicotomia hostilidade-amizade, e argumenta que a assimetria por si só não pode explicar a ocorrência da dicotomia como sugerido pela teoria da assimetria de Womack. No caso da política externa de Moçambique, a dicotomia é causada por uma combinação de fatores, nomeadamente: assimetria de poder, diferenças ideológicas, percepções de liderança, desacordos e laços econômicos. No entanto, destaca-se que a assimetria de poder é o principal fator da dicotomia. Essa complexidade e amálgama de causas da dicotomia torna-se uma característica permanente e distintiva da política externa de Moçambique para a África do Sul. Assim, a contribuição do livro é dupla: em primeiro lugar, apresenta uma análise detalhada e abrangente dos temas da política externa de Moçambique à medida que interage com a África do Sul; em segundo lugar, ao aplicar a teoria da assimetria a Moçambique, o estudo traz uma contribuição teórica significativa para a compreensão da agência do lado menor nas relações assimétricas bilaterais.', '["power imbalance","bilateral relations","ideological differences","leadership perceptions","economic relations"]', '10.7476/9786557250709', '9786557250792', 'https://books.scielo.org/id/37my2', NULL, NULL, 'https://books.scielo.org/id/37my2/cover/cover_thumbnail.jpeg', 330, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-37nz2', '37nz2', 'Estudos socioculturais em alimentação e saúde: saberes em rede, vol. 5', NULL, '["Shirley Donizete Prado","Lígia Amparo-Santos","Luisa Ferreira da Silva","Mabel Gracia Arnaiz","Maria Lúcia Magalhães Bosi"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta coletânea corresponde ao quinto volume da série Sabor Metrópole, espaço que identificamos como aberto a expressões do pensamento quando se voltam às relações sociais construídas em torno de discursos e práticas alimentares e corporais, tendo a saúde por horizonte último;', '["food and health","food practices","body practices","interpersonal relationships","food discourse"]', '10.7476/9788575114568', '9788575114568', 'https://books.scielo.org/id/37nz2', 'https://books.scielo.org/id/37nz2/pdf/prado-9788575114568.pdf', NULL, 'https://books.scielo.org/id/37nz2/cover/cover_thumbnail.jpeg', NULL, 28, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-37t', '37t', 'Compreendendo a complexidade socioespacial contemporânea: o território como categoria de diálogo interdisciplinar', NULL, '["Maria Teresa Franco Ribeiro","Carlos R. S. Milani"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro constrói um diálogo entre pesquisadores brasileiros e franceses, de diferentes campos do conhecimento, sobre dois temas que passaram a ocupar os espaços do debate acadêmico e das ações públicas, nas duas últimas décadas: a questão do desenvolvimento e a questão territorial. Duas questões foram colocadas para os pesquisadores: qual o significado do conceito de território a partir de seu campo de estudo e quais contribuições podem aportar para a compreensão dos processos de desenvolvimento. Além de um rico debate no sentido epistemológico, a partir dos diversos campos de análise o livro aponta também algumas indagações: como trabalhar a relação entre espaço e território, como caracterizar fronteiras territoriais em um mundo em que, elas marcam profundamente tanto a união/ intercâmbio quanto a ruptura/interdição? E várias outras questões que compõem a agenda de debate da economia, geografia, ciências políticas, sociologia e da administração.', '["territory","territoriality","development","space and territory","territorial boundaries"]', '10.7476/9788523209322', '9788523209322', 'https://books.scielo.org/id/37t', 'https://books.scielo.org/id/37t/pdf/ribeiro-9788523209322.pdf', NULL, 'https://books.scielo.org/id/37t/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-37vvw', '37vvw', 'Schistosoma mansoni &amp; Esquistossomose: uma visão multidisciplinar', NULL, '["Omar dos Santos Carvalho","Paulo Marcos Zech Coelho","Henrique Leonel Lenzi"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Estima-se que haja hoje no país cerca de 2,5 milhões de portadores de esquistossomose mansoni — popularmente conhecida como barriga d’água —, afora mais 25 milhões de brasileiros expostos ao risco de contrair a doença. Esta obra, comemorativa ao centenário da descoberta do Schistosoma mansoni no Brasil pelo pesquisador baiano Manuel Augusto da Silva Pirajá, está sendo considerada a mais completa e atual já produzida no país sobre essa específica parasitose. Fruto do esforço e do longo conhecimento acumulado por especialistas altamente qualificados dos mais diversos campos da saúde, supre uma carência bibliográfica de valor inestimável para a comunidade científica, leitores e demais interessados. Em seus 35 capítulos ricamente ilustrados, compreende uma extensa revisão sobre o assunto, abarcando praticamente todas as áreas do conhecimento sobre a doença.', '["Schistosoma mansoni","schistosomiasis mansoni","parasitic infection","epidemiology","disease transmission","Brazil"]', '10.7476/9788575413708', '9788575411506', 'https://books.scielo.org/id/37vvw', 'https://books.scielo.org/id/37vvw/pdf/carvalho-9788575413708.pdf', 'https://books.scielo.org/id/37vvw/epub/carvalho-9788575413708.epub', 'https://books.scielo.org/id/37vvw/cover/cover_thumbnail.jpeg', 1124, 72, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-387', '387', 'Comunicação plural', NULL, '["Mattos, Sérgio"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O ensino do curso de comunicação e seus desafios, a construção da história da televisão no Brasil, cópia de livros nas universidades brasileiras, são alguns dos temas de artigos reunidos neste livro que trata de diversos temas que envolvem a comunicação.', '["communication education","communication curriculum"]', '10.7476/9788523208943', '9788523208943', 'https://books.scielo.org/id/387', 'https://books.scielo.org/id/387/pdf/mattos-9788523208943.pdf', NULL, 'https://books.scielo.org/id/387/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-38m', '38m', 'O corpo, o comer e a comida: um estudo sobre as práticas corporais alimentares cotidianas a partir da cidade de Salvador Bahia', NULL, '["Lígia Amparo da Silva Santos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Atualmente, imagem do corpo magro, saudável, malhado, voyeur e erótico é perseguido desesperadamente pelas pessoas. É nesse contexto que Lígia Santos apresenta um mergulho investigativo sobre corporalidade e comensalidade como extensão do moderno, urbano e desigual. As dimensões sociais, inevitavelmente presentes nas questões do comer e da comida, são colocadas no ambiente cultural permitindo uma análise compreensiva. A obra apresenta reflexões sobre o corpo na contemporaneidade através de ótica das ciências sociais e das ciências da nutrição e; apesar de falar a partir de Salvador na Bahia, escapa do local para ser invadido por um processo de mundialização.', '["body","dietary habits","food","embodiment","commensality","body image","thinness","urban inequality","globalization","Salvador, Bahia","everyday life"]', '10.7476/9788523211707', '9788523211707', 'https://books.scielo.org/id/38m', 'https://books.scielo.org/id/38m/pdf/santos-9788523211707.pdf', NULL, 'https://books.scielo.org/id/38m/cover/cover_thumbnail.jpeg', NULL, 21, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-38vpz', '38vpz', 'A cena musical da Black Rio: estilos e mediações nos bailes soul dos anos 1970', NULL, '["Luciana Xavier de Oliveira"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Em A cena musical da Black Rio, Luciana Xavier de Oliveira apresenta o surgimento, na década de 1970, dos bailes de soul music nos subúrbios carioca, iniciados na esteira do movimento de empoderamento da comunidade negra, sob o lema do black is beatiful. A autora realiza uma análise comunicacional desse cenário, analisa as influências deixadas na moda e no mercado fonográfico e mostra as contribuições dos jovens negros da época a fim de legitimar uma negritude mais positiva e consciente.', '["soul music","dance halls","1970s","musical style","cultural mediation","Afro-Brazilian music","Rio de Janeiro","popular music history"]', '10.7476/9788523218720', '9788523218720', 'https://books.scielo.org/id/38vpz', 'https://books.scielo.org/id/38vpz/pdf/oliveira-9788523218720.pdf', NULL, 'https://books.scielo.org/id/38vpz/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3936m', '3936m', 'Direitos humanos e saúde: gênero e sexualidade em vozes insurgentes', 'gênero e sexualidade em vozes insurgentes', '["Maria Helena Barros de Oliveira","Patrícia da Silva Von Der Way"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A publicação aborda temas emergentes de gênero, sexualidade e direitos humanos na saúde na perspectiva libertadora e decolonial. A obra apresenta contribuições de especialistas e trabalhos de conclusão do curso de Pós-Graduação em Gênero, Sexualidade e Direitos Humanos da Escola Nacional de Saúde Pública Sergio Arouca, da Fundação Oswaldo Cruz (ENSP/Fiocruz), com 17 capítulos divididos em quatro eixos temáticos. Os eixos abrangem as relações de trabalho e saúde ocupacional; os desafios de saúde da população LGBTQIAPN+; as violências e vulnerabilidades de gênero; e o empoderamento por meio da educação e tecnologias. Cada capítulo aprofunda temas essenciais, promovendo uma cultura inclusiva e de direitos humanos na saúde. Destina-se a profissionais e conselheiros de saúde, de serviço social, pesquisadores das humanidades, de ciências sociais e aplicadas interessados em tendências nos gender studies.', '["human rights in health","gender","sexuality","decoloniality","occupational health","gender-based violence","health education","digital technologies","empowerment"]', '10.7476/9786556308975', '9786556306728', 'https://books.scielo.org/id/3936m', 'https://books.scielo.org/id/3936m/pdf/oliveira-9786556308975.pdf', NULL, 'https://books.scielo.org/id/3936m/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
