D, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-39kd4', '39kd4', 'Renovos', NULL, '["Sanqueilo de Lima Santos"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Apresentando inquietações ligadas a trama da existência, o livro é marcado pela presença de poemas, narrativas e monólogos esparsadamente e, quase sempre, esses gêneros são empregados não para o deleite estético – que em se dando, é acidental – mas como destaques involuntários do discurso meditativo. Desse modo, como propõe o autor, “pretendem ser esses textos: o exercício hipotético de uma visão rude do ser”.', '["meditation","existence","poetry","narrative","monologue","philosophy of being"]', '10.7476/9788574555539', '9788574555379', 'https://books.scielo.org/id/39kd4', NULL, NULL, 'https://books.scielo.org/id/39kd4/cover/cover_thumbnail.jpeg', 2019, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-39rx3', '39rx3', 'Avaliação: metodologias no campo da saúde e da formação', NULL, '["Cristina Maria Meira de Melo","Norma Carapiá Fagundes","Tatiane Araújo dos Santos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Nursing', 'Os oito capítulos que compõem a obra são originados de pesquisas realizadas no campo da avaliação pelo grupo de pesquisa Gerir, da Escola de Enfermagem da UFBA. A obra busca estimular pesquisas avaliativas e sua utilização como instrumento de gestão. Descreve como se dá o uso de metodologias de base construtivista, mas sem negar a contribuição dos dados quantitativos. Ao mesmo tempo, consolida as abordagens de tipo qualitativo na avaliação, o que reforça a concepção da universalidade das ciências.', '["evaluation methodology","health assessment","nursing education","constructivist methodology","qualitative evaluation","numerical data"]', '10.7476/9788523211615', '9788523211615', 'https://books.scielo.org/id/39rx3', 'https://books.scielo.org/id/39rx3/pdf/melo-9788523211615.pdf', NULL, 'https://books.scielo.org/id/39rx3/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3bdyq', '3bdyq', 'O ensino de ofícios nos primórdios da industrialização', NULL, '["Luiz Antônio Cuñha"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O ensino de ofícios industriais e manufatureiros passou a ser defendido como um dos meios de integração do proletariado na sociedade moderna, durante as primeiras décadas do Brasil republicano. As escolas profissionais buscaram os jovens que tivessem vocação e aptidão para os ofícios manuais. Passou-se à aprendizagem sistemática (ao taylorismo), em substituição à aprendizagem espontânea (como o artesanato). O autor analisa as iniciativas públicas e privadas, confessionais e laicas de criação de instituições de ensino de ofícios, incluindo as que prepararam o caminho para as atuais. Entre elas, as escolas ferroviárias paulistas, nas quais se encontram os antecedentes do Senai; e as escolas federais de aprendizes artífices, matrizes dos atuais Cefets. Juntamente com os títulos O ENSINO DE OFÍCIOS ARTESANAIS E MANUFATUREIROS NO BRASIL ESCRAVOCRATA e O ENSINO PROFISSIONAL NA IRRADIAÇÃO DO INDUSTRIALISMO, integra a trilogia do mesmo autor, Luiz Antônio Cunha, professor da titular de Educação Brasileira da UFRJ. (Co-edição: Flacso)', '["vocational education","industrial apprenticeship","early industrialization","manual trades","scientific management","apprenticeship schools","SENAI","CEFET","Brazilian Republic"]', '10.7476/9788539303014', '9788571396326', 'https://books.scielo.org/id/3bdyq', NULL, NULL, 'https://books.scielo.org/id/3bdyq/cover/cover_thumbnail.jpeg', 243, 56, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3bm', '3bm', 'Deus ou seja a natureza: Spinoza e os novos paradigmas da física', NULL, '["Roberto Leon Ponczek"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Livro do Prof. Roberto Leon Ponczek, que descreve a imensa influência que o filósofo judeu de origem portuguesa Baruch Spinoza exerceu sobre Albert Einstein.', '["Spinoza","Albert Einstein","philosophy of physics","God and nature","philosophy of science"]', '10.7476/9788523209049', '9788523209049', 'https://books.scielo.org/id/3bm', 'https://books.scielo.org/id/3bm/pdf/ponczek-9788523209049.pdf', NULL, 'https://books.scielo.org/id/3bm/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3c88k', '3c88k', 'Pluralidades: patrimônio cultural e viagem: relendo a literatura sul-baiana', NULL, '["Maria de Lourdes Netto Simões"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'No pensamento dos deslimites de gêneros que norteiam os tempos do século XXI, este livro foca questões teóricas relativas a literatura, a patrimônio cultural e a viagem, ao tempo em que adentra o olhar para a produção literária Sul-baiana.', '["cultural heritage","travel","genre boundaries","literary theory","time in literature"]', '10.7476/9788574555300', '9788574554785', 'https://books.scielo.org/id/3c88k', 'https://books.scielo.org/id/3c88k/pdf/simoes-9788574555300.pdf', 'https://books.scielo.org/id/3c88k/epub/simoes-9788574555300.epub', 'https://books.scielo.org/id/3c88k/cover/cover_thumbnail.jpeg', 239, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3cg7g', '3cg7g', 'Políticas sociais: conceitos, trajetórias e a experiência brasileira', NULL, '["Telma Maria Gonçalves Menicucci","Sandra Gomes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O Brasil tem um Estado de bem-estar? A pergunta permeia o livro Políticas Sociais: conceitos, trajetórias e a experiência brasileira, da coleção Temas em Saúde, lançamento deste ano da Editora Fiocruz. Escrita por Telma Menicucci e Sandra Gomes, a obra traça um panorama do desenvolvimento do sistema de políticas sociais brasileiras, compara estudos diversos sobre o tema e contextualiza historicamente os marcos e modelos adotados pelos países desenvolvidos e em desenvolvimento. O texto mostra que o caminho percorrido na formação e consolidação de sistemas de políticas sociais é explicado pelas escolhas feitas em determinados contextos - políticos, sociais, econômicos e institucionais de cada país. “Há certo consenso e clareza sobre o escopo dos direitos civis e políticos, mas o mesmo não acontece com os direitos sociais, que são objeto de disputa e controvérsia na medida em que se relacionam com o escopo e a natureza da intervenção do Estado e envolvem transferências unilaterais de recursos”, afirmam as autoras. O livro discorre sobre a implantação da seguridade social (previdência, saúde e assistência); sobre educação (acesso, permanência e qualidade na educação básica e ensino superior); e sobre as políticas de combate à pobreza e as transversais de inclusão social ou integradas (desenvolvimento agrário, igualdade racial, juventude e igualdade de gênero). No final da publicação, estão quadros comparativos de políticas sociais implementadas pelo governo federal entre 1988 e maio de 2016, e o capítulo Síntese e tendências atuais.', '["social policy","welfare state","social rights","social security","health policy","education policy","poverty reduction","social inclusion","racial equality","gender equality","youth policy","agricultural development"]', '10.7476/9786557080559', '9788575415580', 'https://books.scielo.org/id/3cg7g', NULL, NULL, 'https://books.scielo.org/id/3cg7g/cover/cover_thumbnail.jpeg', 202, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3d8ft', '3d8ft', 'Porque a gente tem os filhos, mas não tem a natureza: narrativas de violências domésticas não conjugais', NULL, '["Luciana Cristina Teixeira de Souza"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra descortina uma tipologia de violência intrafamiliar pouco focalizada tanto nas políticas públicas como na academia, a saber: a violência não conjugal perpetrada por filhos ou filhas contra suas mães. Portanto, o agressor, nos casos em foco, não é o marido/cônjuge — sujeito universal praticante das violências domésticas.', '["domestic violence","narratives of violence"]', '10.7476/9786588211618', '9786588211533', 'https://books.scielo.org/id/3d8ft', 'https://books.scielo.org/id/3d8ft/pdf/souza-9786588211618.pdf', 'https://books.scielo.org/id/3d8ft/epub/souza-9786588211618.epub', 'https://books.scielo.org/id/3d8ft/cover/cover_thumbnail.jpeg', 218, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3d96p', '3d96p', 'Carl Einstein e a Arte da África', NULL, '["Elena O’Neill","Roberto Conduru"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O escritor, historiador e colecionador de arte Carl Einstein (1885-1940) e a sua obra acerca de esculturas e objetos africanos ajudam a inaugurar o campo de estudos sobre a arte da África. A difusão do pensamento desse teórico e crítico, seja com a reedição e a tradução de textos já publicados, seja com a edição de seus escritos que permaneciam inéditos até aqui, além da contribuição de autores de diversas proveniências (numa segunda parte), desafia o etnocentrismo ainda hegemônico, revertendo práticas determinadas pelo empreendimento colonial.', '["Carl Einstein","African art","African sculpture","art collecting","art criticism","ethnocentrism","colonialism","unpublished documents"]', '10.7476/9786588808108', '9788575113882', 'https://books.scielo.org/id/3d96p', NULL, NULL, 'https://books.scielo.org/id/3d96p/cover/cover_thumbnail.jpeg', 264, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3dj54', '3dj54', 'Seca silenciosa, saúde invisível: um desastre naturalizado no semiárido do Brasil', NULL, '["Aderita Ricarda Martins de Seca","Taís de Moura Ariza Alpino"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-11-23', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'A seca é apenas um evento climático de origem natural ou também é um desastre social, que tem forte impacto na saúde, no bem-estar e no desenvolvimento humano? Esse é um dos principais pontos de Seca Silenciosa, Saúde Invisível: um desastre naturalizado no Semiárido do Brasil, obra escrita pelas pesquisadoras Aderita Ricarda Martins de Sena e Tais de Moura Ariza Alpino. O livro aborda questões específicas do evento climático de seca, com ênfase no Semiárido do Brasil (SAB). Durante as pesquisas, as autoras observaram os efeitos da seca sobre a sociedade e sobre os determinantes da saúde, considerando os contextos do desenvolvimento sustentável ambiental, econômico e social. Além disso, as escritoras caracterizam a seca como um fenômeno ambiental que evolui de forma lenta e silenciosa, o que não motiva a agir de forma urgente: “Trata-se de uma situação diferente de outros tipos de eventos climáticos que surgem de forma aguda e intensiva, como, por exemplo, as inundações, que recebem uma resposta imediata”, complementa Carlos Corvalan, doutor em Saúde Ambiental e professor adjunto da Escola de Saúde Pública da Universidade de Sydney (Austrália), no prefácio da obra. Dessa forma, elas constataram que o setor da Saúde se torna invisível em suas respostas por não perceber os efeitos a curto prazo, deixando, assim, de agir urgentemente.', '["drought","Brazilian semi-arid region","health determinants","social disasters","climate change","environmental determinants of health","sustainable development","health sector response"]', '10.7476/9786557081747', '9786557081419', 'https://books.scielo.org/id/3dj54', NULL, NULL, 'https://books.scielo.org/id/3dj54/cover/cover_thumbnail.jpeg', 208, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3dpsk', '3dpsk', '¿Qué es la teoría?: enfoques, usos y debates en torno al pensamiento teórico', NULL, '["José Enrique Juncosa Blasco","Luis Fernando Garcés Velásquez"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2020, '2020-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'La teoría integra el sentido común académico y se ejerce en la cátedra universitaria casi siempre sin reparar en su condición de realidad abstracta sujeta a continuas discusiones y transformaciones. Para dar cuenta de su carácter problemático y problematizable, los autores afrontan dos preguntas: qué es una teoría?, ¿en qué consiste teorizar? En la búsqueda de respuestas, recorren, con rigor y detalle, los aportes más significativos provenientes tanto de la filosofía de la ciencia y la epistemología como de los estudios culturales y el diálogo de saberes. La trayectoria lograda ratifica que la teoría se despliega de modos diversos atravesada por la permanente tensión entre pensar para conocer y pensar para vivir en colectivo; tiene vida más allá de la lógica investigativa y se constituye en práctica teórica cuando se inserta en proyectos políticos. Redactada para contribuir a la docencia universitaria, la obra apunta a fomentar puntos de encuentro y conversación entre docentes, investigadores y estudiantes de todas la áreas del conocimiento ofreciéndoles la posibilidad de nombrar sus propias praxis teóricas situándolas en medio de otras posibles.', '["theory","theoretical thinking","philosophy of science","epistemology","cultural studies","dialogue of knowledges","theory and politics","university teaching"]', '10.7476/9789978105788', '9789978105788', 'https://books.scielo.org/id/3dpsk', 'https://books.scielo.org/id/3dpsk/pdf/juncosa-9789978105788.pdf', NULL, 'https://books.scielo.org/id/3dpsk/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3dqnm', '3dqnm', 'Corpos e comensalidades em discursos', NULL, '["Ferreira, Francisco Romão","Carvalho, Maria Cláudia da Veiga Soares","Vargas, Eliane Portes","Prado, Shirley Donizete"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra coloca em perspectiva diversas abordagens sobre os discursos em torno do corpo e das comensalidades, que, na cena contemporânea, se constitui em uma arena de disputa em constante negociação de sentidos. Trazendo uma interdisciplinaridade almejada no campo da alimentação e cultura, o livro reúne discussões atuais sobre fake news, mídias sociais, publicidade e considera as categorias cor/raça, gênero, classe social. A partir das perspectivas distintas acerca dos variados temas trazidos, é possível a compreensão da construção social do corpo, e da relação entre sujeito e sociedade.', '["body","commensality","food and culture","fake news","social media","advertising","race","gender","social class","social construction of the body","subject and society","negotiation of meaning"]', '10.7476/9786556308807', '9786556305363', 'https://books.scielo.org/id/3dqnm', 'https://books.scielo.org/id/3dqnm/pdf/ferreira-9786556308807.pdf', NULL, 'https://books.scielo.org/id/3dqnm/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3dz', '3dz', 'O direito à natureza na cidade', NULL, '["Wendel Henrique"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Na cidade contemporânea os lugares da natureza estão previamente selecionados e mercantilizados. O livro O Direito à Natureza na Cidade, de autoria do Professor Doutor Wendel Henrique, busca reconstruir as relações entre a cidade e a natureza, através da análise das representações, ideologias e práticas ao longo da história. O livro destaca o papel do mercado imobiliário na apropriação e produção da natureza na cidade, bem como no próprio design dessa natureza, através de padrões predefinidos e difundidos em escala global. Os elementos empíricos foram desenvolvidos através de pesquisas realizadas nas cidades de São Paulo, Florianópolis e Salvador. A obra se constitui no entendimento do uso da natureza como forma de emancipação coletiva, superando as visões correntes pautadas na apropriação da natureza para garantia da satisfação pessoal.', '["right to nature","urban nature","commodification of nature","real estate market","appropriation of nature","urban design","collective emancipation","representation of nature","São Paulo","Florianópolis","Salvador, Bahia"]', '10.7476/9788523209117', '9788523209117', 'https://books.scielo.org/id/3dz', 'https://books.scielo.org/id/3dz/pdf/henrique-9788523209117.pdf', NULL, 'https://books.scielo.org/id/3dz/cover/cover_thumbnail.jpeg', NULL, 32, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3ff', '3ff', 'Ditadura militar na Bahia novos olhares, novos objetos, novos horizontes', NULL, '["Grimaldo Carneiro Zachariadhes"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro é uma coletânea de artigos elaborados por pesquisadores baianos de diferentes áreas do conhecimento que discutem e analisam fatos relacionados ao período do regime militar na Bahia. Esse trabalho tem duas grandes missões: primeiro, possibilita que os baianos conheçam sua própria história; segundo, demonstra a importância da Bahia no processo de redemocratização do Brasil.', '["military dictatorship","Bahia","Brazilian military dictatorship","democratization","regional history","historiography"]', '10.7476/9788523211820', '9788523211820', 'https://books.scielo.org/id/3ff', 'https://books.scielo.org/id/3ff/pdf/zachariadhes-9788523211820.pdf', NULL, 'https://books.scielo.org/id/3ff/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3fgf5', '3fgf5', 'Novas janelas para o universo', NULL, '["Thyrso Villela Neto"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Physics and Astronomy', 'Estamos vivendo uma era de descobertas astronômicas fabulosas. Percebemos, a cada dia, o quanto ainda nos resta descobrir sobre o cosmos e o quanto as novas tecnologias têm nos ajudado nessa aventura do descobrimento, permitindo a abertura de novas janelas pelas quais podemos apreciar a beleza do Universo. Este volume da Coleção Paradidáticos tem por objetivo fazer que o leitor se sinta entusiasmado a participar dessa aventura e a aprender, cada vez mais, sobre o meio ambiente que nos cerca, que inclui, além do ar, dos mares, dos riso e das florestas, também o Sol, a lua, os planetas, as estrelas, as galáxias, os aglomerados de galáxias, os quasares, os pulsares, os buracos negros... Ou seja, descobrir o Universo com o auxílio de algumas ferramentas tecnológicas de que o Homem dispõe.', '["astronomy","universe","astronomical discoveries","astronomical instruments","solar system","stars","galaxies","quasars","pulsars","black holes","planets"]', '10.7476/9788539303304', '9788571395732', 'https://books.scielo.org/id/3fgf5', NULL, NULL, 'https://books.scielo.org/id/3fgf5/cover/cover_thumbnail.jpeg', 120, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3fz', '3fz', 'Do português arcaico ao português brasileiro: outras histórias', NULL, '["Klebson Oliveira","Hirão Fernandes Cunha e Souza","Juliana Soledade"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Mais uma realização do grupo de pesquisa PROHPOR (Programa para a História da Língua Portuguesa), Do Português Arcaico ao Português Brasileiro é a terceira coletânea realizada pelos especialistas do Departamento de Letras Vernáculas da Universidade Federal da Bahia, depois do sucesso de A Carta de Caminha: Testemunho Lingüístico de 1500 e O Português Quinhentista: Estudos Lingüísticos. Esta obra, organizada pelos ilustres pesquisadores da área, Américo Venâncio Lopes Machado Filho e Sônia Bastos Borba Costa, recobre estudos que vão do português arcaico e avançam ao português brasileiro contemporâneo, passando pelos séculos XVI, XVII, XVIII e XIX, recuando, em alguns casos, ao latim.', '["Portuguese language history","archaic Portuguese","Brazilian Portuguese","18th-century Portuguese"]', '10.7476/9788523211837', '9788523211837', 'https://books.scielo.org/id/3fz', 'https://books.scielo.org/id/3fz/pdf/oliveira-9788523211837.pdf', NULL, 'https://books.scielo.org/id/3fz/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3fzky', '3fzky', 'Projeto comédia Popular Brasileira da Fraternal Companhia de Artes e Malas-Artes (1993-2008): trajetória do ver, Ouvir e imaginar', NULL, '["Roberta Cristina Ninin"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O principal objetivo do presente trabalho é registrar e compreender a trajetória do Projeto Comédia Popular Brasileira (CPB) e, consequentemente, da Fraternal Companhia de Arte e Malas-Artes por meio das personagens criadas durante 15 anos de pesquisa estética (1993-2008). São objetos de análise os projetos específicos desenvolvidos a cada fase do Projeto CPB, suas respectivas peças e espetáculos, concepções de personagens, o trabalho e formação dos atores e a relação estabelecida com o alvo principal de sua vida teatral: o público. Em sua primeira fase (1993-1997) - VER, a Fraternal cria personagens-tipo brasileiras, influenciada pelos comediógrafos Martins Pena, Artur Azevedo e Ariano Suassuna, retomando o diálogo com os tipos fixos da commedia dell´arte. Na segunda fase (1998-2001) - OUVIR, as personagens-tipo cedem o protagonismo às personagens inspiradas nas festas populares medievais, pautadas no estudo teórico de Mikhail Bakhtin. E, na terceira fase (2002-2008) - IMAGINAR, atores saltimbancos apresentam as personagens por meio da narração e da representação. Neste período, a Cia. aprofunda sua prática no jogo cênico estabelecido entre personagens, atores e narradores para a construção dramatúrgica e interpretativa de seus espetáculos, inspirada em Bertolt Brecht e Luigi Pirandello. A escolha de personagens como interlocutoras dos anseios e da história do povo brasileiro refletiu, desde o início, a específica visão de mundo e de cultura popular adotada pela Fraternal, referendada no ponto de vista contrário ao da classe dominante, o da classe dominada. Dario Fo (1999), Mikhail Bakhtin (1987), Walter Benjamin (1994) e Bertolt Brecht, pautados tanto no que concerne a uma apreensão da encenação e da interpretação cômica, quanto a seus posicionamentos críticos perante a atividade artística, foram essenciais à compreensão da trajetória da Cia.', '["commedia dell''arte","character types","popular festivals","Bakhtin","Bertolt Brecht","Luigi Pirandello","Dario Fo","Walter Benjamin","actor training","audience relations","popular culture","dramaturgy"]', '10.7476/9788579830976', '9788579830976', 'https://books.scielo.org/id/3fzky', 'https://books.scielo.org/id/3fzky/pdf/ninin-9788579830976.pdf', NULL, 'https://books.scielo.org/id/3fzky/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3h38z', '3h38z', 'Três ensaios de bioética', NULL, '["Fermín Roland Schramm"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'avaliar a cogência e consistência dos argumentos morais utilizados nos conflitos bioéticos.No segundo ensaio, inédito, aplicamos as ferramentas da bioética ao caso dos conflitos morais envolvidos pelas práticas no campo da engenharia genética baseada no saber-fazer da genômica, e tentando mostrar que conflitos podem ser esses e como as ferramentas da ética aplicada chamada bioética permitem abordá-los.O terceiro ensaio é uma revisão e o aprofundamento de um capítulo de livro bastante antigo, em que, pela primeira vez, discutimos as possibilidades de que dois tipos de saber distintos -a bioética e a biossegurança -estabeleçam entre si uma interface pertinente e justificada na avaliação e gestão da prática biotecnocientífica, tendo em vista a solução de seus conflitos e a possível complementaridade das duas caixas de ferramentas.Mais especificamente, a temática do primeiro ensaio é, sobretudo, de tipo conceitual e metodológico, pois nele analisamos a possibilidade de associar dois âmbitos considerados inconciliáveis: aquele do real em que se dão as práticas dos profissionais clínicos (principalmente médicos) e aquele dos problemas conceituais e metodológicos envolvidos e analisados pela metabioética.De fato, o que faz que os dois âmbitos sejam aparentemente separados é a distinção consagrada entre atividade de primeira ordem, referente ao que se deve fazer e a como se comportar em determinadas condições -os fatos morais a serem analisados pela bioética -, e atividade de segunda ordem, a qual investiga os conceitos e os métodos utilizados no estudo dos referidos fatos morais avaliando a cogência dos argumentos em pauta que servem para justificar as práticas na clínica.Entretanto, a pergunta se é possível uma metabioética realista deverá enfrentar a possível objeção segundo a qual tal possibilidade não existe conceitualmente, por ser a consequência de uma falácia de raciocínio, pelo menos se considerarmos que o adjetivo realista se aplica normalmente a um estado de coisas em princípio independente do conhecimento (ou das ideias) que elaboramos sobre ele e que deveria, portanto, ser separado do real enquanto tal.O neologismo metabioética, por sua vez, deverá se referir a uma atividade dita de segunda ordem, constituída pela análise racional e imparcial dos conceitos, 15 juízos e argumentos morais, assim como dos métodos utilizados no processo de análise.Em suma, devido a essa distinção entre atividades de primeira e de segunda ordem, a metabioética não poderia se ocupar propriamente de problemas práticos, vivenciados no real, reservando suas ferramentas analíticas para os problemas teóricos, ou seja: lógicos, semânticos e epistemológicos, em princípio independentes dos problemas normativos, inclusive de acordo com a distinção, feita pelos linguistas, entre linguagem e metalinguagem.Entretanto, os problemas abordados pela bioética têm, além de uma dimensão teórica, uma dimensão necessariamente prática, visto que se referem, em última instância, àquilo que deveríamos fazer e a como deveríamos nos comportar em uma situação conflituosa que envolve seres vivos.Aqui, sustentaremos a tese de que é possível pensar uma metabioética realista, e defendê-la, partindo do pressuposto de que a distinção lógica entre problemas de primeira ordem e problemas de segunda ordem não implica a sua separação, uma vez que a maneira como a bioética aborda a conflituosidade vigente no set clínico pode ser vista como inseparável de uma análise dos conceitos e métodos envolvidos na argumentação, como nos ensina o método da complexidade -pois as diferenças nas concepções éticas podem ter implicações sobre as próprias tomadas de decisão.É o caso, por exemplo, dos embates, ainda atuais, sobre sacralidade e qualidade de vida e, consequentemente, sobre bioética laica e bioética religiosa, isto é, entre aqueles que remetem, em suas avaliações da moralidade da práxis humana, à sacralidade da vida ou, ao contrário, à qualidade de vida.Ou seja, de acordo com o bioeticista Maurizio Mori, entre uma concepção que "indica a inviolabilidade ou intangibilidade da vida humana" e outra que "afirma como valor fundamental a qualidade da vida humana entendida como bem-estar e/ou como respeito à autonomia das pessoas" (2002: 17).Em suma, propor uma metabioética realista implica salientar o fato de que uma análise pode ter efeitos práticos, como indica a expressão atos de fala, da linguística pragmática, nos quais dizer e fazer são inseparáveis, pois, em determinadas situações, ao dizer algo realizamos um ato locutório que tem seus efeitos práticos sobre os envolvidos, e que a bioética se propõe a abordar.A segunda temática é mais especificamente prática, embora não separada dos problemas teóricos da primeira, pois aborda a moralidade das práticas da * Reelaboração e ampliação do artigo "Questões conceituais e metaéticas da bioética clínica: uma introdução", publicado na revista Bioethikos, 6(2): 125-132, 2012.', '["bioethics","biosafety","genetic engineering","genomic knowledge","moral conflict","clinical practice","applied ethics","moral argument"]', '10.7476/9788575415863', '9788575415863', 'https://books.scielo.org/id/3h38z', 'https://books.scielo.org/id/3h38z/pdf/schramm-9788575415863.pdf', NULL, 'https://books.scielo.org/id/3h38z/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3hm55', '3hm55', 'Políticas antes da política de saúde indígena', NULL, '["Ana Lúcia de Moura Pontes","Felipe Rangel de Souza Machado","Ricardo Ventura Santos"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Quais foram os muitos caminhos, lutas e articulações que possibilitaram a construção de políticas públicas especificamente voltadas para os povos de territórios indígenas no Brasil? É esse percurso que a coletânea busca - a partir de uma perspectiva histórica e antropológica - detalhar em 13 capítulos. O livro investiga o processo de formulação do atual Subsistema de Atenção à Saúde Indígena (SasiSUS), instituído em 1999, abordando as múltiplas redes de participação que envolveram a constituição da política nacional de saúde indígena. O volume tem como base as investigações conduzidas no âmbito do projeto de pesquisa "Saúde dos Povos Indígenas no Brasil: perspectivas históricas, socioculturais", coordenado por Ricardo Ventura e Ana Lúcia Pontes, pesquisadores da Escola Nacional de Saúde Pública Sergio Arouca (Ensp/Fiocruz)', '["Indigenous health policy","public policy formulation","indigenous peoples","health networks","health policy history","Brazil"]', '10.7476/9786557081228', '9786557080467', 'https://books.scielo.org/id/3hm55', 'https://books.scielo.org/id/3hm55/pdf/pontes-9786557081228.pdf', NULL, 'https://books.scielo.org/id/3hm55/cover/cover_thumbnail.jpeg', NULL, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3hq84', '3hq84', 'Métodos para análise hematológica em peixes', NULL, '["Maria José Tavares Ranzani‐Paiva","Santiago Benites de Pádua","Marcos Tavares‐Dias","Mizue Imoto Egami"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Immunology and Microbiology', 'Este livro Preencherá uma das lacunas literárias técnico-científicas essenciais no estudo do sangue normal, no diagnóstico de doenças de peixes. Alem disso, esta obra foi elaborada com intuito de padronizar os protocolos empregados nos procedimentos hematológico.', '["fish hematology","fish disease diagnosis","normal blood values","fish pathology"]', '10.7476/9788576286530', '9788576285304', 'https://books.scielo.org/id/3hq84', NULL, NULL, 'https://books.scielo.org/id/3hq84/cover/cover_thumbnail.jpeg', 140, 199, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3hs', '3hs', 'Educação inclusiva: o professor mediando para a vida', NULL, '["Cristiane Teixeira Sampaio","Sônia Maria Rocha Sampaio"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro traz texto de apresentação, onde se explicita como a temática se tornou objeto de estudo e trabalho destas duas profissionais, seguido de uma introdução em que se discutem educação, exclusão social, direitos humanos, a realidade das pessoas com deficiência e o papel da escola neste cenário. Um capítulo de Contextualização conceitua as ideias de deficiência, inclusão versus integração, educação inclusiva e formação do professor. Depois, o capítulo Refletindo sobre a educação inclusiva apresenta a psicologia histórico-cultural de Vygotsky e as contribuições da psicanálise. Análise da inclusão na prática faz um delineamento da pesquisa e discute qualificação e problematização da inclusão no cotidiano escolar, a atuação e a formação do professor, os paradoxos e sentimentos despertados pela convivência.', '["inclusive education","social exclusion","human rights","people with disabilities","role of schools","teacher professional development","Vygotsky","historical-cultural psychology","psychoanalysis","school coexistence","school everyday life"]', '10.7476/9788523209155', '9788523209155', 'https://books.scielo.org/id/3hs', 'https://books.scielo.org/id/3hs/pdf/sampaio-9788523209155.pdf', NULL, 'https://books.scielo.org/id/3hs/cover/cover_thumbnail.jpeg', NULL, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3htzh', '3htzh', 'Relação professor e estudante na universidade', NULL, '["Silva, Fabrício Oliveira da","Ribeiro, Marinalva Lopes"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro Relação professor e estudante na universidade é uma coletânea de trabalhos oriundos da pesquisa desenvolvida pelo Núcleo de Estudos e Pesquisa sobre Pedagogia Universitária – NEPPU da Universidade Estadual de Feira de Santana. Os textos que compõem a obra trazem para a cena trabalhos que refletem os modos como os professores e estudantes mantém relações pedagógicas afetivas, considerando as necessidades de aprendizagens dos estudantes, bem como o desenvolvimento de estratégias de ensino tecidas por professores da UEFS.', '["teacher-student relationship","university pedagogy","student learning needs","teaching methods","university teaching"]', '10.7476/9788555921117', '9786589524083', 'https://books.scielo.org/id/3htzh', NULL, NULL, 'https://books.scielo.org/id/3htzh/cover/cover_thumbnail.jpeg', 371, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3hwrh', '3hwrh', 'A oeste das minas: escravos, índios e homens livres numa fronteira oitocentista Triângulo Mineiro (1750-1861)', NULL, '["Luís Augusto Bustamante Lourenço"]', 'EDUFU', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Uma leitura obrigatória não apenas para os que se interessam pela história do Triângulo Mineiro, mas também para os que procuram um modelo de geografia histórica acurada. Em uma abordagem perspicaz, reconstrói geografias do passado, contribuindo para plenamente para o entendimento do processo de produção do território nacional.', '["Triângulo Mineiro","mining frontier","slavery","indigenous peoples","free men","19th-century Brazil","territorial production","historical geography"]', '10.7476/9788570785169', '9788570785169', 'https://books.scielo.org/id/3hwrh', 'https://books.scielo.org/id/3hwrh/pdf/lourenco-9788570785169.pdf', NULL, 'https://books.scielo.org/id/3hwrh/cover/cover_thumbnail.jpeg', NULL, 24, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3k9jk', '3k9jk', 'Agriculturas empresariais e espaços rurais na globalização: abordagens a partir da América do Sul', NULL, '["Ève Anne Bühler","Martine Guibert","Oliveira, Valter Lúcio de"]', 'Editora da UFRGS', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'BISANG INTRODUÇÃONas últimas décadas, as produções baseadas no uso do solo -agricultura, pecuária, e silvicultura -estão imersas em mudanças tecnológicas, produtivas, organizacionais e comerciais de grande magnitude.Aumentos de produtividade, concentração produtiva, importância crescente das corporações em relação à agricultura familiar, profissionalização dos recursos humanos, relocalização geográfica e nova especialização produtiva são algumas manifestações deste processo disruptivo de mudança tecno-produtiva (European Union Directorate, 2012; FAO, 2011a FAO, , 2011b;;Fuglie et al. 2011; CSLS 2011; Olmstead e Rhode, 2008; OECD-FAO 2007; USDA, 2005 USDA, e 2011)).A manipulação dos códigos genéticos, as mudanças nos sistemas de cultivo, armazenamento, colheita e posterior conservação dos grãos, assim como a crescente globalização da produção e do consumo sob um modelo fragmentado e relocalizado, são algumas das diversas arestas que caracterizam o processo em curso a partir da oferta.Modificações na matriz energética (rumo aos biocombustíveis) e requisição de biomateriais (a química verde) afetam o dinamismo e a tradicional composição da demanda alimentar.O "ramo agropecuário" deixa de ser sinônimo de grãos e carnes como "ingredientes" para a preparação caseira de comida, para converter-se em fonte de matéria-prima industrial (alimentícia e outras); além disso, os tradicionais agricultores vão Traduzido por Heitor Levy.Por fim, distante da abstração teórica, mas operacionalmente relevante, vão se reconfigurando lentamente os sistemas de captação, destaque e análise dos renovados objetos analíticos.Inicialmente, o conceito limitado de produção agrária derivou na captação e posterior análise por meio de sistemas de classificação universal das atividades econômicas tendo por referência o conceito de setor; avanços mais recentes -centrados na ideia de cadeia ou rede -tornam necessária a reelaboração da contabilidade nacional para o embasamento das análises centradas no agronegócio ou na bioeconomia. REFERÊNCIAS', '["rural space","globalization","agribusiness","agribusiness clusters"]', '10.7476/9786557250044', '9786557250044', 'https://books.scielo.org/id/3k9jk', 'https://books.scielo.org/id/3k9jk/pdf/guibert-9786557250044.pdf', NULL, 'https://books.scielo.org/id/3k9jk/cover/cover_thumbnail.jpeg', NULL, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3kd7g', '3kd7g', 'História dos agrotóxicos no Brasil: usos, impactos e resistências', 'usos, impactos e resistências', '["Pereira, Elenita Malta","Casazza, Ingrid Fonseca","Lignani, Leonardo de Bem"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2026, '2026-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Pharmacology, Toxicology and Pharmaceutics', 'História dos Agrotóxicos no Brasil: usos, impactos e resistências reúne pesquisas que analisam a trajetória histórica dos agrotóxicos no país desde a década de 1940 até os dias atuais. Organizada por Elenita Malta Pereira, Ingrid Fonseca Casazza e Leonardo de Bem Lignani, a obra examina a difusão dessas substâncias na agricultura brasileira, seus impactos sobre a saúde humana e o ambiente e as diferentes formas de resistência construídas ao longo do tempo. Ao reunir contribuições de pesquisadores de diversas áreas, o livro oferece uma perspectiva histórica sobre um tema central para os debates contemporâneos em saúde, ambiente, agricultura e políticas públicas.', '["pesticides","history of pesticides","agricultural pesticides","pesticide resistance","environmental impact of pesticides","public health policy","Brazilian agriculture","pesticide regulation"]', '10.7476/9786557083062', '9786557082409', 'https://books.scielo.org/id/3kd7g', NULL, NULL, 'https://books.scielo.org/id/3kd7g/cover/cover_thumbnail.jpeg', 347, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3kq8w', '3kq8w', 'A ascensão da levedura: como um simples fungo moldou nossa civilização', NULL, '["Nicholas P. Money"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Biochemistry, Genetics and Molecular Biology', 'Este livro conta a história surpreendente da importância da levedura no desenvolvimento da civilização humana. “Era uma vez um micróbio que…” passou a fazer parte da produção de cerveja, de vinho e de pães, há cerca de dez mil anos. Desde então, nunca mais deixamos de ser parceiros desse fungo extraordinário. No século XIX tomamos consciência de sua existência e passamos a aplicar conhecimentos científicos para melhorar os processos de produção de alimentos. Com o tempo, esse fungo unicelular demonstrou ser um excelente material para estudos científicos, e muito do que sabemos hoje em biologia, incluindo a cura de inúmeras doenças, foi desvendado com a ajuda da levedura. Até as mudanças climáticas, problema fundamental, podem ser combatidas usando biocombustíveis produzidos por leveduras, que também vivem em nossa pele e em nosso sistema digestivo. Usando uma linguagem acessível e que provoca a curiosidade do leitor, mas sempre com embasamento científico, esta obra abre nossos olhos para a poderosa e indissociável realidade microscópica que nos envolve.', '["yeast","Saccharomyces cerevisiae","brewing","winemaking","bread making","food production","biofuels","climate change","human-microbe symbiosis"]', '10.7476/9788526815346', '9786586253856', 'https://books.scielo.org/id/3kq8w', NULL, NULL, 'https://books.scielo.org/id/3kq8w/cover/cover_thumbnail.jpeg', 189, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3kvj5', '3kvj5', 'O grupo Música Nova e a música eletroacústica', NULL, '["Denise Hortência Lopes Garcia"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro investiga a relação do grupo Música Nova com a mídia eletroacústica em obras pioneiras no uso de novas tecnologias no Brasil nas décadas de 60 e 70 do século XX. O texto está dividido em três partes. A primeira faz uma revisão histórica da origem e das influências dos quatro compositores que compõem o grupo, buscando compreender as forças de atuação na sua formação. A segunda parte faz uma reflexão teórica sobre o conceito de música eletroacústica, com base na comparação de um amplo conjunto de conceitos dos mais diversos autores. Essa parte é concluída com uma proposta de classificação dos usos das mídias em obras musicais, na qual se incorporam as criações dos compositores analisados. A terceira parte analisa, então, as obras, seguindo a ordem por compositor. Um trabalho não menos importante realizado na pesquisa que originou este livro foi o de restauro e atualização das mídias utilizadas na época nas obras de Gilberto Mendes, como toca-discos e gravador, traduzindo os aparelhos para aplicativos de Max/MSP, com o objetivo de recolocar esse repertório nas possibilidades de performance atuais.', '["electroacoustic music","Gilberto Mendes","Brazilian composers","Max/MSP","1960s-1970s music"]', '10.7476/9788526816688', '9788526815704', 'https://books.scielo.org/id/3kvj5', NULL, NULL, 'https://books.scielo.org/id/3kvj5/cover/cover_thumbnail.jpeg', 237, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3m4ys', '3m4ys', 'Tráfico de pessoas e mobilidade humana', NULL, '["Maria Lúcia Pinto Leal"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A coletânea de artigos incorporados à obra Tráfico de pessoas e mobilidade humana foi resultado de esforço multilateral, construído por intermédio de trabalhos de valorização da temática, viabilizado pelo Ceam/UnB e pela Editora Universidade de Brasília. As abordagens trazidas permitem atualizar conceitos e aprofundar discussões relativas aos avanços e aos desafios das políticas migratórias e de enfrentamento ao tráfico de pessoas. Elaborado por membros de uma rede composta por instituições governamentais, academia e sociedade civil organizada, o material de pesquisa fica disponível aos interessados nas discussões e iniciativas pelo fim das violações aos direitos humanos.', '["human trafficking","human mobility","migration policy","anti-trafficking policy","human rights violations"]', '10.7476/9788523013509', '9788523012205', 'https://books.scielo.org/id/3m4ys', NULL, NULL, 'https://books.scielo.org/id/3m4ys/cover/cover_thumbnail.jpeg', 196, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3mr2s', '3mr2s', 'Fome: uma (re)leitura de Josué de Castro', NULL, '["Rosana Magalhães"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1997, '1997-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Em que medida a fome continua sendo objeto de discussão e se articula no campo da saúde? Que formas de compreensão sobre o tema vêm prevalecendo historicamente? Estas são apenas algumas das perguntas que Rosana Magalhães procura responder, analisando a obra de Josué de Castro. Assim, este livro se contextualiza nas décadas de 80 e 90, quando a fome passa a ser vista como problema político e de cidadania, demandando consenso e cooperação entre o Estado e a sociedade civil. A autora tem, ainda, o cuidado de ressalvar que sua interpretação não é a que detém a verdade absoluta, convidando os interessados ao debate sobre um "pensamento marcante no estudo da fome, tanto no cenário nacional quanto no internacional".', '["hunger","food insecurity","health","citizenship","political economy of food","state and civil society","1980s-1990s"]', '10.7476/9788575413968', '9788575413968', 'https://books.scielo.org/id/3mr2s', 'https://books.scielo.org/id/3mr2s/pdf/magalhaes-9788575413968.pdf', NULL, 'https://books.scielo.org/id/3mr2s/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3mrgm', '3mrgm', 'Mulheres dos cabelos brancos: cartografias do cuidado de si no mundo do samba', NULL, '["Adriana Miranda de Castro"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '2ª lugar do 8º Prêmio ABEU, 2022 – Categoria: Ciências humanas. Aborda o encontro entre os discursos e práticas sobre a saúde e o envelhecimento oriundos da biomedicina, da epidemiologia e da promoção da saúde com a experiência que constitui uma “tia” no mundo do samba. Com esse intuito, apresenta e analisa vivências das mulheres integrantes da Ala dos Cabelos Brancos, do Grêmio Recreativo Escola de Samba Império Serrano, e de compositores e sambistas que integram esse universo cultural, além de dialogar com autores de diversos campos do pensamento. A partir desses depoimentos, a autora investiga como as senhoras do samba lidam com as representações e conceitos de vida saudável, e se elas demonstram algum tipo de resistência à medicalização da vida, entre outros aspectos. O conteúdo constrói um viés crítico sobre a produção e circulação de discursos e práticas ligados à medicalização da vida e sua promessa de saúde e longevidade calcada na adoção de um modo de viver baseado na hiperprevenção.', '["women''s aging","samba","medicalization of life","self-care","health promotion","older women","samba schools","health representations","resistance to medicalization"]', '10.7476/9786587949390', '9786587949352', 'https://books.scielo.org/id/3mrgm', NULL, NULL, 'https://books.scielo.org/id/3mrgm/cover/cover_thumbnail.jpeg', 228, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3mxq8', '3mxq8', 'A Literatura do Outro e os Outros da literatura', NULL, '["Maria Heloisa Martins Dias","Sônia Helena de Oliveira Raymundo Piteri","Raymundo Piteri"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Maria Celeste Tommasello Ramos 1Estudos críticos apontam para a importância do diálogo que os textos literários escritos por Machado de Assis travam com outros textos, autores e fatores de culturas diversas.Entre eles está o estudo realizado por Eugênio Gomes, que verificou o recurso machadiano de utilizar as ideias dos outros como partida ou sugestão para dar a elas desenvolvimento e desfecho imprevistos.Gomes (1958, p.97) declara ser "imprescindível a necessidade de tais investigações [estudo dos diálogos intertextuais], até porque abrem caminho à elucidação do processo de criação ou recriação artística em muitas de suas minúcias reveladoras".Ele estudou a presença inglesa na obra machadiana em Influências inglesas em Machado de Assis.', '["Machado de Assis","intertextuality","literary dialogue","otherness in literature"]', '10.7476/9788579831119', '9788579831119', 'https://books.scielo.org/id/3mxq8', 'https://books.scielo.org/id/3mxq8/pdf/dias-9788579831119.pdf', NULL, 'https://books.scielo.org/id/3mxq8/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3nj6y', '3nj6y', 'Sujeitos da história do ensino de leitura e escrita no Brasil', NULL, '["Maria do Rosário Longo Mortatti","Estela Natalina Mantovani Bertoletti","Fernando Rodrígues de Oliveira","Márcia Cristina de Oliveira Mello","Thabatha Aline Trevisan"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Interrogar sobre o passado de uma das principais atividades educativas na escolarização inicial de crianças – o ensino de leitura e escrita – é o objetivo central desta obra. Entre as várias contribuições relevantes do livro, uma coletânea de 14 ensaios que abrangem mais de um século, da década de 1870 aos dias atuais, sobressai-se a importância da própria temática para a compreensão da cultura escolar.Os estudos põem em destaque cartilhas, livros de leitura, manuais, textos, artigos publicados em jornais e periódicos, polêmicas em torno dos métodos de ensino e a atuação de quem produziu e problematizou sobre o ensino de leitura e escrita no país. Estão contemplados tanto os interesses econômicos e comerciais subjacentes à produção de materiais para esse ensino quanto as tensões políticas que envolveram as disputas dos educadores, o que permite ao leitor aproximar-se das tematizações, concretizações e normatizações que ao longo do tempo pautaram o debate político e pedagógico sobre a alfabetização no Brasil.O primeiro texto da coletânea trata do método de alfabetização de Thomaz Paulo de Bom Sucesso Galhardo, autor da Cartilha da infância, publicada entre a década de 1880 e o ano de 1992. Seguem-se estudos sobre as experiências de Antonio da Silva Jardim (1860-1891), João Köpke (1852-1926), Ramon Roca Dordal (1854-1938) e Carlos Alberto Gomes Cardim (1875-1938), Arnaldo de Oliveira Barreto (1869-1925), Francisco Vianna (1876-1935), Theodoro de Moraes (1877-1956), Antonio Firmino Proença (1880-1946), Renato Fleury (1895-1980), Lourenço Filho (1897-1970), Antônio D’Ávila (1903-1989), Bárbara V. de Carvalho (1915-2008), Emilia Ferreiro (1935) e João Wanderley Geraldi (1946).', '["reading and writing instruction","literacy education","history of education in Brazil","school culture","reading textbooks","teaching methods","early schooling","educational content development"]', '10.7476/9788568334362', '9788568334362', 'https://books.scielo.org/id/3nj6y', 'https://books.scielo.org/id/3nj6y/pdf/mortatti-9788568334362.pdf', NULL, 'https://books.scielo.org/id/3nj6y/cover/cover_thumbnail.jpeg', NULL, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3nwpf', '3nwpf', 'A construção intelectual do Brasil conteporâneo: da resistência à ditadura ao governo FHC', NULL, '["Bernardo Sorj"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A sensação de insegurança que a falta de recuo histórico transmite nos levou a engavetar por longo tempo a publicação deste livro, cujo objeto central é uma instituição à qual estiveram associadas muitas das principais figuras da vida política brasileira contemporânea, tanto do governo como da oposição.', '["intellectual history","resistance to dictatorship","FHC government","politicians"]', '10.7476/9788599662472', '9788599662472', 'https://books.scielo.org/id/3nwpf', 'https://books.scielo.org/id/3nwpf/pdf/sorj-9788599662472.pdf', NULL, 'https://books.scielo.org/id/3nwpf/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3nwvp', '3nwvp', 'Gramsci en Ecuador', NULL, '["Ortiz Crespo, Santiago"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2024, '2024-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra delinea los contornos y la influencia de Antonio Gramsci en Ecuador. Se advierte su influjo en las ciencias sociales en el debate sobre la nación y el Estado, los intelectuales, la crisis del sistema político, el análisis de las relaciones de fuerza la filosofía y la cultura. Sin embargo, no se evidencia tanto ese influjo en la política, pues a diferencia de otros países de América Latina, los partidos de izquierda solo asumieron de manera tardía los postulados gramscianos en Ecuador. Este libro recoge el aporte de diecisiete autores y coautores ecuatorianos a través de ensayos, análisis de procesos y testimonios biográficos, configurando un primer acercamiento diverso y plural del pensador italiano.', '["Antonio Gramsci","Ecuador","state and nation","intellectuals","political crisis","relations of force","philosophy and culture","left-wing parties","Latin American Marxism"]', '10.7476/9789942461100', '9789942460691', 'https://books.scielo.org/id/3nwvp', NULL, NULL, 'https://books.scielo.org/id/3nwvp/cover/cover_thumbnail.jpeg', 416, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3nwyv', '3nwyv', 'Ensino de ciências e matemática III : contribuições da pesquisa acadêmica a partir de múltiplas perspectivas', NULL, '["Fernando Bastos"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro Ensino de Ciências e Matemática III: contribuições da pesquisa acadêmica a partir de múltiplas perspectivas, publicado pela Cultura Acadêmica Editora, tem como objetivo comunicar e oferecer ao debate alguns resultados recentes da produção de pesquisa do Programa de Pós -Graduação em Educação para a Ciência da UNESP, vinculado à Faculdade de Ciências do Campus de Bauru (SP).Assim, reúne, para acesso de pesquisadores, professores e estudantes, nove relatos oriundos de trabalhos de mestrado, doutorado, pós -doutorado e similares, desenvolvidos no referido Programa e passíveis de contribuir para a discussão e o encaminhamento de uma série de questões atuais do Ensino de Ciências.A preparação deste livro iniciou -se com a chamada e seleção preliminar de propostas que fornecessem os textos para os diversos capítulos.Fui incumbido de uma parte desse trabalho, e desde logo ficou evidente a variedade de temáticas e abordagens que vinham sendo enfatizadas pelos pesquisadores que enviavam seus relatos para análise.Um primeiro critério para selecionar o material destinado a integrar o presente volume foi buscar textos cuja abordagem favorecesse discussões de caráter geral, isto é, discussões sobre o ensino escolar e questões sociais e culturais, sobre pesquisa em educação em ciências e sobre metaquestões que se levantam a partir das análises da história e da epistemologia das ciências naturais.', '["science education","mathematics education","science education research","school science teaching","history of natural sciences","epistemology of natural science"]', '10.7476/9788579830860', '9788579830860', 'https://books.scielo.org/id/3nwyv', 'https://books.scielo.org/id/3nwyv/pdf/bastos-9788579830860.pdf', NULL, 'https://books.scielo.org/id/3nwyv/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3p7zc', '3p7zc', 'Os Índios no Império do Brasil: a etnografia do IHGB entre as décadas de 1840 e 1860', NULL, '["Kaori Kodama"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O principal objetivo da historiadora neste livro é analisar como se deu a criação da Seção de Etnografia e Arqueologia no Instituto Histórico e Geográfico do Brasil (IHGB). Formada pela elite letrada imperial oitocentista, esta Seção contava com homens comprometidos em originar um projeto político de desenho da nação brasileira que considerava o papel que caberia ao indígena nesse processo de gestação. A obra está fundamentada em uma sólida pesquisa documental. Ao se deparar com seu conteúdo, o leitor terá a oportunidade de percorrer a identidade nacional do século XIX em um de seus aspectos mais complexos – a questão indígena -, por uma via pouco explorada. Dividido em três partes, a primeira trata de um apanhado das diversas representações do índio brasileiro. Na segunda parte, a autora aponta os pressupostos implícitos na criação de um campo etnográfico no IHGB em diálogo com o problema da nação no Império do Brasil. Já na terceira e última parte, ela associa a criação do IHGB a certas práticas etnográficas levadas adiante em nome do próprio governo imperial.', '["indigenous peoples","ethnography","archaeology","nation-building","national identity","Brazilian Empire","imperial government","ethnographic fieldwork","19th century"]', '10.7476/9786557082232', '9786557082232', 'https://books.scielo.org/id/3p7zc', 'https://books.scielo.org/id/3p7zc/pdf/kodama-9786557082232.pdf', NULL, 'https://books.scielo.org/id/3p7zc/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3q', '3q', 'Avaliação e sociedade: a negociação como caminho', NULL, '["Robinson Moreira Tenório","Vieira, Marcos Antônio"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro é uma coletânea de artigos produzidos nos dois últimos anos pelo Grupo de Avaliação da FACED. São 11 artigos produzidos por 16 autores, imprimindo um caráter multidisciplinar e interdisciplinar ao conjunto da obra.', '["evaluation","society","negotiation","multidisciplinary assessment"]', '10.7476/9788523209346', NULL, 'https://books.scielo.org/id/3q', 'https://books.scielo.org/id/3q/pdf/tenorio-9788523209346.pdf', NULL, 'https://books.scielo.org/id/3q/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3qdrg', '3qdrg', 'Juventude e trabalho: desafios no mundo contemporâneo', NULL, '["Denise Helena Pereira Laranjeira","Rosa Elisa Mirra Barone"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro visa contribuir com as análises sobre a condição plural da juventude na contemporaneidade, frente aos desafios e as possibilidades para a (re)inserção socioprofissional, com ênfase nas articulações com os campos da educação e da cultura. Os artigos que compõem esse livro discutem sobre a relação juventude e trabalho dentro da contemporaneidade, considerando ora o contexto macro da concepção das políticas públicas e/ou dos diferentes programas, ora o cenário micro, marcado pelos desafios, dificuldades e ganhos para os jovens.', '["youth","youth employment","social and professional reintegration","youth policy","contemporary youth","public policy programs"]', '10.7476/9788523220143', '9788523216450', 'https://books.scielo.org/id/3qdrg', NULL, NULL, 'https://books.scielo.org/id/3qdrg/cover/cover_thumbnail.jpeg', 396, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3qp89', '3qp89', 'Medicina da noite: da cronobiologia à prática clínica', NULL, '["José Manoel Jansen","Agnaldo José Lopes","Ursula Jansen","Domenico Capone","Teresinha Yoshiko Maeda","Gerson Magalhães"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2007, '2007-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'Neste livro os autores, pelo saber e pela experiência, buscam clarear os médicos para que atentem aos conhecimentos biopsiquicos da noite e do dormir. A cronobiologia é uma ciência que abrange todos os seres vivos e estuda os fenômenos biológicos em função do tempo, especialmente aqueles que apresentam caráter cíclico. “Entender que o organismo humano modifica-se à noite e que certas doenças expressam-se mais ou preferentemente nesse período é um ganho do médico no trato com seus pacientes”. A idéia de unir, em um só volume, a fisiologia e a fisiopatologia das doenças noturnas é oportuna, necessária e pedagógica.', '["chronobiology","sleep","circadian rhythm","clinical practice"]', '10.7476/9788575413364', '9788575413364', 'https://books.scielo.org/id/3qp89', 'https://books.scielo.org/id/3qp89/pdf/jansen-9788575413364.pdf', NULL, 'https://books.scielo.org/id/3qp89/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3r8dc', '3r8dc', 'Sombras de Leocádia de Tal', 'relatos de um crime na Bahia oitocentista', '["Fernando Donato Vasconcelos","Gervásio Fernandes Araújo Júnior","Maria de Fátima Novaes Pires","Rosângela Figueiredo Miranda","Tatyane Miranda Caires"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2026, '2026-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Uma investigação sobre as memórias fragmentadas e imaginadas em torno do assassinato de Leocádia de Tal na Bahia de 1800. Com base em uma diversidade de documentos, como inquéritos policiais, processos-crimes e relatos orais, a obra faz surgir novas perspectivas sobre o cotidiano, as espiritualidades populares e a historicidade das violências contra as mulheres. O livro convida o leitor a percorrer os caminhos da memória no antigo arraial de Beija-Flor (Guanambi), revelando as dinâmicas de uma vida social marcada por ritos, conflitos e desigualdades nos rincões do país.', '["memory","popular spirituality","violence against women","Guanambi","colonial Bahia","police investigation","criminal trials","oral testimony","popular ritual","social inequality","everyday life"]', '10.7476/9786556309989', '9786556308630', 'https://books.scielo.org/id/3r8dc', 'https://books.scielo.org/id/3r8dc/pdf/vasconcelos-9786556309989.pdf', NULL, 'https://books.scielo.org/id/3r8dc/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3rfdc', '3rfdc', 'Clarice Lispector e a encenação da escritura: em "A via crucis do corpo"', NULL, '["Nilze Maria de Azeredo Reguera"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O interesse da autora em relação ao livro A via crucis do corpo, de Clarice Lispector, lançado em 1974, deve-se, num primeiro momento, ao fato de o mesmo ter sido considerado uma "obra menor", um "desvio" ou, até mesmo, um "lixo", quando comparado às demais publicações da autora, por ter sido escrito "por encomenda", "às pressas", num período em que a escritora passava por dificuldades financeiras. Buscando suscitar elementos que permitam a (re)avaliação dessa visão, Nilze Reguera apresenta uma leitura da obra sob a perspectiva da encenação, considerando como a simulação ("parecer" e "não-ser") e a dissimulação ("não-parecer" e "ser") se entrelaçam no texto.', '["Clarice Lispector","mise-en-scène","simulation","dissimulation"]', '10.7476/9788539302901', '9788571396968', 'https://books.scielo.org/id/3rfdc', NULL, NULL, 'https://books.scielo.org/id/3rfdc/cover/cover_thumbnail.jpeg', 288, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3ryj8', '3ryj8', 'Ser-Tão baiano: o lugar da sertanidade na configuração da identidade baiana', NULL, '["Cláudia Pereira Vasconcelos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Nesta obra, a autora investiga o conceito de baianidade, centrado na cidade de Salvador e em seu Recôncavo. Problematiza a visão da “cultura baiana” amplamente divulgada, inclusive pelas agências de políticas culturais do estado. Compreende a ideia de sertão e os possíveis motivos para a negação de uma tradição sertaneja na Bahia. Tem a obra de Jorge Amado como referência para a construção da ideia de baianidade, o autor Gilberto Freyre como referência da nordestinidade e, por fim, o trabalho de Eurico Alves como principal discurso de afirmação da sertanidade.', '["sertão","regional identity","Salvador, Bahia","Recôncavo","Jorge Amado","Gilberto Freyre","cultural policy","Bahia"]', '10.7476/9788523212339', '9788523208028', 'https://books.scielo.org/id/3ryj8', NULL, NULL, 'https://books.scielo.org/id/3ryj8/cover/cover_thumbnail.jpeg', 141, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3s3vw', '3s3vw', 'Gêneros textuais em contexto de vestibular', NULL, '["Juliano Desiderato Antônio","Pedro Antonio Navarro"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Como forma de colaborar com o trabalho desenvolvido pelos professores e pelas escolas, este livro reúne questões teóricas e caminhos metodológicos para o tratamento da escrita, em contexto escolar, sob o mirante da teoria dos gêneros textuais, levando em conta os gêneros solicitados no vestibular da UEM. Não se trata de um manual a ser ‘seguido’ por professores e muito menos por alunos, mas de um livro de cunho acadêmico cujo objetivo é fomentar a reflexão a respeito dos gêneros solicitados pelo vestibular da UEM, permitindo que os professores do ensino médio construam suas abordagens e metodologias de ensino dos gêneros da forma que considerarem mais adequada às suas realidades. Os capítulos foram produzidos por professores e por pesquisadores familiarizados com o trabalho com os gêneros textuais no contexto dos vestibulares da UEM. Todos os autores atuam ou atuaram como membros da banca de avaliação de redação dos vestibulares da UEM; outros atuam ou atuaram como coordenadores da banca; alguns pesquisaram a fundo alguns desses gêneros em seus projetos de pesquisa institucional ou de pós-graduação, em nível de mestrado ou doutorado.', '["textual genres","college entrance examination","writing instruction","secondary school teaching","writing assessment","teaching methods"]', '10.7476/9788576287414', '9788576287056', 'https://books.scielo.org/id/3s3vw', NULL, NULL, 'https://books.scielo.org/id/3s3vw/cover/cover_thumbnail.jpeg', 276, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3sc6y', '3sc6y', 'Infiltrados e invasores: uma perspectiva comparada sobre relações de classe no cinema brasileiro', NULL, '["Mariana Souto"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A obra analisa as relações de classe em filmes brasileiros do período pós-retomada, entre ficções e documentários, realizando também aproximações com o cinema de outros tempos. Agrupados em pequenos conjuntos, filmes como “Que horas ela volta?”, “O som ao redor”, “Doméstica”, “Santiago” e “Um lugar ao sol” são colocados em diálogo numa perspectiva comparativa que oferece ao leitor um olhar crítico sobre tendências de nossa época. A partir da observação de aspectos formais, a autora avalia as tensões, os conflitos e os afetos entre personagens de classes distintas. O livro é fruto da pesquisa de doutorado de Mariana Souto, vencedora do Prêmio Capes de Teses em 2017.', '["class relations","Brazilian cinema","film analysis","comparative film analysis","social class in film","class struggle","Brazilian documentary film"]', '10.7476/9786556302010', '9788523219215', 'https://books.scielo.org/id/3sc6y', NULL, NULL, 'https://books.scielo.org/id/3sc6y/cover/cover_thumbnail.jpeg', 252, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3srg4', '3srg4', 'Mestrado profissional em saúde pública: caminhos e identidade', NULL, '["Gideon Borges dos Santos","Virgínia Alonso Hortale","Rafael Arouca"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Analisar a identidade do mestrado profissional, especialmente no campo da saúde pública: este foi o desafio assumido pelos autores. Um desafio porque, segundo os pesquisadores, a identidade desses cursos ainda carece de precisão e, consequentemente, de legitimidade. A formação no mestrado profissional tem um compromisso com a experiência proveniente do mundo do trabalho. É necessária uma estrutura curricular diferenciada, que articule o ensino à aplicação profissional. Na prática, porém, essa integração e a inovação ainda encontram uma série de obstáculos. Com o objetivo de construir novos entendimentos acerca das singularidades e características do mestrado profissional em saúde pública, os autores dividiram o livro em seis capítulos. No primeiro, traçam um panorama internacional da formação em saúde pública em nível de mestrado. Em seguida, analisam o marco legal referente à formulação e à implementação do mestrado profissional no Brasil. Depois, apresentam a oferta desses cursos no campo da saúde pública no país. O quarto capítulo é dedicado ao sistema de avaliação da pós-graduação brasileira. O quinto traz uma reflexão sobre o modelo de formação, enquanto o sexto, para finalizar, pensa o mestrado profissional como uma instância escolar de socialização.', '["professional master''s degree","public health education","professional identity","curriculum development","work-based learning","postgraduate assessment","socialization"]', '10.7476/9788575415801', '9788575414156', 'https://books.scielo.org/id/3srg4', NULL, NULL, 'https://books.scielo.org/id/3srg4/cover/cover_thumbnail.jpeg', 104, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
