ations.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3tfnp', '3tfnp', 'Violência sexual infantojuvenil, entre proteger e responsabilizar: limites e alcances da Lei do Depoimento Especial', NULL, '["Fábio de Carvalho Mastroianni","Andreza Marquês de Castro Leão"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A violência sexual infantojuvenil é um tema que demanda cuidado e estratégias que tenham por finalidade evitá-la. Neste livro, os autores abordam a maneira como crianças e adolescentes foram historicamente tratados pelos adultos e, ao mesmo tempo, apresentam os movimentos e as legislações dirigidas à proteção do público infantil, o que deu origem a avanços e diversas leis voltadas a esses indivíduos, sobretudo no século XX.', '["child sexual violence","child protection law","children''s rights","history of child protection","victim responsibility"]', '10.7476/9786559543809', '9786559543809', 'https://books.scielo.org/id/3tfnp', 'https://books.scielo.org/id/3tfnp/pdf/mastroianni-9786559543809.pdf', NULL, 'https://books.scielo.org/id/3tfnp/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3tqqd', '3tqqd', 'Raça: novas perspectivas antropológicas', NULL, '["Osmundo de Araújo Pinho","Lívio Sansone"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Co-edição EDUFBA-ABA O livro é uma coletânea sobre etnia e raça no Brasil. Tem como objetivo mostrar o acúmulo histórico sobre o tema em suas diversas articulações e retratar os novos impasses e desafios dos estudos étnicos e raciais. Aponta que, de um modo geral, os estudos antropológicos sobre identidades e cultura negra transitam em um campo interdisciplinar onde são possíveis múltiplas abordagens.', '["race","ethnicity","Black identity","Black culture","racial studies","ethnic studies","anthropology of race","Brazil"]', '10.7476/9788523212254', '9788523212254', 'https://books.scielo.org/id/3tqqd', 'https://books.scielo.org/id/3tqqd/pdf/pinho-9788523212254.pdf', NULL, 'https://books.scielo.org/id/3tqqd/cover/cover_thumbnail.jpeg', NULL, 27, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3vj9m', '3vj9m', 'Vozes femininas da poesia latino-americana: Cecília e as poetisas uruguaias', NULL, '["Jacicarla Souza da Silva"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A partir da década de 80 do século XX, como se sabe, os textos escritos por mulheres começam a receber merecida atenção da crítica literária latino-americana. São discutidas, portanto, as formas pelas quais são lidas e criticadas as obras de autoria feminina. Deste modo, este trabalho pretende mostrar a importância do ensaio Expressão feminina da poesia na América, da poetisa Cecília Meireles, em relação aos estudos feministas na América Latina, destacando o diálogo que se estabelece entre a autora brasileira e as poetisas hispano-americanas, em especial, as uruguaias. Cabe destacar que o referido ensaio corresponde a uma conferência proferida no ano de 1956, na Universidade do Brasil, e apresenta um panorama da expressão lírica feminina na América hispânica. São comentados aspectos significativos da poesia de grandes representantes, desde a barroca Sóror Juana Inés de la Cruz até a contemporânea de Cecília, a chilena Gabriela Mistral. Observase que as poetisas mencionadas pela autora de Viagem desempenham um importante papel no cenário da produção poética de seus respectivos países. É de se estranhar, portanto, que grande parte delas não integre a historiografia tradicional canônica, injustiça que o ensaio ceciliano corrige. Ao considerar que a crítica feminista atual preocupa-se em resgatar os textos de autoria feminina esquecidos pela crítica tradicional, como também questionar as leituras e métodos sustentados por essa crítica canônica, pode-se afirmar que, através da referida conferência, Cecília demonstra seu caráter precursor diante da crítica literária feminista na América Latina, trazendo à luz uma produção duplamente...', '["Cecília Meireles","women poets","Latin American poetry","feminist literary criticism","Gabriela Mistral","women''s lyric poetry","literary canon","women''s writing history"]', '10.7476/9788579830327', '9788579830327', 'https://books.scielo.org/id/3vj9m', 'https://books.scielo.org/id/3vj9m/pdf/silva-9788579830327.pdf', NULL, 'https://books.scielo.org/id/3vj9m/cover/cover_thumbnail.jpeg', NULL, 23, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
