INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3vybf', '3vybf', 'O Público Infantil: intelectuais, mídias e divulgação do conhecimento', 'intelectuais, mídias e divulgação do conhecimento', '["Ângela de Castro Gomes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2026, '2026-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'No livro "O Público Infantil: intelectuais, mídias e divulgação do conhecimento", Angela de Castro Gomes analisa historicamente como intelectuais, educadores, editores e meios de comunicação participaram da formação do público infantil leitor no Brasil entre o final do século XIX e as primeiras décadas do século XX. Na obra, investiga-se como livros, revistas, rádio, quadrinhos e outras mídias foram usados para divulgar conhecimentos, valores e projetos educacionais voltados às crianças, especialmente no contexto das reformas educacionais e das políticas culturais do período, incluindo iniciativas do Ministério da Educação durante o governo de Getúlio Vargas. Ao explorar debates pedagógicos, práticas editoriais e a atuação de intelectuais mediadores, o livro mostra como a infância foi progressivamente reconhecida como um público estratégico para a construção de leitores, cidadãos e de uma identidade nacional brasileira.', '["children''s literature","intellectuals","media","knowledge dissemination","educational reform","cultural policy","Getúlio Vargas government","Ministry of Education","children''s magazines","comics","radio","editorial practice"]', '10.7476/9786557083055', '9786557082065', 'https://books.scielo.org/id/3vybf', NULL, NULL, 'https://books.scielo.org/id/3vybf/cover/cover_thumbnail.jpeg', 235, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3w52w', '3w52w', 'Política e afetividade: narrativas e trajetórias de pesquisa', NULL, '["Manoel Mendonça Filho","Maria Teresa Nobre"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro apresenta textos dos professores pesquisadores do Grupo de Estudos e Pesquisas sobre Exclusão, Cidadania e Direitos Humanos (GEPEC) da Universidade Federal de Sergipe (UFS) e de pesquisadores convidados de outras instituições públicas de ensino superior.', '["affect","research trajectories","narrative","social exclusion","citizenship","human rights"]', '10.7476/9788523208974', '9788523208974', 'https://books.scielo.org/id/3w52w', 'https://books.scielo.org/id/3w52w/pdf/mendonca-9788523208974.pdf', NULL, 'https://books.scielo.org/id/3w52w/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3w9vj', '3w9vj', 'Uma parada selvagem: para ler as iluminações de Rimbaud', NULL, '["Adalberto Luis Vicente"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Poucas são as obras dedicadas à poesia moderna que não façam referência à produção poética de Arthur Rimbaud. Em sua lírica, ocorrem simultaneamente a ruptura com certa tradição literária e a criação de uma linguagem e de uma técnica de escritura que vão repercutir profundamente na poesia posterior. O livro trata de um estudo sobre a obra As iluminações, precedido de reflexões sobre a produção literária do poeta e de caracterizações do poema em prosa. Um dos poemas mais importantes dessa obra, "Parade", termina com uma frase desafiadora: "Somente eu tenho a chave dessa parada selvagem". Com esse desafio irônico, o poeta chamava atenção para um dos pontos fundamentais de sua poética: o texto põe em questão nossos hábitos de leitura, desafia nosso conhecimento lógico, faz com que coloquemos os pés em um universo cuja ordem não é mais aquela que percebemos na realidade.', '["Arthur Rimbaud","illumination","parades","modern poetry","poetics","reading habits","literary tradition","poetic language","prose poetry"]', '10.7476/9788539304547', '9788539300075', 'https://books.scielo.org/id/3w9vj', NULL, NULL, 'https://books.scielo.org/id/3w9vj/cover/cover_thumbnail.jpeg', 121, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3wf8m', '3wf8m', 'Corpo de vento: Exu da teoria: travessias crítico-performativas pelas artes negras', NULL, '["Denise França Carrascosa"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro convida para uma roda de conversa sobre alguns modos de ser e de usar a literatura, um espaço de troca no qual ventos diversos circulam, injetando energias e estéticas variadas. Organizado em sete “giras” , desde o sumário, incita a pensar, raciocinar fora da linha reta e no interior de uma lógica que foge da rigidez de uma certa tradição teórica ocidental, sem desprezar o rigor ou a seriedade crítica. Textualidades literárias, proposições e reflexões teóricas são colocadas lado a lado para discutir temas muito caros à crítica literária contemporânea, tais como “a crise da representação”, pós-colonialidade, pós-escravismo, performances, racismo e direitos humanos, dentre outros. Os textos exploram conceito-fundamentos como Exu da teoria, encantoria, crítica performativa, odusciência, corpo movimento.', '["Afro-Brazilian art","Black literature","performativity","performance","crisis of representation","postcoloniality","post-slavery","racism","human rights","body and movement"]', '10.7476/9786556308753', '9786556305813', 'https://books.scielo.org/id/3wf8m', NULL, NULL, 'https://books.scielo.org/id/3wf8m/cover/cover_thumbnail.jpeg', 260, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3wj6h', '3wj6h', 'Um sabiá sujo: a aventura científica sobre a descoberta de uma ave e de um continente', NULL, '["Marcos Rodrigues"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Este livro é uma viagem pela América do Sul sob a luz de uma espécie de ave que só foi descoberta em 2007 e formalmente descrita em 2012. Inicialmente a ave mais parecia um sabiá sujo, mas hoje é conhecida como pedreiro-do-espinhaço. Existem mais de dez mil espécies de aves no planeta. Qual seria a importância de mais uma nesse contexto de milhares? A descoberta do pedreiro-do-espinhaço suscitou um enigma biogeográfico, pois ele pertence a um grupo de espécies que se originou e evoluiu nas altas montanhas da Cordilheira dos Andes e nos frios campos da Patagônia. Como poderia ter surgido nas montanhas de Minas Gerais, local tão distante dessas regiões? O livro é sobre esse paradoxo biogeográfico explicado à luz das mais recentes descobertas da biologia evolutiva em linguagem que lembra um thriller investigativo.', '["new species description","biogeography","Andes","Patagonia","Minas Gerais","evolutionary biology","South America"]', '10.7476/9786586253740', '9786586253566', 'https://books.scielo.org/id/3wj6h', NULL, NULL, 'https://books.scielo.org/id/3wj6h/cover/cover_thumbnail.jpeg', 368, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3wr9p', '3wr9p', 'Independência &amp; Instrução no Brasil: história, memória e formação (1822-1972)', NULL, '["Limeira, Aline de Morais","Clemente, Edgleide","Gongra, José"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Os processos de instrução, escolarização e formação das populações, assim como a produção de um conjunto de narrativas em disputa sobre histórias e memórias da Independência, em épocas e cenários distintos, constituem os eixos centrais nos quatorze artigos do livro. A primeira parte da obra, intitulada “O processo (in)acabado da emancipação”, apresenta seis trabalhos que instituem um conjunto multifacetado de fontes documentais, com o intuito de pensar os processos inconclusos da Independência e seus rebatimentos na produção de distintas histórias, memórias e projetos de nação. Já na segunda parte, “O dever de (des)lembrar”, oito artigos revisitam momentos históricos distintos dos atos, festejos e produções em torno das comemorações e lembranças da independência política do país. A educação e a formação do povo e da nação são os eixos primordiais dessa coletânea, que contribui, de forma original, para os debates contemporâneos da historiografia nacional.', '["Brazilian independence","education history","school education","national formation","collective memory","independence celebrations","nation-building","Brazilian historiography"]', '10.7476/9786587949499', '9786587949482', 'https://books.scielo.org/id/3wr9p', NULL, NULL, 'https://books.scielo.org/id/3wr9p/cover/cover_thumbnail.jpeg', 586, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3wsmq', '3wsmq', 'Católico, protestante, cidadão: uma comparação entre Brasil e Estados Unidos', NULL, '["Angela Randolpho Paiva"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Direitos humanos e cidadania são concepções que surgiram no momento em que o indivíduo passou a ser o fundamento ontológico para a organização dos diversos Estados nacionais do mundo ocidental. Ganharam estatuto jurídico ao serem incluídas na pauta das discussões políticas no período de construção dos diversos Estados - nação que se formavam, principalmente no século XIX.[...] [trecho retirado da introdução do livro]', '["human rights","citizenship","Catholicism","Protestantism","religion and citizenship","comparative constitutional law","Brazil","nation-building","individualism"]', '10.7476/9788579820410', '9788579820410', 'https://books.scielo.org/id/3wsmq', 'https://static.scielo.org/scielobooks/3wsmq/pdf/paiva-9788579820410.pdf', NULL, 'https://books.scielo.org/id/3wsmq/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3ww26', '3ww26', 'Violência sob o olhar da saúde: infrapolítica da contemporaneidade brasileira', NULL, '["Minayo, Maria Cecília de Souza","Edinilsa Ramos de Souza"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Apresenta um panorama atualizado sobre o impacto da violência na saúde pública. Examinam-se as tendências das produções científicas sobre o assunto e busca-se conceituar o tema em seus aspectos filosóficos, teóricos, sociais e culturais. Analisam-se também a mortalidade por causas externas no Brasil, a morbidade por envenenamento e as diferentes formas de violência, assim como a relação entre drogas e violência e entre mídia e violência. Obra que traz contribuição tanto para os envolvidos com a saúde coletiva, a sociologia, a antropologia e a segurança pública como para os formuladores e gestores das políticas públicas.', '["violence","public health","infrapolitics","external causes of death","forms of violence","media and violence","public policy","Brazil"]', '10.7476/9786557081150', '9786557081150', 'https://books.scielo.org/id/3ww26', 'https://books.scielo.org/id/3ww26/pdf/minayo-9786557081150.pdf', NULL, 'https://books.scielo.org/id/3ww26/cover/cover_thumbnail.jpeg', NULL, 24, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3y5xk', '3y5xk', 'Equidade e Saúde: contribuições da epidemiologia', NULL, '["Rita Barradas Barata","Maurício L. Barreto","Naomar de Almeida Filho","Renato Peixoto Veras"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1997, '1997-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A interpretação do princípio constitucional do direito ΰ saúde deve ser feita levando-se em conta tais significados.Não se trata simplesmente de oferecer um "mínimo de cuidados a todos os indivíduos, mas, antes, de atender as necessidades humanas segundo o princípio da eq٧idade, vale dizer, a "disposição de reconhecer igualmente o direito de cada um", o "sentimento de justiça avesso a um critério rigoroso e estritamente legal" (Ferreira, 1986).Qual a contribuição possível da Epidemiologia no cumprimento desses princípios?Desde sua origem como disciplina científica, no cerne do pensamento epi¬ demiológico tem estado a avaliação do risco de adquirir e desenvolver doenças e agravos ΰ saúde e o estabelecimento de ''comparações'' para a identificação dos determinantes desses riscos.Comparações essas realizadas entre subconjuntos de sujeitos identificados por possuírem alguma característica capaz de distinguilos e individualizá-los, como grupo, no conjunto maior da população humana; portanto, comparações entre desiguais.oudiferentes (Almeida Filho, 1992).O fato de a Epidemiologia tomar o processo saúde-doença, em sua dimensão coletiva, como seu objeto de estudo e intervenção, confere-lhe particular instrumen tal idade na etapa de constituição do Estado Moderno, visto que a preservação da saúde da força de trabalho urbana e rural coloca-se como uma das principais neces sidades sociais nessa época (Mendes-Gonçalves, 1994).Entretanto, ao trabalhar com os diferenciais de saúde-doença nos variados grupos sociais, a Epidemiologia vκ-se imediatamente confrontada com os aspectos sociais, econτmicos e políticos da própria organização social e com o potencial de denúncia que os conhecimentos por ela produzidos trazem para o espaço público (Barata, 1990).Nesse processo de constituição da Epidemiologia, enquanto disciplina científica do campo da Saúde Coletiva e conjunto de práticas sociais voltadas para o controle de doenças e agravos ΰ saúde, as diferenças entre os grupos de sujeitos -cujas comparações estão na base da construção do pensamento epide¬ miológico -vão ganhando a conotação e o significado de desigualdades.Desi gualdades que remetem ΰ desproporcionalidade, parcialidade e injustiça.Esses sentidos da desigualdade terão desdobramentos diversos no interior da disciplina, dando origem a, pelo menos, duas correntes de pensamento: uma delas, mais ''naturalizada'', na qual os diferenciais serão tratados, na medida do possível, despidos de qualquer conotação social, cultural e política, como sim ples características biológicas e demográficas de conjuntos de organismos mais ou menos destacados de seu ambiente; outra, mais ''politizada'', na qual os diferenciais assumem a condição de desigualdades ou injustiças produzidas na estrutura so cial e refletidas no processo de adoecimento e morte dos sujeitos.Na verdade, mesmo a primeira das correntes acima mencionadas incorpora, em alguma medida, as questões sociais na explicação do processo saúde-doença.Ela o faz, principalmente, a partir do referencial da Sociologia funcionalista, valen do-se do conceito de estratificação social, enquanto a outra vertente baseia-se no materialismo histórico em suas diferentes formas de elaboração (Barreto, 1990).Aparentemente não há como a Epidemiologia eludir a questão da desigualda de, pois ela se encontra instalada no próprio cerne do objeto e do pensamento; entre tanto, o que irá distinguir as diferentes correntes de produção será a forma de en¬ frentamento que essa questão terá não só no nível teórico e metodológico, mas tam bém em relação ΰ praxis.Cabe perguntar de onde vem o potencial político da denúncia da desigual dade, isto é, o caráter ideológico que tal denúncia adquire em nossa sociedade.Por que a polκmica em torno da desigualdade?Não é perfeitamente esperado e natural a observação de que os sujeitos se diferenciam por uma série de caracte rísticas?De onde vem o espanto em face do desigual?Por que a demonstração da desigualdade assume ares de denúncia política?Na história da humanidade, todas as formas de organização social foram marcadas, com maior ou menor intensidade, pelas posições desiguais que os su jeitos ocuparam na estrutura social.Sejam castas, classes ou estratos demográfi cos, todas as formas de organização social contaram com grupos distintos em sua estrutura.Todas elas, porém, tinham justificativas no plano jurídico e políti co para as desigualdades existentes, fossem elas baseadas na condição de nasci mento, na autoridade da Igreja ou em outro critério qualquer.Apenas as sociedades capitalistas ocidentais afirmaram, como princípio no plano político e jurídico, a igualdade de todos os cidadãos, independentemente das condições de nascimento ou da posição efetivamente ocupada na estrutura social.O lema da Revolução Francesa, adotado como paradigma das revoluções burguesas, afirma os valores ''Liberdade, Igualdade e Fraternidade'' como aqueles capazes de garantir o predomínio da Razão e a libertação da humanidade de todos os precon ceitos, crenças e mitos que impediram o desenvolvimento pleno das potencialidades humanas até o advento do Século das Luzes.Dado que a organização social capitalista não possibilita a concretização dessa igualdade apregoada, surge a brecha para que a questão da desigualdade apareça revestida de forte potencial de denúncia.Não fosse a contradição entre a realidade concreta dos sujeitos e a ideologia, não haveria motivos para o ''espan¬ to'' nem para todas as tentativas que são feitas no sentido de esvaziar a desigual dade do seu conteúdo político.Diante da existκncia concreta das desigualdades presentes no processo saúde-doença e dada a politização inerente a toda explicitação desse fato, resta ΰ Epidemiologia enfrentar a questão, quer seja do ponto de vista da produção do conhecimento, quer na elaboração e implementação das propostas de interven ção decorrentes.Considerando que a parcela dos que optam por tratar a desigualdade de maneira ''naturalizada'' -portanto, esvaziada de seu conteúdo político -não lo gra resolver ou superar a questão, devemos colocar o foco de atenção nas alter nativas que se apresentam, do ponto de vista teórico, para aqueles que preten dem tomar a existκncia de desigualdades sociais como ponto de partida da refle xão sobre a saúde e a doença.Podemos identificar duas correntes de pensamento majoritárias no que se refere ao tratamento teórico da desigualdade no βmbito das investigações epide¬ miológicas.Há uma parcela importante dessa produção na qual a desigualdade é enfocada através da teoria da estratificação social, enquanto outra parcela adota a perspectiva da estrutura de classes.As teorias de estratificação social tratam a desigualdade de um ponto de vista predominantemente quantitativo, ou seja, estabelecendo pontos de cortes em variáveis cujas gradações representam um contínuo de situações possíveis, resultando assim na classificação de indivíduos e grupos sociais em estratos altos, intermediários e baixos.Os estratos são cate gorias eminentemente descritivas, que permitem a comparação entre posições re lativas -do tipo mais ou menos (Stavenhagen, 1974).Sua construção está ba seada na utilização de variáveis individuais tomadas como indicadoras de condi ção social, tais como renda, escolaridade, áreas residenciais, escalas de prestígio etc.; ou na elaboração de índices compostos, nos quais diversas variáveis podem es tar incluídas apenas de maneira agregada ou sob a forma de esquema hierárquico (SEADE, 1992).A categoria classe social, por sua vez, é analítica e histórica, isto é, mos tra-se com capacidade explicativa e como portadora de conteúdo concreto espe cífico para cada momento histórico.Está baseada em critérios estruturais-fun¬ cionais relativos ΰ posição que os grupos ocupam na organização social.Tal po sição é definida a partir do lugar na produção social, das relações com os meios de produção, papel na organização social e relações de dominação/subordinação (Stavenhagen, 1974).Portanto, a adoção de m', '["health equity","right to health","social determinants of health","health disparities","public health","history of epidemiology","health as a public good"]', '10.7476/9788575412640', '9788575412640', 'https://books.scielo.org/id/3y5xk', 'https://books.scielo.org/id/3y5xk/pdf/barata-9788575412640.pdf', NULL, 'https://books.scielo.org/id/3y5xk/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3y8yz', '3y8yz', 'Plágio: palavras escondidas', NULL, '["Débora Faria Diniz","Ana Terra"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra faz uma etnografia do plágio – as autoras perseguiram textos de controvérsia, histórias de investigação em comitês internacionais e sítios de trabalhos prontos. Buscaram as vozes dos autores e plagiadores. Passearam pela arte e pela literatura, e não só pelas letras acadêmicas. O livro é isso tudo e um pouco mais: bem-humorado e elegante, desafia as fórmulas prontas que descrevem o plágio como crime capital intelectual. O plágio é um malfeito que abala a integridade acadêmica, mas é preciso devolvê-lo ao campo pedagógico. Esse é um dos xeques-mates lançados pelo livro. Um livro indispensável para leitores e escritores, professores e estudantes.', '["plagiarism","academic integrity","intellectual property","academic misconduct","art and literature"]', '10.7476/9788575414507', '9788598070377', 'https://books.scielo.org/id/3y8yz', NULL, NULL, 'https://books.scielo.org/id/3y8yz/cover/cover_thumbnail.jpeg', 184, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3yd', '3yd', 'Tempos de Vargas: o rádio e o controle da informação', NULL, '["Othon Jambeiro","Amanda Mota","Andrea Ribeiro","Clarissa Amaral","Cassiano Simões","Eliane Costa","Fabiano Brito","Sandro Rostelato Ferreira","Suzy dos Santos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Uma análise comparativa entre os campos da história, da política e do desenvolvimento sócio econômico através da associação entre a legislação da Era Vargas com o desenvolvimento técnico e social das mídias. A obra, resultado da autoria de jornalistas, publicitários, sociólogos e pesquisadores é marcada pelo ponto de vista eclético e minucioso que descreve desde o nascimento da radiofusão no Brasil, as mudanças ocorridas durante a Constituição de 1934, o Estado Novo, o pós-guerra e na instauração da democracia no país. Um registro que colabora para a acessibilidade de dados históricos e de imensa importância para aqueles que nutrem paixão por este meio de comunicação que marcou a história das mídias por seu pioneirismo e seu poder de influência no Brasil e no mundo.', '["radio broadcasting history","Vargas era","radio regulation","information control","Estado Novo","democratic transition","media development","Brazilian radio"]', '10.7476/9788523212414', '9788523212414', 'https://books.scielo.org/id/3yd', 'https://books.scielo.org/id/3yd/pdf/jambeiro-9788523212414.pdf', NULL, 'https://books.scielo.org/id/3yd/cover/cover_thumbnail.jpeg', NULL, 11, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3ydzn', '3ydzn', 'O Instituto de Biologia conta suas histórias', NULL, '["Medeiros, Adriana Oliveira","Sá, Thiago Serravalle de","Bellintani, Moema Cortizo","Santos, Eliene Gabriel de Souza","Oliviera, Cristiane Pereira"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste livro, o(a) leitor(a) encontra um apanhado de histórias em que professores(as), técnicos(as) e estudantes de graduação e pós-graduação do Instituto de Biologia da Universidade Federal da Bahia (UFBA) contam sobre suas linhas de pesquisa e seus últimos achados científicos, utilizando uma linguagem acessível às crianças e aos adultos. As histórias trazem saberes sobre plantas, microrganismos e animais. Falam sobre os biomas baianos, rios e mares. Trazem também a relação da humanidade com o meio ambiente e como tudo está conectado. O livro apresenta, por meio de Qrcode, acesso a vídeos nos quais cada uma das histórias é contada e legendada em português e em Língua Brasileira de Sinais.', '["science communication","popular science","plants","microorganisms","animals","Brazilian biomes","human-environment relationship","Brazilian Sign Language (Libras)"]', '10.7476/9786556308913', '9786556306575', 'https://books.scielo.org/id/3ydzn', 'https://books.scielo.org/id/3ydzn/pdf/medeiros-9786556308913.pdf', NULL, 'https://books.scielo.org/id/3ydzn/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3yrrb', '3yrrb', 'Adolpho Lutz Sumário – Glossário - Índices - v.1, Suplemento', NULL, '["Jaime Larry Benchimol","Magali Romero Sá"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2004, '2004-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Beobachtungen über die Cladoceren der Umgegend von Leipzig, Observações sobre os cladóceros dos arredores de Leipzig, p. 261-65 [Observations on Cladocera on the Outskirts of Leipzig]Observações Publicado originalmente em Sitzungsberichte der Naturforschenden Gesellschaft zu Leipzig, v.5, n.4-9, p.36-41. Resumo/AbstractComunicação apresentada à Sociedade de Ciências Naturais de Leipzig.Relata as conclusões de investigação incompleta realizada nos meses de outubro e novembro de 1877 e no decorrer do verão de 1878.Inclui relação das espécies de cladóceros observadas, suas variedades e os locais onde foram encontradas.Em alguns casos, menciona a época de aparecimento dos machos.Communication presented to Leipzig''s Natural Sciences Society.It displays the conclusions of the investigation that took place in October-November 1877 and in the summer of 1878.It also lists the Cladocera species that were observed, their varieties and the locations where they were found.In some cases, it mentions the period when males show up to mate.1879 Untersuchungen über die Cladoceren der Umgebung von Bern, p.269-77 Investigações sobre os cladóceros da região de Berna, p.279-88 [Investigating Cladocera in the city of Bern and outskirts] Observações Publicado originalmente em Mitteilungen der Naturforschenden Gesellschaft in Bern.p.38-54.Resumo/Abstract Comunicação apresentada à Sociedade de Ciências Naturais de Berna.Relaciona as 42 espécies de cladóceros observadas e as localidades onde foram encontradas, destacando as variações de forma não descritas em trabalhos anteriores.Conclui que, de maneira geral, a fauna investigada apresentava grande similitude com as de outras regiões, estando inserida numa grande área zoológica que cobria toda a Europa Central e Ocidental.1880 Ein Fall von acuter fibrinöser Bronchitis, p.293-96 Um caso de bronquite fibrinosa aguda, p.297-300 [A Case of Acute Fibronous Bronchitis] Observações Publicado originalmente em Correspondenz-Blatt für schweizer Aerzte, v.10, n.15, p.488-91. Resumo/AbstractRelatório escrito por Lutz na qualidade de médico assistente do Hospital Cantonal de St. Gallen.Descreve a evolução clínica de um caso de bronquite fibrinosa aguda, analisando o quadro clínico anterior da paciente e o primeiro diagnóstico: bronquite crupal ou alguma doença diftérica primária das vias aéreas.Lutz avalia o tratamento adotado e sugere como melhor terapêutica preparados à base de quebracho e o estímulo à expectoração através de substância emética.Report written by Lutz as assistant doctor at St. Gallen Canton Hospital.It describes the clinical evolution of a case of acute fibronous bronchitis and analyzes the previous general health reports on the patient and the first diagnosis: croupassociated bronchitis or a kind of primary diphtheria.Lutz analyzes the procedures taken and suggests a more efficient treatment, prepared with quebracho (a South American plant), as well as the use of emetic substances to help expectoration.', '["Cladocera","Crustacea","freshwater zooplankton","species checklist","Leipzig","Bern","male emergence","zoogeographical distribution"]', '10.7476/9788575412350', '9788575412350', 'https://books.scielo.org/id/3yrrb', 'https://books.scielo.org/id/3yrrb/pdf/benchimol-9788575412350.pdf', NULL, 'https://books.scielo.org/id/3yrrb/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3zcft', '3zcft', 'Avaliação em saúde: dos modelos conceituais à prática na análise da implantação de programas', NULL, '["Zulmira Hartz"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1997, '1997-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Emerge da convicção sobre a efetividade possível das ações programáticas para evitar ou reduzir o sofrimento causado pelos problemas de saúde. Reúne especialistas brasileiros e canadenses para discutir conceitos e métodos da avaliação na saúde, valendo-se, como exemplo, de desenho metodológico na implantação de um programa em sistemas locais de saúde no Nordeste brasileiro. Com texto fluente e atual, a coletânea incita a transpor a "tradição" do planejamento, diferenciando conceitos de avaliação normativa e pesquisa avaliativa, para favorecer o conhecimento das práticas em saúde na pesquisa-ação sobre serviços.', '["health program evaluation","program implementation","normative evaluation","evaluation research","action research","health services","local health systems","program planning","Northeast Brazil"]', '10.7476/9788575414033', '9788575414033', 'https://books.scielo.org/id/3zcft', 'https://books.scielo.org/id/3zcft/pdf/hartz-9788575414033.pdf', NULL, 'https://books.scielo.org/id/3zcft/cover/cover_thumbnail.jpeg', NULL, 89, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3zd6q', '3zd6q', 'Ateliês de Pesquisa: formação de professores(as)-pesquisadores(as) e métodos de pesquisa em educação', NULL, '["Ana Lúcia Gomes da Silva","Váldina Gonçalves da Costa","Diego Carlos Pereira"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro é resultado de encontros acadêmicos gestados em rede colaborativa que transcenderam a “expressão reta”, instados pela preocupação com a pesquisa em educação e, consequentemente, com a formação de professores(as)-pesquisadores(as). Em todo o mundo, é crescente a necessidade de pensar aspectos teórico-metodológicos na pesquisa em educação. É preciso, ainda, reconhecer a educação como área repleta de territorializações, desterritorializações e reterritorializações, em permanente movimento.', '["research workshop","teacher-researcher training","research methods in education","educational research","territorialization of education","reterritorialization"]', '10.7476/9786588211373', '9786588211021', 'https://books.scielo.org/id/3zd6q', 'https://books.scielo.org/id/3zd6q/pdf/silva-9786588211373.pdf', 'https://books.scielo.org/id/3zd6q/epub/silva-9786588211373.epub', 'https://books.scielo.org/id/3zd6q/cover/cover_thumbnail.jpeg', 197, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-3zhhw', '3zhhw', 'Revisitando o território fluminense, VI', NULL, '["Glaúcio José Marafon","Miguel Ângelo Ribeiro"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Apresentação P assados 13 anos desde a primeira publicação da coletânea intitulada Revisitando o Território Fluminense, organizada no âmbito do Núcleo de Geografia Fluminense (NEGEF) do Instituto de Geografia -UERJ, sob a coordenação do professor Glaucio José Marafon e com a colaboração do professor Miguel Angelo Ribeiro, apresentamos este novo volume, no qual convidamos pesquisadores doutores de outras instituições e profissionais que acabaram de concluir suas pesquisas em níveis de mestrado e doutorado, com temáticas variadas, tendo como recorte espacial o estado do Rio de Janeiro.O território fluminense abarca uma gama de singularidades que se imbricam, contemporaneamente, com os eventos em escalas nacional e global, o que proporciona reflexões, análises e discussões de diferentes abordagens e propósitos.No bojo de tais singularidades, os 16 artigos que compõem esta obra apresentam situações das mais diferentes ordens, desde aquelas vinculadas ao poder econômico e aos investimentos externos, até justiça por cidades mais habitáveis, produção energética, espaço rural fluminense associado à agricultura familiar e às suas relações com a atividade turística; além de questões regionais, expansão da metrópole carioca em direção à Zona Oeste, com novos investimentos, cartografia da ação social, transformações socioeconômicas de municípios localizados em diferentes regiões de governo com implicação em suas sedes, importância da mobilidade turística, espetacularização do lazer e importância da mobilidade populacional em decorrência de novos projetos que visem ao desenvolvimento econômico do território fluminense.', '["urban expansion","Zona Oeste","family farming","rural space","tourism","energy production","regional government","economic power","external investment","habitability","human mobility","economic development"]', '10.7476/9788575114575', '9788575114575', 'https://books.scielo.org/id/3zhhw', 'https://books.scielo.org/id/3zhhw/pdf/marafon-9788575114575.pdf', NULL, 'https://books.scielo.org/id/3zhhw/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-42hrr', '42hrr', 'Gobierno electrónico en América Latina: revisión y tendencias', NULL, '["Julián David Cortés-Sánchez","Diego Cardona"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este libro presenta los resultados de investigación del proyecto denominado “Evaluación del impacto de las Tecnologías de la Información y las Comunicaciones en las estructuras organizacionales - Caso Gobierno Electrónico en América Latina”, el cual fue financiado por Colciencias en el 2011 a través del Programa Nacional de Jóvenes Investigadores e Innovadores. El objetivo de esta investigación fue desarrollar un marco teórico sobre el nacimiento, el despliegue, la evaluación, y el futuro del Gobierno Electrónico –GE– en América Latina. En la primera sección, se especifica la delimitación del problema, los objetivos y las preguntas desde las cuales se focaliza esta investigación. Luego se aborda el marco conceptual necesario para contextualizar a los lectores sobre las dinámicas correspondientes a las Tecnologías de la Información y las Comunicaciones –TIC–, su impacto en la sociedad y su papel dentro del sector público. Posteriormente se analizan dos informes relacionados con la evaluación de las estrategias de GE implementadas internacionalmente: el de la Universidad de Brown y el de la Organización de las Naciones Unidas –ONU–. Luego se identifican cuáles fueron los inicios del GE en América Latina con relación a cumbres, acuerdos, compromisos y agendas internacionales. Después se realiza una introducción a la iniciativa Municipios Eficientes y Transparentes –MuNet– de la Organización de los Estados Americanos –OEA–. Con base en los países participantes en la fase II del programa MuNet, se determina la muestra de países que se van a evaluar con relación a sus avances en estrategias de GE y la lucha contra la corrupción. Esta evaluación emplea como insumos dos fuentes principales: el informe de GE de la ONU y el Índice de Percepción de Corrupción de Transparencia Internacional. Posteriormente se presentan las tendencias internacionales del GE. Por último se exponen las conclusiones halladas a lo largo de esta investigación.', '["e-government","Latin America","information and communication technologies","public sector","e-government evaluation","e-government strategy","Organization of American States"]', '10.7476/9789587386400', '9789587386394', 'https://books.scielo.org/id/42hrr', NULL, NULL, 'https://books.scielo.org/id/42hrr/cover/cover_thumbnail.jpeg', 114, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-43w9y', '43w9y', 'Monteiro Lobato: um estudo de A chave do tamanho', NULL, '["Thiago Alves Valente"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro, Thiago Alves Valente faz um percurso panorâ­mico e histórico da fortuna crítica de A chave do tamanho, de Monteiro Lobato, configurando um quadro por cujas lacunas pretende caminhar. Ao organizar os vários estudos críticos por eixos temáticos (ideologia, pensamento filosófico, cientificismo, questões estéticas), o autor constata que há a “necessidade de empreender uma análise textual em que os elementos estrutu­rais da narrativa possam ser compreendidos sem sua funcionali­dade na construção da obra”. Com esse intuito, Valente realiza um confronto entre as modificações feitas por Monteiro Lobato nas várias edições do livro para, em seguida, apresentar com rara originalidade sua crí­tica desse texto lobatiano, comprovando, por meio de elementos que estruturam a narrativa, de que modo os temas centrais da obra de Lobato estão articulados na criação literária.', '["Monteiro Lobato","critical reception","text analysis","editions","ideology","philosophical thought","scientism","aesthetics","Brazilian children''s literature"]', '10.7476/9786557145319', '9786557145319', 'https://books.scielo.org/id/43w9y', 'https://books.scielo.org/id/43w9y/pdf/valente-9786557145319.pdf', NULL, 'https://books.scielo.org/id/43w9y/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-447g2', '447g2', 'Medicamentos no Brasil: inovação e acesso', NULL, '["Paulo Marchiori Buss","José da Rocha Carvalheiro","Carmen Nila Phang Romero Casas"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Uma das particularidades da área da saúde é pertencer tanto à esfera social quanto à industrial, característica que representa oportunidades e grandes desafios. O livro Medicamentos no Brasil: inovação e acesso tem o objetivo de fomentar o desenvolvimento tecnológico e fortalecer a produção nacional, além de garantir que o conhecimento desses avanços beneficie a população brasileira. Como afirma o ministro da Saúde, José Gomes Temporão, no prefácio: “...inovação não pode estar desligada da idéia de acesso”. Reunindo os pontos de vista da academia, governo e setor produtivo público e privado, com abordagens que privilegiam o contexto nacional e refletem sobre a posição brasileira no cenário internacional, a obra apresenta um diagnóstico da área de medicamentos no país, avalia seus problemas e potencialidades e faz recomendações concretas para superação dos obstáculos e aproveitamento das oportunidades. Cabe destacar que é o segundo volume de uma série sobre pesquisa, desenvolvimento e inovação nos segmentos industriais da saúde, do Projeto Inovação em Saúde (presidência/Fiocruz), cujo primeiro livro é Vacinas, Soros e Imunizações no Brasil.', '["pharmaceutical industry","pharmaceutical innovation","access to medicines","technological progress","healthcare innovation","Brazil","public and private sector","health policy"]', '10.7476/9788575415979', '9788575415979', 'https://books.scielo.org/id/447g2', 'https://books.scielo.org/id/447g2/pdf/buss-9788575415979.pdf', NULL, 'https://books.scielo.org/id/447g2/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-44wdr', '44wdr', 'História da filosofia moderna', NULL, '["Regina Silva"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta obra é um manual que estuda os principais pensadores do período iniciado no fim do século XIV (morte de Petrarca) e que se estende à metade do século XIX. Portanto, vai do Humanismo-Renascimento (cap.1) a Hegel (cap. 27), abrangendo boa parte do programa de filosofia para o ensino médio e o conteúdo de várias disciplinas dos cursos de graduação em filosofia. Apresenta, além disso, roteiros inéditos de pesquisa, como: as disciplinas e o programa de estudos das escolas na Europa moderna, explicitando a formação dos filósofos dessa época; a modalidade de comunicação – correspondência, academias, círculos científicos – entre os pensadores dos diversos países europeus; as questões e os conceitos filosóficos mais recorrentes, como atomismo, jusnaturalismo, ratio studiorum, liberalismo, idealismo alemão. A obra contribui para a formação em sentido amplo, pois, além de oferecer as informações mais importantes sobre os pensadores do período moderno, é capaz de despertar o interesse dos estudantes na medida em que é também um excelente guia para a iniciação científica.', '["modern philosophy","history of philosophy","humanism","Renaissance","Hegel","philosophy education","academies","scientific circles","atomism","natural law","Ratio Studiorum","liberalism"]', '10.7476/9788526816619', '9788526815285', 'https://books.scielo.org/id/44wdr', NULL, NULL, 'https://books.scielo.org/id/44wdr/cover/cover_thumbnail.jpeg', 734, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-452n9', '452n9', 'Cartas imaginarias a Freud y otros ensayos', NULL, '["Alberto Fergusson"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Las cinco cartas imaginarias a Freud recogidas en este libro son su columna vertebral y los efectos que producirán en la comunidad psicoanalítica están aún por verse. Pero las cartas no agotan los aportes de esta obra. Alberto Fergusson, médico, psiquiatra y psicoanalista, tiene toda una historia vital dedicada al estudio y el tratamiento de pacientes psicóticos. En los años ochenta creó una institución que bautizó Fungrata, inspirada en las premisas del freudomarxismo de la Escuela de Frankfurt y en el mal llamado “movimiento antipsiquiátrico” (mal llamado en la medida en que no se opone a la psiquiatría, sino más bien a una mala práctica psiquiátrica) y en los trabajos y experiencias de Laing, Cooper, Basaglia y Szasz. Fungrata, institución pionera en nuestro país, sigue produciendo asombro en varias partes del mundo por haber llegado, desde ya hace décadas, adonde muchos otros dispositivos dedicados a la intervención psicosocial con pacientes psicóticos hoy aspiran llegar.', '["psychoanalytic community","psychoanalytic literary criticism","antipsychiatry","Frankfurt School","Freudian Marxism","psychiatric hospitals","psychosocial interventions","psychotic patients","La Granja","self-rehabilitation"]', '10.7476/9789587385915', '9789587385908', 'https://books.scielo.org/id/452n9', NULL, NULL, 'https://books.scielo.org/id/452n9/cover/cover_thumbnail.jpeg', 204, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-45qyc', '45qyc', 'Os partidos e o regime: a lógica do processo eleitoral brasileiro', NULL, '["Fábio Wanderley Reis"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os autores reunidos neste volume vêm há algum tempo estudando a problemática dos partidos políticos, do processo político-eleitoral, e das alternativas institucionais que se abrem diante do atual regime brasileiro.', '["political parties","electoral process","party system","electoral institutions","institutional alternatives","Brazilian politics"]', '10.7476/9788599662960', '9788599662960', 'https://books.scielo.org/id/45qyc', 'https://books.scielo.org/id/45qyc/pdf/lamounier-9788599662960.pdf', NULL, 'https://books.scielo.org/id/45qyc/cover/cover_thumbnail.jpeg', NULL, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-45vyc', '45vyc', 'Doenças Endêmicas: abordagens sociais, culturais e comportamentais', NULL, '["Rita Barradas Barata","Roberto Briceño-León"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2000, '2000-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'No mundo, cerca de meio bilhão de pessoas sofrem de enfermidades parasitárias endêmicas. Na América Latina, ainda se convive com velhas endemias como esquistossomose, malária, leshmanioses e hanseníase. A solução? Construir, de maneira solidária, o campo da saúde coletiva. Reunindo artigos de 35 conceituados pesquisadores latino-americanos, Doenças Endêmicas aproxima as abordagens teórico-metodológicas das ciências sociais e da epidemiologia. Certamente será útil para todos os profissionais interessados em desenvolver estratégias alternativas na formulação, implementação e avaliação de programas de controle de endemias.', '["endemic disease","parasitic infection","schistosomiasis","malaria","leishmaniasis","leprosy","collective health","Latin America"]', '10.7476/9788575413944', '9788575413944', 'https://books.scielo.org/id/45vyc', 'https://books.scielo.org/id/45vyc/pdf/barata-9788575413944.pdf', NULL, 'https://books.scielo.org/id/45vyc/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-45y8h', '45y8h', 'Representações midiáticas da saúde', NULL, '["Igor Pinto Sacramento","Wilson Couto Borges"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Para o campo de estudos sobre saúde, vem sendo cada vez mais importante refletir sobre o lugar que a mídia ocupa nas configurações de representações de saúde e doenças, bem como dos indivíduos saudáveis e doentes, dos corpos e das práticas corporais, dos modelos de prevenção e de promoção, dos processos de medicalização, dos fatores de risco e dos pânicos sanitários. As representações são parte de práticas sociais mais amplas que nos localizam, nos identificam, nos diferenciam, nos conectam e nos afastam. É nesse âmbito que os autores, com este livro, buscam estimular estudos sobre as representações midiáticas sobre processos de saúde e doença. A percepção dos autores, dessa forma, é a de que as representações midiáticas têm, sem dúvidas, efeitos profundos em todos as formas de organização da vida social, até mesmo na produção e reprodução de identidades, diferenças, afecções, moralidades, empatias, repulsas e pânicos. As consequências e o poder das representações são intensos, uma vez que elas se tornam campos de batalha para lutas pelo sentido nas sociedades, no interior das quais se disputa estabelecer o que é considerado aceitável, indizível, punível, normal, patológico, saudável, belo e assim por diante.', '["medicalization","health promotion","disease prevention","health risk factors","social identity"]', '10.7476/9786557080894', '9786557080283', 'https://books.scielo.org/id/45y8h', NULL, NULL, 'https://books.scielo.org/id/45y8h/cover/cover_thumbnail.jpeg', 180, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
